function syncMemberNutritionPrescription(athId, forcedData = null) {
    let data = forcedData;
    if (!data) {
        if (AppState.profile && AppState.profile.prescribed_nutrition && typeof AppState.profile.prescribed_nutrition === 'object') {
            if (!isCurrentUserAdmin() || AppState.profile.id === athId) {
                data = AppState.profile.prescribed_nutrition;
            }
        }
        if (!data && window.__coachAthletesCache) {
            const cached = window.__coachAthletesCache.find(a => a.id === athId);
            if (cached && cached.prescribed_nutrition) data = cached.prescribed_nutrition;
        }
    }
    if (!data) {
        const raw = localStorage.getItem(`sens_prescribed_nutrition_${athId}`);
        if (raw) {
            try { data = JSON.parse(raw); } catch (e) {}
        }
    }

    if (!data) {
        if (!athId.startsWith('mock_') && athId !== 'usr-vip-001' && athId !== 'usr-onl-003') {
            data = {
                target_calories: 2000,
                target_protein: 150,
                target_carbs: 200,
                target_fats: 65,
                target_water: 2.5,
                directive_note: 'Pauta en preparación por Nico. Priorizá hidratación constante y alimentos de alta densidad nutricional.',
                prescribed_foods: []
            };
        } else {
            data = {
                target_calories: 2200,
                target_protein: 160,
                target_carbs: 220,
                target_fats: 70,
                target_water: 2.5,
                directive_note: 'Priorizá llegar a tu meta de proteína diaria repartida en las comidas principales y mantener hidratación constante antes de entrenar.',
                prescribed_foods: [
                    { id: 'fd-p1', name: 'Pechuga de Pollo / Pavo', grams: 200, cal: 330, protein: 62 },
                    { id: 'fd-p2', name: 'Huevos de Campo Enteros', grams: 120, cal: 172, protein: 15 },
                    { id: 'fd-c1', name: 'Avena Tradicional Arrollada', grams: 80, cal: 311, protein: 11 },
                    { id: 'fd-c2', name: 'Arroz Yamani / Integral', grams: 150, cal: 168, protein: 3.9 }
                ]
            };
        }
    }

    // 1. Elementos de Pauta del Entrenador
    const kcalEl = document.getElementById('nutriPrescribedKcal');
    const noteEl = document.getElementById('nutriPrescribedCoachNote');
    const foodsGrid = document.getElementById('nutriPrescribedFoodsGrid');

    if (kcalEl) {
        if (data.target_calories) {
            kcalEl.innerHTML = `${data.target_calories.toLocaleString('es-AR')} <span style="font-size: 1.1rem; color: var(--text-secondary); font-weight: 400;">kcal / día</span>`;
        } else {
            kcalEl.innerHTML = `- <span style="font-size: 1.1rem; color: var(--text-secondary); font-weight: 400;">kcal / día</span>`;
        }
    }
    if (noteEl && data.directive_note) noteEl.textContent = `"${data.directive_note}"`;

    // 2. Elementos del Hero de Nutrición (Samsung Health Target)
    const targetKcalEl = document.getElementById('nutriTargetKcal');
    const optimalRangeEl = document.getElementById('nutriOptimalRangeText');
    const maxKcalLabel = document.getElementById('nutriMaxKcalLabel');
    const carbsGramsEl = document.getElementById('nutriCarbsGrams');
    const fatsGramsEl = document.getElementById('nutriFatsGrams');
    const protGramsEl = document.getElementById('nutriProtGrams');

    const targetKcal = data.target_calories || 2000;
    const targetProt = data.target_protein || 150;
    const targetCarbs = data.target_carbs || 200;
    const targetFats = data.target_fats || 65;

    if (targetKcalEl) targetKcalEl.textContent = `${targetKcal.toLocaleString('es-AR')} kcal`;
    if (optimalRangeEl) optimalRangeEl.textContent = `${Math.round(targetKcal * 0.9).toLocaleString('es-AR')} - ${Math.round(targetKcal * 1.1).toLocaleString('es-AR')}`;
    if (maxKcalLabel) maxKcalLabel.textContent = `${Math.round(targetKcal * 1.3).toLocaleString('es-AR')}`;

    if (carbsGramsEl) carbsGramsEl.innerHTML = `${targetCarbs}<span style="font-size: 12px; font-weight: 500; color: var(--text-muted);">g</span>`;
    if (fatsGramsEl) fatsGramsEl.innerHTML = `${targetFats}<span style="font-size: 12px; font-weight: 500; color: var(--text-muted);">g</span>`;
    if (protGramsEl) protGramsEl.innerHTML = `${targetProt}<span style="font-size: 12px; font-weight: 500; color: var(--text-muted);">g</span>`;

    if (foodsGrid && Array.isArray(data.prescribed_foods)) {
        if (data.prescribed_foods.length === 0) {
            foodsGrid.innerHTML = '<span style="font-size: 12px; color: var(--text-muted);">Estructurá tus comidas con los alimentos del banco base más abajo.</span>';
        } else {
            let html = '';
            data.prescribed_foods.forEach(f => {
                html += `
                    <div style="background: rgba(229, 203, 167, 0.08); border: 1px solid rgba(229, 203, 167, 0.3); border-radius: 8px; padding: 6px 12px; display: inline-flex; align-items: center; gap: 8px;">
                        <span style="font-size: 12.5px; font-weight: 700; color: #FFFFFF;">${f.name}</span>
                        <span class="pill pill-champagne" style="font-size: 10px; padding: 2px 6px;">${f.grams}g (${f.cal} kcal)</span>
                        <button type="button" class="btn btn-outline btn-sm btn-quick-add-prescribed" data-food-id="${f.id}" data-grams="${f.grams}" style="padding: 2px 6px; font-size: 10px; border-color: rgba(255,255,255,0.2);">+ Sumar hoy</button>
                    </div>
                `;
            });
            foodsGrid.innerHTML = html;

            foodsGrid.querySelectorAll('.btn-quick-add-prescribed').forEach(btn => {
                btn.addEventListener('click', () => {
                    const foodId = btn.getAttribute('data-food-id');
                    const grams = parseInt(btn.getAttribute('data-grams'), 10) || 100;
                    const food = FOOD_CATALOG.find(x => x.id === foodId);
                    if (food) {
                        const cal = Math.round((grams * (food.calPer100 || 0)) / 100);
                        const prot = Math.round(((grams * (food.protPer100 || 0)) / 100) * 10) / 10;
                        if (!AppState.dailyNutrition) AppState.dailyNutrition = { calories: 0, protein: 0, carbs: 0, fats: 0 };
                        AppState.dailyNutrition.calories += cal;
                        AppState.dailyNutrition.protein += prot;
                        localStorage.setItem('sens_daily_nutrition', JSON.stringify(AppState.dailyNutrition));
                        updateDashboardRings();
                        showSensToast(`${food.name} (${grams}g) sumado a tu total de hoy (+${cal} kcal).`, 'success', 3000);
                    }
                });
            });
        }
    }

    // Sincronizar Sección Dinámica de Pauta Nutricional & 500 Alimentos Clínicos
    renderMemberNutritionPlan(athId, AppState.nutriSelectedDate || AppState.selectedDate || new Date());
    if (typeof renderNutriDaysNav === 'function') renderNutriDaysNav();
    initUserNutritionFilterAndDateListeners();
    initUserFoodDetailModal();
    if (typeof initUserFoodSwapModal === 'function') initUserFoodSwapModal();
    if (typeof initUserShoppingListModal === 'function') initUserShoppingListModal();
    initUserCustomMealModal(athId);
    if (typeof initCalendarSwipeGestures === 'function') initCalendarSwipeGestures();
}

/**
 * =============================================================================
 * SECCIÓN DE RECOMENDACIÓN NUTRICIONAL DEL ATLETA & MASTER 500 FOODS
 * =============================================================================
 */
let userActiveNutriMealSlot = 'desayuno';
let userActiveFoodForDetail = null;
let userCustomTrayItems = [];

/**
 * Determina equivalencia de porción por unidad (huevos, frutas, rodajas, etc.)
 */
function getFoodUnitInfo(food) {
    if (!food) return { hasUnit: false, unitName: 'u', gramsPerUnit: 100, defaultUnits: 1 };
    const str = (food.unidades_caseras_total || food.portion || '').trim();
    const name = (food.name || food.nombre_alimento_o_plato || food.name_es || '').trim();
    const baseG = Number(food.porcion_total_g_ml || food.baseGrams || food.defaultGrams || food.grams || 100) || 100;
    const pesoUnidad = Number(food.peso_unidad_g) || 0;

    // Si la base de datos v2 provee peso_unidad_g directamente
    if (pesoUnidad > 0) {
        let unitWord = 'u';
        if (str) {
            const m = str.match(/^(\d+(?:\.\d+)?(?:\s*a\s*\d+(?:\.\d+)?)?)\s+([a-záéíóúñ]+)/i);
            if (m && m[2] && m[2].length > 1) {
                const invalid = ['de', 'en', 'con', 'del', 'al', 'para', 'o', 'por'];
                if (!invalid.includes(m[2].toLowerCase())) unitWord = m[2].toLowerCase();
            }
        }
        if (unitWord === 'u' && /huevo/i.test(name)) unitWord = 'huevos';
        if (unitWord === 'u' && /galleta/i.test(name)) unitWord = 'galletas';
        if (unitWord === 'u' && /feta/i.test(name)) unitWord = 'fetas';
        if (unitWord === 'u' && /tostada/i.test(name)) unitWord = 'tostadas';
        if (unitWord === 'u' && /plato|bowl|porcion|porción/i.test(str)) unitWord = 'porción';

        const defUnits = Math.max(0.5, Math.round((baseG / pesoUnidad) * 10) / 10);
        return {
            hasUnit: true,
            unitName: unitWord,
            gramsPerUnit: pesoUnidad,
            defaultUnits: defUnits
        };
    }

    // Helper para normalizar fracciones unicode habituales
    const cleanStr = str
        .replace(/½/g, '0.5')
        .replace(/¾/g, '0.75')
        .replace(/¼/g, '0.25')
        .replace(/⅓/g, '0.33')
        .replace(/⅔/g, '0.67');

    // 1. Intentar parsear unidades caseras descriptivas de la base de datos de 500 alimentos
    // Ejemplos: '1 pechuga mediana cocida (150 g)', '2 huevos grandes (100 g)', '1 omelette (380 g)', '2 tostones grandes (380 g)', '4 a 5 fetas gruesas (100 g)'
    if (cleanStr) {
        // Regex para capturar cantidad (num o rango ej '4 a 5'), palabra de unidad, y total en gramos si existe
        const match = cleanStr.match(/^(\d+(?:\.\d+)?(?:\s*a\s*\d+(?:\.\d+)?)?)\s+([a-záéíóúñ]+)/i);
        if (match) {
            let countStr = match[1];
            let count = 1;
            if (countStr.includes('a')) {
                const parts = countStr.split('a').map(p => parseFloat(p.trim())).filter(n => !isNaN(n));
                count = parts.length === 2 ? (parts[0] + parts[1]) / 2 : (parts[0] || 1);
            } else {
                count = parseFloat(countStr) || 1;
            }

            let unitWord = match[2].toLowerCase().trim();

            // Descartar conectores o preposiciones accidentales
            const invalidWords = ['de', 'en', 'con', 'del', 'al', 'para', 'o', 'por'];
            if (!invalidWords.includes(unitWord) && unitWord.length > 1) {
                // Normalizar palabras compuestas
                if (unitWord === 'pan' && (cleanStr.toLowerCase().includes('pan pita') || cleanStr.toLowerCase().includes('pan árabe') || cleanStr.toLowerCase().includes('árabe'))) {
                    unitWord = 'sándwich';
                }

                // Buscar gramos totales entre paréntesis ej: (150 g) o (100 g totales) o (120 g peso drenado)
                const gMatch = cleanStr.match(/\((\d+(?:\.\d+)?)\s*g/i);
                let totalG = gMatch ? parseFloat(gMatch[1]) : baseG;
                if (!totalG || totalG <= 0) totalG = baseG;

                const gramsPerUnit = Math.max(5, Math.round(totalG / count));

                return {
                    hasUnit: true,
                    unitName: unitWord,
                    gramsPerUnit: gramsPerUnit,
                    defaultUnits: count
                };
            }
        }
    }

    // 2. Coincidencias específicas por nombre cuando no hay unidades caseras estructuradas (ej. alimentos personalizados o creados a mano)
    const nameLower = name.toLowerCase();

    // Huevo puro (estrictamente si empieza con huevo o es huevo duro/poché, NUNCA platos compuestos con huevo)
    if (/^huevo(s)?\b/i.test(nameLower) || nameLower === 'huevo duro' || nameLower === 'huevo poché') {
        return { hasUnit: true, unitName: 'huevos', gramsPerUnit: 50, defaultUnits: 2 };
    }
    if (/^clara(s)?\b/i.test(nameLower)) {
        return { hasUnit: true, unitName: 'claras', gramsPerUnit: 33, defaultUnits: 4 };
    }
    if (nameLower.includes('banana')) {
        return { hasUnit: true, unitName: 'banana', gramsPerUnit: 120, defaultUnits: 1 };
    }
    if (nameLower.includes('manzana')) {
        return { hasUnit: true, unitName: 'manzana', gramsPerUnit: 150, defaultUnits: 1 };
    }
    if (nameLower.includes('medallón') || nameLower.includes('medallon')) {
        return { hasUnit: true, unitName: 'medallón', gramsPerUnit: 100, defaultUnits: 1 };
    }
    if (nameLower.includes('feta') || nameLower.includes('rebanada')) {
        return { hasUnit: true, unitName: 'fetas', gramsPerUnit: 30, defaultUnits: 2 };
    }
    if (nameLower.includes('rodaja')) {
        return { hasUnit: true, unitName: 'rodajas', gramsPerUnit: 35, defaultUnits: 2 };
    }
    if (nameLower.includes('scoop')) {
        return { hasUnit: true, unitName: 'scoop', gramsPerUnit: 30, defaultUnits: 1 };
    }
    if (nameLower.includes('lata')) {
        return { hasUnit: true, unitName: 'lata', gramsPerUnit: 120, defaultUnits: 1 };
    }
    if (nameLower.includes('omelette')) {
        return { hasUnit: true, unitName: 'omelette', gramsPerUnit: baseG || 350, defaultUnits: 1 };
    }
    if (nameLower.includes('wrap') || nameLower.includes('fajita')) {
        return { hasUnit: true, unitName: 'wrap', gramsPerUnit: baseG || 300, defaultUnits: 1 };
    }
    if (nameLower.includes('tostón') || nameLower.includes('toston')) {
        return { hasUnit: true, unitName: 'tostones', gramsPerUnit: Math.round(baseG / 2) || 150, defaultUnits: 2 };
    }
    if (nameLower.includes('tostada')) {
        return { hasUnit: true, unitName: 'tostadas', gramsPerUnit: Math.round(baseG / 2) || 150, defaultUnits: 2 };
    }

    if (cleanStr.includes('unidad') || cleanStr.includes('unidades')) {
        return { hasUnit: true, unitName: 'unidad', gramsPerUnit: baseG, defaultUnits: 1 };
    }

    return { hasUnit: true, unitName: 'porción', gramsPerUnit: baseG, defaultUnits: 1 };
}

window.getFoodUnitInfo = getFoodUnitInfo;

/**
 * Renderiza el calendario semanal de nutrición (id="nutriDaysNav")
 * con paridad total con Inicio y Entrenamiento
 */
function renderNutriDaysNav() {
    const container = document.getElementById('nutriDaysNav');
    if (!container) return;

    if (!AppState.activeWeekStart) {
        AppState.activeWeekStart = getMonday(new Date());
    }

    const rangeLabel = document.getElementById('sensNutriWeekRangeLabel');
    if (rangeLabel && typeof getWeekRangeLabel === 'function') {
        rangeLabel.textContent = getWeekRangeLabel(AppState.activeWeekStart);
    }

    const athId = (typeof getActiveAthleteId === 'function') ? getActiveAthleteId() : 'mock_vip';
    const dayNames = ['LUN', 'MAR', 'MIÉ', 'JUE', 'VIE', 'SÁB', 'DOM'];
    let html = '';

    for (let i = 0; i < 7; i++) {
        const dayDate = new Date(AppState.activeWeekStart);
        dayDate.setDate(AppState.activeWeekStart.getDate() + i);

        const isToday = isSameDay(dayDate, new Date());
        const isSelected = isSameDay(dayDate, AppState.nutriSelectedDate || AppState.selectedDate || new Date());
        const dayKey = 'day' + (i + 1);
        const heroNum = dayDate.getDate();

        const dateIso = `${dayDate.getFullYear()}-${String(dayDate.getMonth() + 1).padStart(2, '0')}-${String(dayDate.getDate()).padStart(2, '0')}`;
        const hasCustomMeals = Boolean(localStorage.getItem(`sens_user_logged_meals_${athId}_${dateIso}`));
        const hasAdjustments = Boolean(localStorage.getItem(`sens_user_adjusted_meals_${athId}_${dateIso}`));
        const hasConsumed = Boolean(localStorage.getItem(`sens_user_consumed_foods_${athId}_${dateIso}`));
        const isLogged = hasCustomMeals || hasAdjustments || hasConsumed;

        let badgeHtml = '';
        if (isLogged) {
            badgeHtml = `<span class="sens-day-badge done" title="Plan nutricional registrado">✓</span>`;
        } else if (isToday) {
            badgeHtml = `<span class="sens-day-badge today" title="Hoy">Hoy</span>`;
        } else {
            badgeHtml = `<span class="sens-day-badge rest" title="Pauta activa">–</span>`;
        }

        html += `
            <button type="button" class="sens-week-day-pill ${isSelected ? 'active' : ''} ${isToday ? 'is-today' : ''}" data-day-key="${dayKey}" data-date="${formatDateKey(dayDate)}">
                <span class="sens-day-name">${dayNames[i]}</span>
                <span class="sens-day-hero-num">${heroNum}</span>
                <div class="sens-day-modality-indicator">${badgeHtml}</div>
            </button>
        `;
    }

    container.innerHTML = html;

    container.querySelectorAll('.sens-week-day-pill').forEach((pill, idx) => {
        pill.addEventListener('click', () => {
            container.querySelectorAll('.sens-week-day-pill').forEach(p => p.classList.remove('active'));
            pill.classList.add('active');

            const dayDate = new Date(AppState.activeWeekStart);
            dayDate.setDate(AppState.activeWeekStart.getDate() + idx);
            AppState.selectedDate = dayDate;
            AppState.nutriSelectedDate = dayDate;
            const dayKey = 'day' + (idx + 1);
            AppState.currentDay = dayKey;

            renderMemberNutritionPlan(athId, dayDate);
            renderNutriDaysNav();
            if (typeof renderDynamicWeekStrip === 'function') renderDynamicWeekStrip();
            if (typeof renderWorkoutDaysNav === 'function') renderWorkoutDaysNav();
            if (typeof updateObjectiveCardData === 'function') updateObjectiveCardData(dayDate);
            if (typeof syncAllStreakAndPillTelemetry === 'function') {
                syncAllStreakAndPillTelemetry(dayDate);
            }
        });
    });
}

window.renderNutriDaysNav = renderNutriDaysNav;

/**
 * Helpers Clínicos y de Formato Nutricional SENS
 */
function escapeSensHtml(str) {
    if (!str) return '';
    return String(str)
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#039;');
}

function getGlobalFoodCatalog() {
    if (typeof SENS_FOOD_LIBRARY !== 'undefined' && Array.isArray(SENS_FOOD_LIBRARY) && SENS_FOOD_LIBRARY.length > 0) {
        return SENS_FOOD_LIBRARY;
    }
    if (typeof window !== 'undefined' && Array.isArray(window.SENS_FOOD_LIBRARY) && window.SENS_FOOD_LIBRARY.length > 0) {
        return window.SENS_FOOD_LIBRARY;
    }
    if (typeof window !== 'undefined' && Array.isArray(window.FOOD_CATALOG) && window.FOOD_CATALOG.length > 0) {
        return window.FOOD_CATALOG;
    }
    return (typeof FOOD_CATALOG !== 'undefined' && Array.isArray(FOOD_CATALOG)) ? FOOD_CATALOG : [];
}

function normalizeSensString(str) {
    if (!str) return '';
    return str.toString()
        .normalize('NFD')
        .replace(/[\u0300-\u036f]/g, '')
        .toLowerCase()
        .trim();
}

function parseNumberedList(text) {
    if (!text || typeof text !== 'string') return [];
    const trimmed = text.trim();
    if (/\b\d+\.\s*/.test(trimmed)) {
        return trimmed.split(/(?=\b\d+\.\s*)/g).map(s => s.trim()).filter(Boolean);
    }
    if (trimmed.includes('\n')) return trimmed.split('\n').map(s => s.trim()).filter(Boolean);
    if (trimmed.includes('•')) return trimmed.split('•').map(s => s.trim()).filter(Boolean);
    return [trimmed];
}

function formatIngredientsHtml(ings) {
    if (!ings) return '<div class="sens-ingredient-item-row"><span class="sens-ingredient-bullet">•</span><span>Alimento de alta pureza biológica sin conservantes añadidos.</span></div>';
    let list = [];
    if (Array.isArray(ings)) {
        list = ings;
    } else if (typeof ings === 'string') {
        const trimmed = ings.trim();
        if (/\b\d+\.\s*/.test(trimmed)) {
            list = trimmed.split(/(?=\b\d+\.\s*)/g).map(s => s.trim()).filter(Boolean);
        } else if (trimmed.includes('•')) {
            list = trimmed.split('•').map(s => s.trim()).filter(Boolean);
        } else if (trimmed.includes('\n')) {
            list = trimmed.split('\n').map(s => s.trim()).filter(Boolean);
        } else if (trimmed.includes(',')) {
            list = trimmed.split(',').map(s => s.trim()).filter(Boolean);
        } else {
            list = [trimmed];
        }
    }
    return list.map((item) => {
        const clean = item.replace(/^\d+\.\s*/, '').trim();
        return `
            <div class="sens-ingredient-item-row">
                <span class="sens-ingredient-bullet">•</span>
                <span style="color: #CBD5E1;">${clean}</span>
            </div>
        `;
    }).join('');
}

function formatSingleStepRowHtml(stepText, num = 1) {
    if (!stepText) return '';
    const clean = stepText.replace(/^\d+\.\s*/, '').trim();
    return `
        <div class="sens-step-item-row" style="border-bottom: none; padding: 2px 0;">
            <span class="sens-step-badge">${num}</span>
            <span>${clean}</span>
        </div>
    `;
}

function formatStepsHtml(stepsText) {
    const list = parseNumberedList(stepsText);
    if (list.length === 0) {
        return '<div class="sens-step-item-row"><span class="sens-step-badge">1</span><span>Cocción a temperatura controlada preservando perfil enzimático.</span></div>';
    }
    return list.map((step, idx) => {
        const clean = step.replace(/^\d+\.\s*/, '').trim();
        return `
            <div class="sens-step-item-row">
                <span class="sens-step-badge">${idx + 1}</span>
                <span>${clean}</span>
            </div>
        `;
    }).join('');
}

/**
 * Marca o desmarca un alimento como consumido hoy desde la card directa (Item 5)
 */
function toggleFoodLoggedStatus(foodKey, mealSlot) {
    const sDate = AppState.nutriSelectedDate || new Date();
    if (isFutureDate(sDate)) {
        if (typeof showSensToast === 'function') {
            showSensToast('No es posible registrar comidas de fechas futuras.', 'champagne', 2500);
        }
        return;
    }

    const athId = (typeof getActiveAthleteId === 'function') ? getActiveAthleteId() : 'mock_vip';
    const dateIso = `${sDate.getFullYear()}-${String(sDate.getMonth() + 1).padStart(2, '0')}-${String(sDate.getDate()).padStart(2, '0')}`;
    const logKey = `sens_user_consumed_foods_${athId}_${dateIso}`;

    let loggedFoods = {};
    try {
        loggedFoods = JSON.parse(localStorage.getItem(logKey) || '{}');
    } catch (e) {}

    const isCurrentlyLogged = Boolean(loggedFoods[foodKey]);
    if (isCurrentlyLogged) {
        delete loggedFoods[foodKey];
        if (typeof showSensToast === 'function') showSensToast('Alimento desmarcado de hoy.', 'info', 1500);
    } else {
        loggedFoods[foodKey] = true;
        if (typeof showSensToast === 'function') showSensToast('✓ Registrado como consumido hoy.', 'champagne', 2000);
    }
    localStorage.setItem(logKey, JSON.stringify(loggedFoods));

    renderMemberNutritionPlan(athId, sDate);
    renderNutriDaysNav();

    if (typeof syncAllStreakAndPillTelemetry === 'function') {
        const streakEval = syncAllStreakAndPillTelemetry(sDate);
        const nutriStatus = streakEval?.current?.nutrition?.status;
        const prevStatus = streakEval?.previous?.nutrition?.status;
        const consumedKcal = streakEval?.current?.nutrition?.consumed || 0;
        const targetKcal = streakEval?.current?.nutrition?.target || 1950;

        if (nutriStatus === 'on_track' && prevStatus !== 'on_track') {
            if (typeof window.showSensCelebrationToast === 'function') {
                window.showSensCelebrationToast('¡Racha Nutricional Activa!', `Tus calorías (${consumedKcal.toLocaleString('es-AR')} kcal) quedaron en el rango óptimo (-20% / +10%).`);
            }
        } else if (nutriStatus === 'exceeded') {
            if (typeof showSensToast === 'function') {
                showSensToast(`Perdiste el objetivo de racha nutricional de hoy: consumiste ${consumedKcal.toLocaleString('es-AR')} kcal (+10% del objetivo de ${targetKcal.toLocaleString('es-AR')} kcal).`, 'warning', 5000);
            }
        } else if (prevStatus === 'on_track' && nutriStatus === 'pending') {
            if (typeof showSensToast === 'function') {
                showSensToast(`Perdiste el objetivo de racha nutricional de hoy: calorías consumidas (${consumedKcal.toLocaleString('es-AR')} kcal) quedaron debajo del mínimo óptimo.`, 'warning', 4500);
            }
        }
    } else {
        if (typeof updateObjectiveCardData === 'function') updateObjectiveCardData(sDate);
        if (typeof SensDailyStreakManager !== 'undefined') {
            SensDailyStreakManager.evaluateDay(sDate, athId);
        }
        if (typeof updateSensStreakCard === 'function') updateSensStreakCard(sDate);
    }
}

window.toggleFoodLoggedStatus = toggleFoodLoggedStatus;

/**
 * Abre el modal de comida personalizada pre-seleccionando un momento específico de comida
 */
function openCustomMealModalForSlot(slot) {
    const athId = (typeof getActiveAthleteId === 'function') ? getActiveAthleteId() : 'mock_vip';
    if (typeof initUserCustomMealModal === 'function') {
        initUserCustomMealModal(athId);
    }

    const modal = document.getElementById('userCustomMealModal');
    if (!modal) return;
    userCustomTrayItems = [];
    userActiveNutriMealSlot = slot || 'almuerzo';

    const slotPills = modal.querySelectorAll('#customMealSlotRow .sens-nutri-tab-pill');
    slotPills.forEach(pill => {
        const isMatch = pill.getAttribute('data-slot') === userActiveNutriMealSlot;
        pill.classList.toggle('active', isMatch);
    });

    // Reset de pestañas Modo Búsqueda vs Manual
    const tabSearch = document.getElementById('tabCustomSearchMode');
    const tabManual = document.getElementById('tabCustomManualMode');
    const paneSearch = document.getElementById('paneCustomSearch');
    const paneManual = document.getElementById('paneCustomManual');
    if (tabSearch && tabManual && paneSearch && paneManual) {
        tabSearch.style.color = '#E5CBA7';
        tabSearch.style.borderBottomColor = '#E5CBA7';
        tabManual.style.color = '#71717A';
        tabManual.style.borderBottomColor = 'transparent';
        paneSearch.style.display = 'block';
        paneManual.style.display = 'none';
    }

    // Reset de Filtros de Calorías
    const kcalChips = modal.querySelectorAll('#customKcalFilterRow .sens-kcal-chip');
    kcalChips.forEach(c => c.classList.remove('active'));
    const allChip = modal.querySelector('#customKcalFilterRow .sens-kcal-chip[data-range="all"]');
    if (allChip) allChip.classList.add('active');

    const minInput = document.getElementById('customKcalMinInput');
    const maxInput = document.getElementById('customKcalMaxInput');
    if (minInput) minInput.value = '';
    if (maxInput) maxInput.value = '';

    modal.classList.add('active');
    document.body.style.overflow = 'hidden';

    const searchInput = document.getElementById('customFoodSearchInput');
    if (searchInput) {
        searchInput.value = '';
    }

    if (typeof window.renderCustomSearchResults === 'function') {
        window.renderCustomSearchResults('');
    }
    if (typeof window.renderCustomTray === 'function') {
        window.renderCustomTray();
    }
}

window.openCustomMealModalForSlot = openCustomMealModalForSlot;

function renderMemberNutritionPlan(athId, targetDate = new Date()) {
    const sDate = targetDate || new Date();
    AppState.nutriSelectedDate = sDate;
    const isToday = isSameDay(sDate, new Date());

    const dateIso = `${sDate.getFullYear()}-${String(sDate.getMonth() + 1).padStart(2, '0')}-${String(sDate.getDate()).padStart(2, '0')}`;
    const dayOfWeek = sDate.getDay();
    const dayKey = dayOfWeek === 0 ? 'day7' : `day${dayOfWeek}`;

    const adjustStorageKey = `sens_user_adjusted_meals_${athId}_${dateIso}`;
    const customStorageKey = `sens_user_logged_meals_${athId}_${dateIso}`;
    const consumedStorageKey = `sens_user_consumed_foods_${athId}_${dateIso}`;

    let userAdjusted = {};
    try {
        userAdjusted = JSON.parse(localStorage.getItem(adjustStorageKey) || '{}');
    } catch (e) {}

    let userCustomMeals = [];
    try {
        userCustomMeals = JSON.parse(localStorage.getItem(customStorageKey) || '[]');
    } catch (e) {}

    let userConsumedFoods = {};
    try {
        userConsumedFoods = JSON.parse(localStorage.getItem(consumedStorageKey) || '{}');
    } catch (e) {}

    // 2. Obtener Plan del Coach
    let userPlan = null;
    try {
        const raw = localStorage.getItem(`sens_prescribed_nutrition_${athId}`) ||
                    localStorage.getItem(`sens_coach_assigned_nutrition_${athId}`);
        if (raw) userPlan = JSON.parse(raw);
    } catch (e) {}
    if (!userPlan && AppState.profile?.prescribed_nutrition) {
        userPlan = AppState.profile.prescribed_nutrition;
    }

    // Auto-sanitización y vinculación con la Base de 500 Alimentos (garantiza fotos WebP reales en todo momento)
    const mealKeys = ['desayuno', 'almuerzo', 'merienda', 'cena', 'snack'];
    if (userPlan && userPlan.days) {
        Object.keys(userPlan.days).forEach(dKey => {
            const d = userPlan.days[dKey];
            if (d && d.meals) {
                mealKeys.forEach(mKey => {
                    const slot = d.meals[mKey];
                    const foods = Array.isArray(slot?.foods) ? slot.foods : (Array.isArray(slot) ? slot : null);
                    if (foods) {
                        foods.forEach(f => {
                            const res = (typeof window.getResolvedFood === 'function') ? window.getResolvedFood(f, athId) : null;
                            if (res) {
                                f.id = res.id;
                                f.codigo = res.codigo;
                                f.name = res.nombre_alimento_o_plato || res.name;
                                f.image = res.imagen_url || res.image;
                            }
                        });
                    }
                });
            }
        });
    }

    // Directiva del Coach y Objetivo
    const directiveCard = document.getElementById('memberNutriDirectiveCard');
    const directiveText = document.getElementById('memberNutriDirectiveText');
    const goalPill = document.getElementById('memberNutriPlanGoalPill');
    const dailyGoalBadge = document.getElementById('nutriDailyGoalBadge');

    const userGoal = userPlan?.goal || AppState.profile?.goal || 'fat_loss';
    const goalLabels = {
        fat_loss: 'Déficit Calórico',
        muscle_gain: 'Superávit Magro',
        recomp: 'Recomposición',
        posture_health: 'Longevidad'
    };
    const goalText = goalLabels[userGoal] || 'Nutrición SENS';
    if (goalPill) goalPill.textContent = goalText;
    if (dailyGoalBadge) dailyGoalBadge.textContent = `Meta: ${goalText}`;
    if (directiveText) {
        directiveText.textContent = userPlan?.directive_note || 'Priorizá 35-40g de proteína en cada una de las comidas principales y mantené hidratación constante antes y después de entrenar.';
    }

    // 3. Estructurar Alimentos del Día
    const mealLabels = {
        desayuno: 'Desayuno',
        almuerzo: 'Almuerzo',
        merienda: 'Merienda',
        cena: 'Cena',
        snack: 'Snacks'
    };

    const dayMeals = userPlan?.days?.[dayKey]?.meals || userPlan?.days?.['day1']?.meals || {};

    const defaultMealsFallback = {
        desayuno: [
            { id: 'd679f46e-bed8-5759-8669-62707b9a3110', codigo: 'NUT-002', name: 'Huevo Entero de Gallina (Cocido / Duro o Poché)', image: 'Nutricion/images/nut-002-huevo-entero-de-gallina.webp', grams: 120, mealSlot: 'desayuno' },
            { id: 'ab477ed5-01b7-5ed0-b2ba-309a145d4550', codigo: 'NUT-022', name: 'Avena Arrollada Tradicional (En Crudo para Cocinar o Remojar)', image: 'Nutricion/images/nut-022-avena-arrollada-tradicional.webp', grams: 60, mealSlot: 'desayuno' }
        ],
        almuerzo: [
            { id: 'ae856777-a8d3-5238-9385-6bffce376820', codigo: 'NUT-001', name: 'Pechuga de Pollo a la Plancha (Sin Piel)', image: 'Nutricion/images/nut-001-pechuga-de-pollo-a-la-plancha.webp', grams: 180, mealSlot: 'almuerzo' },
            { id: 'ad77e728-2da8-5d10-90d2-58ddd37ce9d2', codigo: 'NUT-024', name: 'Arroz Integral o Yamaní Cocido', image: 'Nutricion/images/nut-024-arroz-integral-o-yamani-cocido.webp', grams: 150, mealSlot: 'almuerzo' }
        ],
        merienda: [
            { id: '5f2ed125-2184-5830-86a6-a1e33c94581c', codigo: 'NUT-017', name: 'Yogur Griego Natural Sin Azúcar (Descremado / Skyr)', image: 'Nutricion/images/nut-017-yogur-griego-natural-sin-azucar.webp', grams: 170, mealSlot: 'merienda' },
            { id: '46a1db17-597b-53d7-ab86-cc681f75d218', codigo: 'NUT-042', name: 'Almendras o Nueces Naturales (Peladas)', image: 'Nutricion/images/nut-042-almendras-o-nueces-naturales.webp', grams: 30, mealSlot: 'merienda' }
        ],
        cena: [
            { id: 'da2fd14d-6afa-5d65-bb77-cf335f72d636', codigo: 'NUT-010', name: 'Salmón Rosado / Trucha Salmonada a la Plancha', image: 'Nutricion/images/nut-010-salmon-rosado-trucha-salmonada-a-la-plancha.webp', grams: 180, mealSlot: 'cena' },
            { id: '2294c1d4-d80a-50d6-8382-fde68052d415', codigo: 'NUT-038', name: 'Brócoli Cocido al Vapor (Al Dente)', image: 'Nutricion/images/nut-038-brocoli-cocido-al-vapor.webp', grams: 150, mealSlot: 'cena' }
        ],
        snack: [
            { id: '74f7cbc6-7d44-50fc-9b58-7efc3b091185', codigo: 'NUT-035', name: 'Manzana Roja o Verde con Cáscara', image: 'Nutricion/images/nut-035-manzana-roja-o-verde-con-cascara.webp', grams: 160, mealSlot: 'snack' }
        ]
    };

    let allDayFoods = [];

    mealKeys.forEach(mKey => {
        let foods = dayMeals[mKey]?.foods || dayMeals[mKey] || [];
        if (!Array.isArray(foods) || foods.length === 0) {
            foods = defaultMealsFallback[mKey] || [];
        }
        foods.forEach(f => {
            allDayFoods.push(Object.assign({}, f, { mealSlot: mKey }));
        });
    });

    // Agregar comidas personalizadas registradas por el usuario para hoy
    userCustomMeals.forEach(cm => {
        allDayFoods.push(cm);
    });

    // 4. Renderizar Subsecciones Visuales con Container Encompassing Parent Card (Item 1 & 2)
    const foodListEl = document.getElementById('memberNutriFoodList');
    const activeFilter = AppState.activeNutriFilter || 'todas';
    const slotsToRender = activeFilter === 'todas' ? mealKeys : [activeFilter];

    let subsectionsHtml = '';

    slotsToRender.forEach(mKey => {
        const slotFoods = allDayFoods.filter(f => f.mealSlot === mKey);
        let slotKcal = 0;
        let slotConsumedKcal = 0;
        let slotConsumedCount = 0;

        const cardsHtml = slotFoods.map(item => {
            const resolved = (typeof window.getResolvedFood === 'function')
                ? window.getResolvedFood(item, athId)
                : item;

            const foodKey = resolved?.id || resolved?.codigo || item.id || item.name;
            const grams = userAdjusted[foodKey] ? parseInt(userAdjusted[foodKey], 10) : (item.grams || resolved?.defaultGrams || 100);

            let macros;
            if (item.isCustom && item.calories !== undefined) {
                macros = {
                    calories: item.calories,
                    protein: item.protein || 0,
                    carbs: item.carbs || 0,
                    fats: item.fats || 0
                };
            } else {
                macros = (typeof window.calculateFoodMacros === 'function')
                    ? window.calculateFoodMacros(resolved, grams)
                    : { calories: Math.round(grams * 1.5), protein: 20, carbs: 15, fats: 5 };
            }

            slotKcal += macros.calories;

            const isLogged = item.isCustom ? (userConsumedFoods[foodKey] !== false) : Boolean(userConsumedFoods[foodKey]);
            if (isLogged) {
                slotConsumedKcal += macros.calories;
                slotConsumedCount++;
            }

            const imgUrl = resolved?.image || resolved?.image_url || 'Nutricion/images/nut-001-pechuga-de-pollo-a-la-plancha.webp';
            const foodTitle = item.name || resolved?.name || resolved?.name_es || 'Alimento SENS';
            const portionText = item.isCustom ? 'Comida Personalizada' : (resolved?.unidades_caseras_total || `${grams}g`);

            return `
                <div class="sens-nutri-food-card ${isLogged ? 'is-logged' : ''}" data-food-id="${foodKey}" data-meal-slot="${item.mealSlot}" data-grams="${grams}">
                    <img class="sens-nutri-food-thumb" src="${imgUrl}" alt="${foodTitle}" onerror="this.src='Nutricion/images/nut-001-pechuga-de-pollo-a-la-plancha.webp'">
                    <div class="sens-nutri-food-info">
                        <span class="sens-nutri-food-meal-tag">${mealLabels[item.mealSlot] || item.mealSlot}</span>
                        <div class="sens-nutri-food-title" title="${foodTitle}">${foodTitle}</div>
                        <div class="sens-nutri-food-meta">${grams}g • ${portionText}</div>
                        <div class="sens-nutri-food-macros">
                            <span class="prot">${Math.round(macros.protein)}g P</span>
                            <span class="carb">${Math.round(macros.carbs)}g C</span>
                            <span class="fat">${Math.round(macros.fats)}g G</span>
                        </div>
                    </div>
                    <div class="sens-nutri-food-right" style="display: flex; align-items: center; gap: 8px;">
                        <div class="sens-nutri-kcal-badge">${macros.calories} kcal</div>
                        <button type="button" class="sens-btn-quick-log ${isLogged ? 'is-logged' : ''}" data-food-id="${foodKey}" data-meal-slot="${item.mealSlot}" title="${isLogged ? 'Desmarcar ingesta' : 'Registrar como consumido'}">
                            <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round">
                                <polyline points="20 6 9 17 4 12"></polyline>
                            </svg>
                        </button>
                    </div>
                </div>
            `;
        }).join('');

        const subtotalMeta = slotConsumedCount > 0
            ? `${slotConsumedKcal.toLocaleString('es-AR')} / ${slotKcal.toLocaleString('es-AR')} kcal • ${slotConsumedCount}/${slotFoods.length} consumidos`
            : `${slotKcal.toLocaleString('es-AR')} kcal • ${slotFoods.length} items`;

        subsectionsHtml += `
            <div class="sens-meal-subsection-block" data-meal-slot="${mKey}">
                <div class="sens-meal-subsection-header">
                    <div class="sens-meal-header-left">
                        <div class="sens-meal-header-title-row">
                            <span class="sens-meal-badge-dot"></span>
                            <h4 class="sens-meal-title">${mealLabels[mKey]}</h4>
                        </div>
                        <span class="sens-meal-subtotal-meta">${subtotalMeta}</span>
                    </div>
                    <button type="button" class="btn-quick-add-to-meal" data-meal-slot="${mKey}" title="Agregar alimento a ${mealLabels[mKey]}">
                        <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><line x1="12" y1="5" x2="12" y2="19"></line><line x1="5" y1="12" x2="19" y2="12"></line></svg>
                        <span>Agregar</span>
                    </button>
                </div>
                <div class="sens-meal-foods-grid">
                    ${cardsHtml || `<div style="padding: 14px; font-size: 12px; color: #71717A; background: rgba(255,255,255,0.02); border-radius: 12px; border: 1px dashed rgba(255,255,255,0.06); text-align: center;">No hay alimentos en ${mealLabels[mKey]}. Tocá <strong>+ Agregar</strong> para sumar desde la biblioteca o registrar calorías.</div>`}
                </div>
            </div>
        `;
    });

    if (foodListEl) {
        foodListEl.innerHTML = subsectionsHtml;

        // Listener: + Agregar en cabecera de subsección
        foodListEl.querySelectorAll('.btn-quick-add-to-meal').forEach(btn => {
            btn.addEventListener('click', (e) => {
                e.stopPropagation();
                const slot = btn.getAttribute('data-meal-slot');
                if (typeof window.openCustomMealModalForSlot === 'function') {
                    window.openCustomMealModalForSlot(slot);
                }
            });
        });

        // Listener: Botón táctil Quick Log
        foodListEl.querySelectorAll('.sens-btn-quick-log').forEach(btn => {
            btn.addEventListener('click', (e) => {
                e.stopPropagation();
                const fid = btn.getAttribute('data-food-id');
                const slot = btn.getAttribute('data-meal-slot');
                toggleFoodLoggedStatus(fid, slot);
            });
        });

        // Listener: Card de alimento abre el Inspector
        foodListEl.querySelectorAll('.sens-nutri-food-card').forEach(card => {
            card.addEventListener('click', (e) => {
                if (e.target.closest('.sens-btn-quick-log, .btn-quick-add-to-meal')) return;
                const foodKey = card.getAttribute('data-food-id');
                const mealSlot = card.getAttribute('data-meal-slot');
                const item = allDayFoods.find(f => (f.id === foodKey || f.codigo === foodKey || f.name === foodKey));
                if (item) {
                    openUserFoodDetailModal(item, mealSlot);
                }
            });
        });
    }

    // 5. Recalcular Balance Global del Día & Sincronizar Hero Card (Item 2: ESTRICTAMENTE SOBRE LO CONSUMIDO)
    let totalConsumedKcal = 0;
    let totalConsumedProt = 0;
    let totalConsumedCarbs = 0;
    let totalConsumedFats = 0;

    allDayFoods.forEach(item => {
        const resolved = (typeof window.getResolvedFood === 'function')
            ? window.getResolvedFood(item, athId)
            : item;
        const foodKey = resolved?.id || resolved?.codigo || item.id || item.name;
        const grams = userAdjusted[foodKey] ? parseInt(userAdjusted[foodKey], 10) : (item.grams || resolved?.defaultGrams || 100);

        let macros;
        if (item.isCustom && item.calories !== undefined) {
            macros = {
                calories: item.calories,
                protein: item.protein || 0,
                carbs: item.carbs || 0,
                fats: item.fats || 0
            };
        } else {
            macros = (typeof window.calculateFoodMacros === 'function')
                ? window.calculateFoodMacros(resolved, grams)
                : { calories: Math.round(grams * 1.5), protein: 20, carbs: 15, fats: 5 };
        }

        const isLogged = item.isCustom ? (userConsumedFoods[foodKey] !== false) : Boolean(userConsumedFoods[foodKey]);
        if (isLogged) {
            totalConsumedKcal += macros.calories;
            totalConsumedProt += macros.protein;
            totalConsumedCarbs += macros.carbs;
            totalConsumedFats += macros.fats;
        }
    });

    const targetKcal = userPlan?.target_calories || 1950;
    const consumedNum = document.getElementById('nutriConsumedNum');
    const targetKcalEl = document.getElementById('nutriTargetKcal');
    const remainingEl = document.getElementById('nutriRemainingKcal');
    const optimalRangeEl = document.getElementById('nutriOptimalRangeText');
    const sliderFill = document.getElementById('nutriSliderFill');
    const carbsGramsEl = document.getElementById('nutriCarbsGrams');
    const fatsGramsEl = document.getElementById('nutriFatsGrams');
    const protGramsEl = document.getElementById('nutriProtGrams');

    if (consumedNum) consumedNum.textContent = totalConsumedKcal.toLocaleString('es-AR');
    if (targetKcalEl) targetKcalEl.textContent = `${targetKcal.toLocaleString('es-AR')} kcal`;
    if (remainingEl) {
        const diff = targetKcal - totalConsumedKcal;
        if (totalConsumedKcal === 0) {
            remainingEl.textContent = `Restan ${targetKcal.toLocaleString('es-AR')} kcal para tu objetivo`;
            remainingEl.style.color = '#A1A1AA';
        } else if (diff > 0) {
            remainingEl.textContent = `Restan ${diff.toLocaleString('es-AR')} kcal para tu objetivo`;
            remainingEl.style.color = '#A1A1AA';
        } else if (diff === 0) {
            remainingEl.textContent = 'Meta calórica alcanzada exacta';
            remainingEl.style.color = '#10B981';
        } else {
            remainingEl.textContent = `+${Math.abs(diff).toLocaleString('es-AR')} kcal sobre objetivo`;
            remainingEl.style.color = '#F59E0B';
        }
    }
    if (optimalRangeEl) {
        optimalRangeEl.textContent = `Rango óptimo: ${Math.round(targetKcal * 0.9).toLocaleString('es-AR')} - ${Math.round(targetKcal * 1.1).toLocaleString('es-AR')} kcal`;
    }
    if (sliderFill) {
        const pct = targetKcal > 0 ? Math.min(100, Math.round((totalConsumedKcal / targetKcal) * 100)) : 0;
        sliderFill.style.width = `${pct}%`;
        sliderFill.style.background = totalConsumedKcal > (targetKcal * 1.1) ? 'linear-gradient(90deg, #F59E0B, #EF4444)' : 'linear-gradient(90deg, #9E7D4B 0%, #E5CBA7 100%)';
    }

    // Resumen y Desglose de Macronutrientes en Acordeón Integrado (ESTRICTAMENTE SOBRE LO CONSUMIDO)
    const quickSummary = document.getElementById('nutriMacroQuickSummary');
    if (carbsGramsEl) carbsGramsEl.innerHTML = `${Math.round(totalConsumedCarbs)}<span style="font-size: 12px; font-weight: 500; color: var(--text-muted);">g</span>`;
    if (fatsGramsEl) fatsGramsEl.innerHTML = `${Math.round(totalConsumedFats)}<span style="font-size: 12px; font-weight: 500; color: var(--text-muted);">g</span>`;
    if (protGramsEl) protGramsEl.innerHTML = `${Math.round(totalConsumedProt)}<span style="font-size: 12px; font-weight: 500; color: var(--text-muted);">g</span>`;

    const totalMacroGrams = (totalConsumedCarbs + totalConsumedProt + totalConsumedFats);
    let carbPct = 0;
    let protPct = 0;
    let fatPct = 0;

    if (totalMacroGrams > 0) {
        carbPct = Math.round((totalConsumedCarbs / totalMacroGrams) * 100);
        protPct = Math.round((totalConsumedProt / totalMacroGrams) * 100);
        fatPct = Math.max(0, 100 - carbPct - protPct);
        if (quickSummary) {
            quickSummary.textContent = `${Math.round(totalConsumedProt)}g Prot • ${Math.round(totalConsumedCarbs)}g Carbs • ${Math.round(totalConsumedFats)}g Grasas`;
        }
    } else {
        if (quickSummary) {
            quickSummary.textContent = 'Sin comidas marcadas hoy • Tocá ✓ en cada plato para sumar';
        }
    }

    const carbsRatioEl = document.getElementById('nutriCarbsRatio');
    const protRatioEl = document.getElementById('nutriProtRatio');
    const fatsRatioEl = document.getElementById('nutriFatsRatio');
    if (carbsRatioEl) carbsRatioEl.textContent = `${carbPct}% del total`;
    if (protRatioEl) protRatioEl.textContent = `${protPct}% del total`;
    if (fatsRatioEl) fatsRatioEl.textContent = `${fatPct}% del total`;

    const segCarb = document.getElementById('nutriSegCarb');
    const segProt = document.getElementById('nutriSegProt');
    const segFat = document.getElementById('nutriSegFat');
    if (segCarb) segCarb.style.width = `${carbPct}%`;
    if (segProt) segProt.style.width = `${protPct}%`;
    if (segFat) segFat.style.width = `${fatPct}%`;

    const legCarb = document.getElementById('legendCarbPct');
    const legProt = document.getElementById('legendProtPct');
    const legFat = document.getElementById('legendFatPct');
    if (legCarb) legCarb.textContent = `${carbPct}% Carb`;
    if (legProt) legProt.textContent = `${protPct}% Proteína`;
    if (legFat) legFat.textContent = `${fatPct}% Grasa`;

    // Persistir calorías consumidas del día para sincronía cruzada con Inicio (Balance Energético y Racha)
    try {
        localStorage.setItem(`sens_cals_${dateIso}`, totalConsumedKcal);
        if (isToday) {
            if (!AppState.dailyNutrition) AppState.dailyNutrition = {};
            AppState.dailyNutrition.calories = totalConsumedKcal;
            AppState.dailyNutrition.protein = Math.round(totalConsumedProt);
            AppState.dailyNutrition.carbs = Math.round(totalConsumedCarbs);
            AppState.dailyNutrition.fats = Math.round(totalConsumedFats);
            localStorage.setItem('sens_daily_nutrition', JSON.stringify(AppState.dailyNutrition));
        }
    } catch (e) {}

    // Toggle del Acordeón de Macronutrientes
    const btnToggleMacro = document.getElementById('btnToggleMacroDrawer');
    const macroDrawer = document.getElementById('sensNutriMacroDrawerBody');
    const chevron = document.getElementById('macroDrawerChevron');
    if (btnToggleMacro && !btnToggleMacro._hasMacroToggleBound) {
        btnToggleMacro._hasMacroToggleBound = true;
        btnToggleMacro.addEventListener('click', () => {
            if (!macroDrawer) return;
            const isClosed = macroDrawer.style.display === 'none' || !macroDrawer.style.display;
            macroDrawer.style.display = isClosed ? 'block' : 'none';
            if (chevron) chevron.textContent = isClosed ? '▴' : '▾';
        });
    }

    // Experiencia 2: Recomendador Inteligente "Clavar mis Macros"
    if (typeof renderSmartMacroRecommender === 'function') {
        renderSmartMacroRecommender(allDayFoods, athId, targetKcal, totalConsumedKcal, userPlan?.target_protein || 150, totalConsumedProt);
    }
}

/**
 * Abre el Modal de Detalle de Alimento & Ajuste Proporcional de Gramos / Unidades
 */
function openUserFoodDetailModal(foodItem, mealSlot = 'almuerzo', isFromSearch = false) {
    window.openUserFoodDetailModal = openUserFoodDetailModal;
    const modal = document.getElementById('userFoodDetailModal');
    if (!modal) return;

    const athId = (typeof getActiveAthleteId === 'function') ? getActiveAthleteId() : 'mock_vip';
    const sDate = AppState.nutriSelectedDate || new Date();
    const dateIso = `${sDate.getFullYear()}-${String(sDate.getMonth() + 1).padStart(2, '0')}-${String(sDate.getDate()).padStart(2, '0')}`;
    const adjustStorageKey = `sens_user_adjusted_meals_${athId}_${dateIso}`;

    let userAdjusted = {};
    try {
        userAdjusted = JSON.parse(localStorage.getItem(adjustStorageKey) || '{}');
    } catch (e) {}

    const resolved = (typeof window.getResolvedFood === 'function')
        ? window.getResolvedFood(foodItem, athId)
        : foodItem;

    userActiveFoodForDetail = {
        item: foodItem,
        resolved: resolved,
        mealSlot: mealSlot,
        athId: athId,
        dateIso: dateIso,
        isFromSearch: Boolean(isFromSearch)
    };

    const foodKey = resolved?.id || resolved?.codigo || foodItem.id || foodItem.name;
    const initialGrams = userAdjusted[foodKey] ? parseInt(userAdjusted[foodKey], 10) : (foodItem.grams || resolved?.porcion_total_g_ml || resolved?.defaultGrams || 100);

    // Ajustar texto del botón principal si viene desde el buscador de comidas personalizadas
    const confirmBtn = document.getElementById('btnConfirmUfdPortion');
    if (confirmBtn) {
        confirmBtn.textContent = isFromSearch ? 'Registrar en mi Día' : 'Guardar Ajuste de Porción';
    }

    // Poblar elementos
    const catPill = document.getElementById('ufdCategoryPill');
    const mealPill = document.getElementById('ufdMealPill');
    const foodImg = document.getElementById('ufdFoodImg');
    const titleEl = document.getElementById('ufdFoodTitle');
    const gramInput = document.getElementById('ufdGramInput');
    const ingrText = document.getElementById('ufdIngredientsText');
    const tipText = document.getElementById('ufdCoachTipText');
    const allergensText = document.getElementById('ufdAllergensText');
    const chefCard = document.getElementById('ufdChefTrickWrap');
    const chefText = document.getElementById('ufdChefTrickText');
    const eqCard = document.getElementById('ufdEquivalentsWrap');
    const eqText = document.getElementById('ufdEquivalentsText');
    const badgesRow = document.getElementById('ufdBadgesRow');

    if (catPill) catPill.textContent = resolved?.categoria_nutricional || 'Nutrición SENS';
    if (mealPill) mealPill.textContent = (mealSlot || 'Almuerzo').toUpperCase();
    if (foodImg) {
        foodImg.src = resolved?.image || resolved?.imagen_url || 'Nutricion/images/nut-001-pechuga-de-pollo-a-la-plancha.webp';
        foodImg.onerror = () => { foodImg.src = 'Nutricion/images/nut-001-pechuga-de-pollo-a-la-plancha.webp'; };
    }
    if (titleEl) titleEl.textContent = foodItem.name || resolved?.name || resolved?.nombre_alimento_o_plato || resolved?.name_es || 'Alimento SENS';
    if (gramInput) gramInput.value = initialGrams;

    // Badges flotantes en Hero Image
    if (badgesRow) {
        let bHtml = '';
        if (resolved?.tipo_item) {
            bHtml += `<span class="sens-food-badge-pill champagne">${resolved.tipo_item}</span>`;
        }
        if (resolved?.costo_estimado_nivel) {
            bHtml += `<span class="sens-food-badge-pill">💰 ${resolved.costo_estimado_nivel}</span>`;
        }
        if (resolved?.apto_vianda_fria) {
            bHtml += `<span class="sens-food-badge-pill">❄️ Apto Vianda</span>`;
        }
        if (resolved?.tiempo_preparacion_min) {
            bHtml += `<span class="sens-food-badge-pill">⏱️ ${resolved.tiempo_preparacion_min} min</span>`;
        }
        badgesRow.innerHTML = bHtml;
    }

    // Ingredientes reales con viñetas limpias
    if (ingrText) {
        const ings = resolved?.ingredientes_y_gramajes || resolved?.ingredientes_principales;
        ingrText.innerHTML = formatIngredientsHtml(ings);
    }

    // Pasos de preparación numerados 1., 2., 3.
    const fullSteps = resolved?.paso_a_paso_preparacion || resolved?.pasos_preparacion || resolved?.preparacion || 'Cocción a temperatura controlada preservando perfil enzimático.';
    const stepItems = parseNumberedList(fullSteps);

    const previewEl = document.getElementById('ufdStepsPreview');
    const fullEl = document.getElementById('ufdStepsFull');
    const toggleStepsBtn = document.getElementById('btnToggleUfdSteps');
    const stepsToggleText = document.getElementById('ufdStepsToggleText');
    const stepsArrow = document.getElementById('ufdStepsArrow');

    if (previewEl && fullEl) {
        fullEl.style.display = 'none';
        previewEl.style.display = 'block';
        if (stepsToggleText) stepsToggleText.textContent = 'Ver más';
        if (stepsArrow) stepsArrow.textContent = '▾';

        if (stepItems.length > 1) {
            previewEl.innerHTML = formatSingleStepRowHtml(stepItems[0], 1);
            fullEl.innerHTML = stepItems.map((s, idx) => formatSingleStepRowHtml(s, idx + 1)).join('');
            if (toggleStepsBtn) toggleStepsBtn.style.display = 'inline-flex';
        } else {
            previewEl.innerHTML = formatSingleStepRowHtml(stepItems[0] || fullSteps, 1);
            fullEl.innerHTML = '';
            if (toggleStepsBtn) toggleStepsBtn.style.display = 'none';
        }
    }

    if (toggleStepsBtn && !toggleStepsBtn._hasToggleBound) {
        toggleStepsBtn._hasToggleBound = true;
        toggleStepsBtn.addEventListener('click', () => {
            if (!fullEl || !previewEl) return;
            const isClosed = fullEl.style.display === 'none';
            if (isClosed) {
                previewEl.style.display = 'none';
                fullEl.style.display = 'flex';
                fullEl.style.flexDirection = 'column';
                fullEl.style.gap = '8px';
                if (stepsToggleText) stepsToggleText.textContent = 'Ver menos';
                if (stepsArrow) stepsArrow.textContent = '▴';
            } else {
                previewEl.style.display = 'block';
                fullEl.style.display = 'none';
                if (stepsToggleText) stepsToggleText.textContent = 'Ver más';
                if (stepsArrow) stepsArrow.textContent = '▾';
            }
        });
    }

    // TRUCO DEL CHEF SENS (NUEVO)
    if (chefCard && chefText) {
        if (resolved?.truco_del_chef) {
            chefText.textContent = resolved.truco_del_chef;
            chefCard.style.display = 'block';
        } else {
            chefCard.style.display = 'none';
        }
    }

    // TIP NUTRICIONISTA DEPORTIVO
    if (tipText) {
        tipText.textContent = resolved?.tip_nutricionista_deportivo || resolved?.tip_coach_nico || 'Optimizá la masticación y acompañá con ingesta pausada de agua para facilitar vaciado gástrico.';
    }

    // REEMPLAZOS EQUIVALENTES
    if (eqCard && eqText) {
        if (resolved?.reemplazos_equivalentes) {
            eqText.textContent = resolved.reemplazos_equivalentes;
            eqCard.style.display = 'block';
        } else {
            eqCard.style.display = 'none';
        }
    }

    // ALÉRGENOS
    if (allergensText) {
        allergensText.textContent = resolved?.alergenos || resolved?.alergenos_sensibilidades || 'Ninguno declarado';
    }

    // Soporte de Unidades vs Gramos (Item 5)
    const unitInfo = getFoodUnitInfo(resolved || foodItem);
    const unitToggleWrap = document.getElementById('ufdUnitToggleWrap');
    const gramsRow = document.getElementById('ufdGramsStepperRow');
    const unitsRow = document.getElementById('ufdUnitsStepperRow');
    const unitInput = document.getElementById('ufdUnitInput');
    const unitLabel = document.getElementById('ufdUnitNameLabel');
    const btnModeGrams = document.getElementById('btnUfdUnitModeGrams');
    const btnModeUnits = document.getElementById('btnUfdUnitModeUnits');

    userActiveFoodForDetail.unitInfo = unitInfo;

    if (unitInfo && unitInfo.hasUnit) {
        if (unitToggleWrap) unitToggleWrap.style.display = 'inline-flex';
        if (unitLabel) unitLabel.textContent = unitInfo.unitName;
        const initialUnits = Math.round((initialGrams / unitInfo.gramsPerUnit) * 10) / 10;
        if (unitInput) unitInput.value = initialUnits || 1;
    } else {
        if (unitToggleWrap) unitToggleWrap.style.display = 'none';
    }

    if (btnModeGrams && btnModeUnits) {
        btnModeGrams.classList.add('active');
        btnModeUnits.classList.remove('active');
        if (gramsRow) gramsRow.style.display = 'flex';
        if (unitsRow) unitsRow.style.display = 'none';
    }

    const updateLiveCalculations = (grams) => {
        grams = Math.max(10, Math.min(1200, parseInt(grams, 10) || 100));
        let macros;
        if (foodItem.isCustom && foodItem.calories !== undefined) {
            const factor = grams / (foodItem.grams || 100);
            macros = {
                calories: Math.round(foodItem.calories * factor),
                protein: Math.round((foodItem.protein || 0) * factor * 10) / 10,
                carbs: Math.round((foodItem.carbs || 0) * factor * 10) / 10,
                fats: Math.round((foodItem.fats || 0) * factor * 10) / 10
            };
        } else {
            macros = (typeof window.calculateFoodMacros === 'function')
                ? window.calculateFoodMacros(resolved, grams)
                : { calories: Math.round(grams * 1.5), protein: 25, carbs: 15, fats: 5 };
        }

        const calcKcal = document.getElementById('ufdCalcKcal');
        const calcProt = document.getElementById('ufdCalcProt');
        const calcCarbs = document.getElementById('ufdCalcCarbs');
        const calcFats = document.getElementById('ufdCalcFats');

        if (calcKcal) calcKcal.textContent = macros.calories;
        if (calcProt) calcProt.textContent = `${macros.protein}g`;
        if (calcCarbs) calcCarbs.textContent = `${macros.carbs}g`;
        if (calcFats) calcFats.textContent = `${macros.fats}g`;
    };

    updateLiveCalculations(initialGrams);
    userActiveFoodForDetail.updateLiveCalculations = updateLiveCalculations;

    modal.classList.add('active');
    document.body.style.overflow = 'hidden';
    document.body.classList.add('sens-modal-open');
}

function initUserFoodDetailModal() {
    const modal = document.getElementById('userFoodDetailModal');
    const closeBtn = document.getElementById('btnCloseUserFoodDetailModal');
    const gramInput = document.getElementById('ufdGramInput');
    const unitInput = document.getElementById('ufdUnitInput');
    const minus50 = document.getElementById('btnUfdMinus50');
    const minus10 = document.getElementById('btnUfdMinus10');
    const plus10 = document.getElementById('btnUfdPlus10');
    const plus50 = document.getElementById('btnUfdPlus50');
    const minusUnit = document.getElementById('btnUfdMinusUnit');
    const plusUnit = document.getElementById('btnUfdPlusUnit');
    const btnModeGrams = document.getElementById('btnUfdUnitModeGrams');
    const btnModeUnits = document.getElementById('btnUfdUnitModeUnits');
    const gramsRow = document.getElementById('ufdGramsStepperRow');
    const unitsRow = document.getElementById('ufdUnitsStepperRow');
    const confirmBtn = document.getElementById('btnConfirmUfdPortion');

    if (!modal || modal._hasDetailBound) return;
    modal._hasDetailBound = true;

    const closeModal = () => {
        modal.classList.remove('active');
        document.body.style.overflow = '';
        setTimeout(() => {
            if (!document.querySelector('.sens-modal-sheet-wrap.active')) {
                document.body.classList.remove('sens-modal-open');
            }
        }, 50);
    };

    if (closeBtn) closeBtn.addEventListener('click', closeModal);
    modal.addEventListener('click', (e) => {
        if (e.target === modal) closeModal();
    });

    // Toggle entre Modo Gramos y Modo Unidades (Item 5)
    if (btnModeGrams && btnModeUnits) {
        btnModeGrams.addEventListener('click', () => {
            btnModeGrams.classList.add('active');
            btnModeUnits.classList.remove('active');
            if (gramsRow) gramsRow.style.display = 'flex';
            if (unitsRow) unitsRow.style.display = 'none';
        });

        btnModeUnits.addEventListener('click', () => {
            btnModeUnits.classList.add('active');
            btnModeGrams.classList.remove('active');
            if (gramsRow) gramsRow.style.display = 'none';
            if (unitsRow) unitsRow.style.display = 'flex';

            const uInfo = userActiveFoodForDetail?.unitInfo;
            if (uInfo && uInfo.hasUnit && gramInput && unitInput) {
                const currentG = parseInt(gramInput.value, 10) || uInfo.gramsPerUnit;
                unitInput.value = Math.max(0.5, Math.round((currentG / uInfo.gramsPerUnit) * 10) / 10);
            }
        });
    }

    const adjustGrams = (delta) => {
        if (!gramInput) return;
        let current = parseInt(gramInput.value, 10) || 100;
        let next = Math.max(10, Math.min(1200, current + delta));
        gramInput.value = next;

        const uInfo = userActiveFoodForDetail?.unitInfo;
        if (uInfo && uInfo.hasUnit && unitInput) {
            unitInput.value = Math.max(0.5, Math.round((next / uInfo.gramsPerUnit) * 10) / 10);
        }

        if (userActiveFoodForDetail && userActiveFoodForDetail.updateLiveCalculations) {
            userActiveFoodForDetail.updateLiveCalculations(next);
        }
    };

    if (minus50) minus50.addEventListener('click', () => adjustGrams(-50));
    if (minus10) minus10.addEventListener('click', () => adjustGrams(-10));
    if (plus10) plus10.addEventListener('click', () => adjustGrams(10));
    if (plus50) plus50.addEventListener('click', () => adjustGrams(50));

    if (gramInput) {
        gramInput.addEventListener('input', (e) => {
            const val = parseInt(e.target.value, 10) || 100;
            const uInfo = userActiveFoodForDetail?.unitInfo;
            if (uInfo && uInfo.hasUnit && unitInput) {
                unitInput.value = Math.max(0.5, Math.round((val / uInfo.gramsPerUnit) * 10) / 10);
            }
            if (userActiveFoodForDetail && userActiveFoodForDetail.updateLiveCalculations) {
                userActiveFoodForDetail.updateLiveCalculations(val);
            }
        });
    }

    // Steppers de Unidades
    const adjustUnits = (delta) => {
        if (!unitInput) return;
        const uInfo = userActiveFoodForDetail?.unitInfo;
        const gramsPerUnit = (uInfo && uInfo.gramsPerUnit) ? uInfo.gramsPerUnit : 100;
        let current = parseFloat(unitInput.value) || 1;
        let next = Math.max(0.5, Math.min(20, Math.round((current + delta) * 10) / 10));
        unitInput.value = next;

        const newGrams = Math.round(next * gramsPerUnit);
        if (gramInput) gramInput.value = newGrams;

        if (userActiveFoodForDetail && userActiveFoodForDetail.updateLiveCalculations) {
            userActiveFoodForDetail.updateLiveCalculations(newGrams);
        }
    };

    if (minusUnit) minusUnit.addEventListener('click', () => adjustUnits(-1));
    if (plusUnit) plusUnit.addEventListener('click', () => adjustUnits(1));

    if (unitInput) {
        unitInput.addEventListener('input', (e) => {
            const uInfo = userActiveFoodForDetail?.unitInfo;
            const gramsPerUnit = (uInfo && uInfo.gramsPerUnit) ? uInfo.gramsPerUnit : 100;
            const uVal = parseFloat(e.target.value) || 1;
            const newGrams = Math.round(uVal * gramsPerUnit);
            if (gramInput) gramInput.value = newGrams;
            if (userActiveFoodForDetail && userActiveFoodForDetail.updateLiveCalculations) {
                userActiveFoodForDetail.updateLiveCalculations(newGrams);
            }
        });
    }

    if (confirmBtn) {
        confirmBtn.addEventListener('click', () => {
            if (!userActiveFoodForDetail) return;
            const { resolved, item, athId, dateIso, isFromSearch, mealSlot } = userActiveFoodForDetail;
            const newGrams = gramInput ? parseInt(gramInput.value, 10) : 100;
            const foodKey = resolved?.id || resolved?.codigo || item.id || item.name;

            if (isFromSearch) {
                // Registrar comida seleccionada directamente en el día
                const customStorageKey = `sens_user_logged_meals_${athId}_${dateIso}`;
                let userCustomMeals = [];
                try {
                    userCustomMeals = JSON.parse(localStorage.getItem(customStorageKey) || '[]');
                } catch (e) {}

                const macros = (typeof window.calculateFoodMacros === 'function')
                    ? window.calculateFoodMacros(resolved, newGrams)
                    : { calories: Math.round(newGrams * 1.5), protein: 20, carbs: 15, fats: 5 };

                const newId = `custom-food-${resolved?.codigo || resolved?.id || Date.now()}-${Date.now()}`;
                userCustomMeals.push({
                    id: newId,
                    codigo: resolved?.codigo,
                    name: resolved?.nombre_alimento_o_plato || resolved?.name,
                    calories: macros.calories,
                    protein: macros.protein,
                    carbs: macros.carbs,
                    fats: macros.fats,
                    grams: newGrams,
                    isCustom: true,
                    mealSlot: mealSlot || 'almuerzo',
                    image: resolved?.image || resolved?.imagen_url
                });
                localStorage.setItem(customStorageKey, JSON.stringify(userCustomMeals));

                // Marcar automáticamente como consumida
                const consumedStorageKey = `sens_user_consumed_foods_${athId}_${dateIso}`;
                let userConsumedFoods = {};
                try {
                    userConsumedFoods = JSON.parse(localStorage.getItem(consumedStorageKey) || '{}');
                } catch (e) {}
                userConsumedFoods[newId] = true;
                localStorage.setItem(consumedStorageKey, JSON.stringify(userConsumedFoods));

                // Cerrar modal de búsqueda personalizada
                const customModal = document.getElementById('userCustomMealModal');
                if (customModal) {
                    customModal.classList.remove('active');
                }
            } else {
                const adjustStorageKey = `sens_user_adjusted_meals_${athId}_${dateIso}`;
                let userAdjusted = {};
                try {
                    userAdjusted = JSON.parse(localStorage.getItem(adjustStorageKey) || '{}');
                } catch (e) {}

                userAdjusted[foodKey] = newGrams;
                localStorage.setItem(adjustStorageKey, JSON.stringify(userAdjusted));
            }

            closeModal();
            const targetD = AppState.nutriSelectedDate || AppState.selectedDate || new Date();
            renderMemberNutritionPlan(athId, targetD);
            if (typeof renderNutriDaysNav === 'function') renderNutriDaysNav();
            if (typeof syncAllStreakAndPillTelemetry === 'function') {
                syncAllStreakAndPillTelemetry(targetD);
            } else {
                if (typeof updateObjectiveCardData === 'function') updateObjectiveCardData(targetD);
                if (typeof updateSensStreakCard === 'function') updateSensStreakCard(targetD);
            }

            if (typeof showSensToast === 'function') {
                const foodTitle = item.name || resolved?.nombre_alimento_o_plato || resolved?.name;
                const msg = isFromSearch
                    ? `${foodTitle} registrado en ${(mealSlot || 'Almuerzo').toUpperCase()} (${newGrams}g).`
                    : `Porción de ${foodTitle} ajustada a ${newGrams}g.`;
                showSensToast(msg, 'champagne');
            }
        });
    }

    const swapBtn = document.getElementById('btnOpenUfdSwapModal');
    if (swapBtn && !swapBtn._hasSwapModalBound) {
        swapBtn._hasSwapModalBound = true;
        swapBtn.addEventListener('click', () => {
            if (!userActiveFoodForDetail) return;
            const item = userActiveFoodForDetail.item;
            const slot = userActiveFoodForDetail.mealSlot;
            closeModal();
            openFoodSwapModal(item, slot);
        });
    }
}

/**
 * Inicializa Modal de Carga de Comida Personalizada (Fuera de Plan)
 */
function initUserCustomMealModal(athId) {
    const modal = document.getElementById('userCustomMealModal');
    const openBtn = document.getElementById('btnOpenCustomMealModal');
    const closeBtn = document.getElementById('btnCloseUserCustomMealModal');
    const tabSearch = document.getElementById('tabCustomSearchMode');
    const tabManual = document.getElementById('tabCustomManualMode');
    const paneSearch = document.getElementById('paneCustomSearch');
    const paneManual = document.getElementById('paneCustomManual');
    const searchInput = document.getElementById('customFoodSearchInput');
    const searchResults = document.getElementById('customSearchResultsList');
    const tray = document.getElementById('customSelectedIngredientsTray');
    const trayList = document.getElementById('customTrayItemsList');
    const trayTotalKcal = document.getElementById('customTrayTotalKcal');
    const saveBtn = document.getElementById('btnSaveCustomMealToDay');

    // Controles de Filtro Calórico (Item 8)
    const kcalChips = modal ? modal.querySelectorAll('#customKcalFilterRow .sens-kcal-chip') : [];
    const minInput = document.getElementById('customKcalMinInput');
    const maxInput = document.getElementById('customKcalMaxInput');
    const resetKcalBtn = document.getElementById('btnResetKcalFilter');
    window._sensActiveKcalRange = 'all';

    if (!modal) return;

    if (openBtn && !openBtn._hasCustomMealBound) {
        openBtn._hasCustomMealBound = true;
        openBtn.addEventListener('click', () => {
            userCustomTrayItems = [];
            window.renderCustomTray();
            modal.classList.add('active');
            document.body.classList.add('sens-modal-open');
            document.body.style.overflow = 'hidden';
            if (searchInput) {
                searchInput.value = '';
            }
            window._sensActiveKcalRange = 'all';
            window.renderCustomSearchResults('');
        });
    }

    if (modal._hasCustomLogicBound) {
        // Asegurar que siempre se expongan los helpers
        window.renderCustomSearchResults = window.renderCustomSearchResults || renderSearchResults;
        window.renderCustomTray = window.renderCustomTray || renderCustomTray;
        return;
    }
    modal._hasCustomLogicBound = true;

    const closeModal = () => {
        modal.classList.remove('active');
        document.body.style.overflow = '';
        setTimeout(() => {
            if (!document.querySelector('.sens-modal-sheet-wrap.active')) {
                document.body.classList.remove('sens-modal-open');
            }
        }, 50);
    };

    if (closeBtn) closeBtn.addEventListener('click', closeModal);
    modal.addEventListener('click', (e) => {
        if (e.target === modal) closeModal();
    });

    // Pestañas de Modo
    if (tabSearch && tabManual) {
        tabSearch.addEventListener('click', () => {
            tabSearch.style.color = '#E5CBA7';
            tabSearch.style.borderBottomColor = '#E5CBA7';
            tabSearch.style.background = 'transparent';
            tabManual.style.color = '#71717A';
            tabManual.style.borderBottomColor = 'transparent';
            tabManual.style.background = 'transparent';
            if (paneSearch) paneSearch.style.display = 'block';
            if (paneManual) paneManual.style.display = 'none';
        });
        tabManual.addEventListener('click', () => {
            tabManual.style.color = '#E5CBA7';
            tabManual.style.borderBottomColor = '#E5CBA7';
            tabManual.style.background = 'transparent';
            tabSearch.style.color = '#71717A';
            tabSearch.style.borderBottomColor = 'transparent';
            tabSearch.style.background = 'transparent';
            if (paneManual) paneManual.style.display = 'block';
            if (paneSearch) paneSearch.style.display = 'none';
        });
    }

    // Selector de Momento de Comida
    const slotPills = modal.querySelectorAll('#customMealSlotRow .sens-nutri-tab-pill');
    slotPills.forEach(pill => {
        pill.addEventListener('click', () => {
            slotPills.forEach(p => p.classList.remove('active'));
            pill.classList.add('active');
            userActiveNutriMealSlot = pill.getAttribute('data-slot') || 'almuerzo';
            renderSearchResults(searchInput ? searchInput.value : '');
        });
    });

    // Selector de Tipo de Ítem (Todos, Recetas, Alimentos Base, Vianda Fría)
    const typePills = modal.querySelectorAll('#customSearchTypeRow .sens-nutri-tab-pill');
    typePills.forEach(pill => {
        pill.addEventListener('click', () => {
            typePills.forEach(p => p.classList.remove('active'));
            pill.classList.add('active');
            window._sensActiveItemType = pill.getAttribute('data-type') || 'all';
            renderSearchResults(searchInput ? searchInput.value : '');
        });
    });

    // Renderizado de Tray con Botones de Marca SENS (Item 6)
    function renderCustomTray() {
        if (!tray || !trayList) return;
        if (userCustomTrayItems.length === 0) {
            tray.style.display = 'none';
            trayList.innerHTML = '';
            if (trayTotalKcal) trayTotalKcal.textContent = '0 kcal';
            return;
        }

        tray.style.display = 'block';
        let sumKcal = 0;

        trayList.innerHTML = userCustomTrayItems.map((item, idx) => {
            const macros = (typeof window.calculateFoodMacros === 'function')
                ? window.calculateFoodMacros(item.food, item.grams)
                : { calories: Math.round(item.grams * 1.5) };
            sumKcal += macros.calories;

            return `
                <div style="display: flex; justify-content: space-between; align-items: center; background: rgba(255,255,255,0.04); border-radius: 8px; padding: 6px 10px;">
                    <span style="font-size: 12px; color: #FFF; font-weight: 600;">${item.food.name}</span>
                    <div style="display: flex; align-items: center; gap: 8px;">
                        <input type="number" class="input-tray-grams" data-tray-idx="${idx}" value="${item.grams}" min="10" max="800" style="width: 55px; background: rgba(0,0,0,0.5); border: 1px solid rgba(255,255,255,0.15); color: #E5CBA7; font-size: 12px; padding: 2px 4px; border-radius: 4px; text-align: center;">
                        <span style="font-size: 11px; color: #E5CBA7; font-weight: 700;">${macros.calories} kcal</span>
                        <button type="button" class="sens-btn-remove-luxury btn-remove-tray-item" data-tray-idx="${idx}" title="Eliminar de la bandeja">
                            <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"><line x1="18" y1="6" x2="6" y2="18"></line><line x1="6" y1="6" x2="18" y2="18"></line></svg>
                        </button>
                    </div>
                </div>
            `;
        }).join('');

        if (trayTotalKcal) trayTotalKcal.textContent = `${sumKcal} kcal Totales`;

        // Eventos en inputs de gramos y eliminar
        trayList.querySelectorAll('.input-tray-grams').forEach(inp => {
            inp.addEventListener('input', (e) => {
                const idx = parseInt(e.target.getAttribute('data-tray-idx'), 10);
                const g = parseInt(e.target.value, 10) || 50;
                if (userCustomTrayItems[idx]) {
                    userCustomTrayItems[idx].grams = g;
                    renderCustomTray();
                }
            });
        });

        trayList.querySelectorAll('.btn-remove-tray-item').forEach(btn => {
            btn.addEventListener('click', () => {
                const idx = parseInt(btn.getAttribute('data-tray-idx'), 10);
                userCustomTrayItems.splice(idx, 1);
                renderCustomTray();
            });
        });
    }

    // Renderizado de Resultados de Búsqueda con Filtro de Calorías, Momento y Tipo (Bug #4 e Items 4 & 8)
    function renderSearchResults(query = '') {
        if (!searchResults) return;
        const library = (typeof getGlobalFoodCatalog === 'function') ? getGlobalFoodCatalog() : (window.SENS_FOOD_LIBRARY || []);
        if (!library || library.length === 0) {
            searchResults.innerHTML = `
                <div style="text-align: center; padding: 24px 14px; color: #A1A1AA; font-size: 12px; background: rgba(255,255,255,0.02); border-radius: 10px;">
                    Cargando biblioteca de alimentos...
                </div>
            `;
            return;
        }
        const norm = (str) => (typeof normalizeSensString === 'function') ? normalizeSensString(str) : (str ? str.toString().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim() : '');
        const q = norm(query);

        let matches = library;

        // 1. Filtro estricto por Momento de Ingesta (Bug #4)
        const currentSlot = userActiveNutriMealSlot || 'almuerzo';
        if (currentSlot === 'desayuno' || currentSlot === 'merienda') {
            matches = matches.filter(f => f.desayuno_merienda === true);
        } else if (currentSlot === 'almuerzo' || currentSlot === 'cena') {
            matches = matches.filter(f => f.almuerzo_cena === true);
        } else if (currentSlot === 'snack') {
            matches = matches.filter(f => f.snack === true);
        }

        // 2. Filtro por Tipo de Ítem (Segmented Control)
        const activeType = window._sensActiveItemType || 'all';
        if (activeType === 'Receta') {
            matches = matches.filter(f => f.tipo_item === 'Receta');
        } else if (activeType === 'Alimento Base') {
            matches = matches.filter(f => f.tipo_item === 'Alimento Base');
        } else if (activeType === 'vianda') {
            matches = matches.filter(f => f.apto_vianda_fria === true);
        }

        // 3. Filtro por Texto Búsqueda (Sin sensibilidad a acentos)
        if (q.length > 0) {
            matches = matches.filter(f => {
                return norm(f.name).includes(q) ||
                       norm(f.nombre_alimento_o_plato).includes(q) ||
                       norm(f.name_es).includes(q) ||
                       norm(f.name_en).includes(q) ||
                       norm(f.categoria_nutricional).includes(q) ||
                       norm(f.etiquetas_dieta_filtros).includes(q) ||
                       norm(f.codigo).includes(q);
            });
        }

        // 4. Filtro por rango de calorías
        const activeRange = window._sensActiveKcalRange || 'all';
        let minCal = 0;
        let maxCal = 99999;
        if (activeRange === 'under200') {
            maxCal = 200;
        } else if (activeRange === '200-400') {
            minCal = 200;
            maxCal = 400;
        } else if (activeRange === '400-600') {
            minCal = 400;
            maxCal = 600;
        } else if (activeRange === 'over600') {
            minCal = 600;
        } else if (activeRange === 'custom') {
            const minVal = parseInt(minInput?.value, 10);
            const maxVal = parseInt(maxInput?.value, 10);
            if (!isNaN(minVal)) minCal = minVal;
            if (!isNaN(maxVal)) maxCal = maxVal;
        }

        matches = matches.filter(f => {
            const cal = Number(f.calorias_kcal !== undefined ? f.calorias_kcal : (f.calories || 0)) || 0;
            return cal >= minCal && cal <= maxCal;
        });

        matches = matches.slice(0, 30);

        if (matches.length === 0) {
            searchResults.innerHTML = `
                <div style="text-align: center; padding: 24px 14px; color: #A1A1AA; font-size: 12px; background: rgba(255,255,255,0.02); border-radius: 10px; border: 1px dashed rgba(255,255,255,0.08);">
                    No se encontraron alimentos para "<strong>${escapeSensHtml(query)}</strong>" en el momento ${currentSlot} y filtros seleccionados.<br>Probá cambiar el filtro o usar la carga rápida de calorías.
                </div>
            `;
            return;
        }

        searchResults.innerHTML = matches.map(f => {
            const cal = Number(f.calorias_kcal !== undefined ? f.calorias_kcal : (f.calories || 0)) || 0;
            const prot = Number(f.proteinas_g !== undefined ? f.proteinas_g : (f.protein || 0)) || 0;
            const img = f.imagen_url || f.image || f.image_url || 'Nutricion/images/nut-001-pechuga-de-pollo-a-la-plancha.webp';
            const fid = f.id || f.codigo;
            const steps = f.paso_a_paso_preparacion || f.pasos_preparacion || 'Cocción saludable preservando micronutrientes.';
            const ingrs = f.ingredientes_y_gramajes || f.ingredientes_principales || 'Alimento natural de alta calidad biológica.';
            const foodName = f.nombre_alimento_o_plato || f.name || 'Alimento SENS';

            return `
                <div class="sens-search-result-card" style="flex-shrink: 0 !important; background: rgba(255,255,255,0.03); border: 1px solid rgba(255,255,255,0.08); border-radius: 12px; overflow: hidden; margin-bottom: 6px;">
                    <div style="display: flex; justify-content: space-between; align-items: center; padding: 8px 12px; gap: 8px;">
                        <div class="sens-search-card-click-trigger" data-food-id="${fid}" style="display: flex; align-items: center; gap: 10px; min-width: 0; flex: 1; cursor: pointer;" title="Toca para ver foto grande y desglose completo">
                            <img src="${img}" style="width: 44px; height: 44px; border-radius: 8px; object-fit: cover; flex-shrink: 0; background: #18181B; border: 1px solid rgba(255,255,255,0.1);" onerror="this.src='Nutricion/images/nut-001-pechuga-de-pollo-a-la-plancha.webp'">
                            <div style="min-width: 0; flex: 1;">
                                <div style="font-size: 13px; font-weight: 700; color: #FFF; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; text-overflow: ellipsis; line-height: 1.25;">${foodName}</div>
                                <div style="font-size: 11px; color: #71717A; font-variant-numeric: tabular-nums; margin-top: 2px;">
                                    ${f.porcion_total_g_ml || 100}g • <span style="color: #E5CBA7; font-weight: 700;">${cal} kcal</span> • <span style="color: #38BDF8;">${prot}g Prot</span>
                                    ${f.apto_vianda_fria ? ' • <span style="color: #93C5FD;">❄️ Vianda</span>' : ''}
                                </div>
                            </div>
                        </div>
                        <div style="display: flex; align-items: center; gap: 6px; flex-shrink: 0;">
                            <button type="button" class="btn btn-outline btn-sm btn-inspect-food-item" data-food-id="${fid}" style="padding: 4px 8px; font-size: 11px; border-color: rgba(229,203,167,0.35); color: #E5CBA7;" title="Ver foto y desglose completo">
                                <span>Detalle ↗</span>
                            </button>
                            <button type="button" class="btn btn-outline btn-sm btn-add-food-to-tray" data-food-id="${fid}" style="padding: 4px 10px; font-size: 11px; border-color: rgba(255,255,255,0.2); color: #FFFFFF;" title="Añadir a comida compuesta">
                                + Agregar
                            </button>
                        </div>
                    </div>
                </div>
            `;
        }).join('');

        // Listeners para agregar a bandeja
        searchResults.querySelectorAll('.btn-add-food-to-tray').forEach(btn => {
            btn.addEventListener('click', (e) => {
                e.stopPropagation();
                const fid = btn.getAttribute('data-food-id');
                const found = library.find(x => (x.id === fid || x.codigo === fid));
                if (found) {
                    userCustomTrayItems.push({
                        food: found,
                        grams: found.defaultGrams || found.porcion_total_g_ml || 100
                    });
                    renderCustomTray();
                    if (typeof showSensToast === 'function') {
                        showSensToast(`${found.name || found.nombre_alimento_o_plato} añadido a la bandeja.`, 'champagne');
                    }
                }
            });
        });

        // Listeners para ver desglose completo con foto grande (Item C)
        searchResults.querySelectorAll('.sens-search-card-click-trigger, .btn-inspect-food-item').forEach(el => {
            el.addEventListener('click', (e) => {
                e.stopPropagation();
                const fid = el.getAttribute('data-food-id');
                const found = library.find(x => (x.id === fid || x.codigo === fid));
                if (found) {
                    closeModal();
                    openUserFoodDetailModal(found, userActiveNutriMealSlot, true);
                }
            });
        });
    }

    window.renderCustomSearchResults = renderSearchResults;
    window.renderCustomTray = renderCustomTray;

    // Poblar inicialmente la lista de búsqueda
    renderSearchResults('');

    // Handlers de Filtros de Calorías (Item 8)
    const applyKcalFilter = () => {
        const q = searchInput ? searchInput.value : '';
        renderSearchResults(q);
    };

    kcalChips.forEach(chip => {
        chip.addEventListener('click', () => {
            kcalChips.forEach(c => c.classList.remove('active'));
            chip.classList.add('active');
            window._sensActiveKcalRange = chip.getAttribute('data-range') || 'all';
            if (minInput) minInput.value = '';
            if (maxInput) maxInput.value = '';
            applyKcalFilter();
        });
    });

    if (minInput) minInput.addEventListener('input', () => {
        kcalChips.forEach(c => c.classList.remove('active'));
        window._sensActiveKcalRange = 'custom';
        applyKcalFilter();
    });
    if (maxInput) maxInput.addEventListener('input', () => {
        kcalChips.forEach(c => c.classList.remove('active'));
        window._sensActiveKcalRange = 'custom';
        applyKcalFilter();
    });
    if (resetKcalBtn) {
        resetKcalBtn.addEventListener('click', () => {
            kcalChips.forEach(c => c.classList.remove('active'));
            const allChip = modal.querySelector('#customKcalFilterRow .sens-kcal-chip[data-range="all"]');
            if (allChip) allChip.classList.add('active');
            window._sensActiveKcalRange = 'all';
            if (minInput) minInput.value = '';
            if (maxInput) maxInput.value = '';
            applyKcalFilter();
        });
    }

    if (searchInput) {
        searchInput.addEventListener('input', (e) => {
            renderSearchResults(e.target.value);
        });
    }

    // Presets Rápidos en Modo Manual (Item 5)
    const presetChips = modal.querySelectorAll('#manualKcalPresetsWrap .sens-kcal-chip');
    presetChips.forEach(chip => {
        chip.addEventListener('click', () => {
            presetChips.forEach(c => c.classList.remove('active'));
            chip.classList.add('active');
            const k = parseInt(chip.getAttribute('data-kcal'), 10) || 500;
            const kcalInp = document.getElementById('manualMealKcalInput');
            const protInp = document.getElementById('manualMealProtInput');
            const carbsInp = document.getElementById('manualMealCarbsInput');
            const fatsInp = document.getElementById('manualMealFatsInput');
            if (kcalInp) kcalInp.value = k;
            if (protInp) protInp.value = Math.round((k * 0.30) / 4);
            if (carbsInp) carbsInp.value = Math.round((k * 0.45) / 4);
            if (fatsInp) fatsInp.value = Math.round((k * 0.25) / 9);
        });
    });

    // Botón Guardar Comida en el Día
    if (saveBtn) {
        saveBtn.addEventListener('click', () => {
            const sDate = AppState.nutriSelectedDate || new Date();
            if (isFutureDate(sDate)) {
                if (typeof showSensToast === 'function') {
                    showSensToast('No es posible registrar comidas de fechas futuras.', 'champagne', 2500);
                }
                return;
            }

            const activeAthId = athId || (typeof getActiveAthleteId === 'function' ? getActiveAthleteId() : 'mock_vip');
            const dateIso = `${sDate.getFullYear()}-${String(sDate.getMonth() + 1).padStart(2, '0')}-${String(sDate.getDate()).padStart(2, '0')}`;
            const customStorageKey = `sens_user_logged_meals_${activeAthId}_${dateIso}`;

            let userCustomMeals = [];
            try {
                userCustomMeals = JSON.parse(localStorage.getItem(customStorageKey) || '[]');
            } catch (e) {}

            const isManualActive = paneManual && paneManual.style.display === 'block';

            if (isManualActive) {
                const nameInp = document.getElementById('manualMealNameInput');
                const kcalInp = document.getElementById('manualMealKcalInput');
                const protInp = document.getElementById('manualMealProtInput');
                const carbsInp = document.getElementById('manualMealCarbsInput');
                const fatsInp = document.getElementById('manualMealFatsInput');

                const mealName = nameInp?.value.trim() || 'Comida Personalizada';
                const kcal = parseInt(kcalInp?.value, 10) || 450;
                const prot = parseFloat(protInp?.value) || 30;
                const carbs = parseFloat(carbsInp?.value) || 40;
                const fats = parseFloat(fatsInp?.value) || 12;

                const newCustomMeal = {
                    id: `custom-manual-${Date.now()}`,
                    name: mealName,
                    calories: kcal,
                    protein: prot,
                    carbs: carbs,
                    fats: fats,
                    grams: 100,
                    isCustom: true,
                    mealSlot: userActiveNutriMealSlot
                };
                userCustomMeals.push(newCustomMeal);

                if (nameInp) nameInp.value = '';
                if (kcalInp) kcalInp.value = '';
            } else {
                // Modo Búsqueda con Tray Multi-ingrediente
                if (userCustomTrayItems.length === 0) {
                    if (typeof showSensToast === 'function') {
                        showSensToast('Por favor seleccioná al menos un alimento o usá la carga rápida de calorías.', 'champagne');
                    }
                    return;
                }

                userCustomTrayItems.forEach(item => {
                    const macros = (typeof window.calculateFoodMacros === 'function')
                        ? window.calculateFoodMacros(item.food, item.grams)
                        : { calories: Math.round(item.grams * 1.5), protein: 20, carbs: 15, fats: 5 };

                    userCustomMeals.push({
                        id: `custom-food-${item.food.codigo || item.food.id}-${Date.now()}`,
                        name: item.food.name,
                        calories: macros.calories,
                        protein: macros.protein,
                        carbs: macros.carbs,
                        fats: macros.fats,
                        grams: item.grams,
                        isCustom: true,
                        mealSlot: userActiveNutriMealSlot,
                        image: item.food.image
                    });
                });
                userCustomTrayItems = [];
            }

            localStorage.setItem(customStorageKey, JSON.stringify(userCustomMeals));

            // Asegurar que las comidas registradas por el usuario queden marcadas como consumidas
            const consumedStorageKey = `sens_user_consumed_foods_${activeAthId}_${dateIso}`;
            let userConsumedFoods = {};
            try {
                userConsumedFoods = JSON.parse(localStorage.getItem(consumedStorageKey) || '{}');
            } catch (e) {}
            userCustomMeals.forEach(cm => {
                if (cm.id && userConsumedFoods[cm.id] === undefined) {
                    userConsumedFoods[cm.id] = true;
                }
            });
            localStorage.setItem(consumedStorageKey, JSON.stringify(userConsumedFoods));

            closeModal();
            renderMemberNutritionPlan(activeAthId, sDate);
            renderNutriDaysNav();

            if (typeof syncAllStreakAndPillTelemetry === 'function') {
                const streakEval = syncAllStreakAndPillTelemetry(sDate);
                const nutriStatus = streakEval?.current?.nutrition?.status;
                const prevStatus = streakEval?.previous?.nutrition?.status;
                const consumedKcal = streakEval?.current?.nutrition?.consumed || 0;
                const targetKcal = streakEval?.current?.nutrition?.target || 1950;

                if (nutriStatus === 'on_track' && prevStatus !== 'on_track') {
                    if (typeof window.showSensCelebrationToast === 'function') {
                        window.showSensCelebrationToast('¡Racha Nutricional Activa!', `Tus calorías (${consumedKcal.toLocaleString('es-AR')} kcal) quedaron en el rango óptimo (-20% / +10%).`);
                    }
                } else if (nutriStatus === 'exceeded') {
                    if (typeof showSensToast === 'function') {
                        showSensToast(`Perdiste el objetivo de racha nutricional de hoy: consumiste ${consumedKcal.toLocaleString('es-AR')} kcal (+10% del objetivo de ${targetKcal.toLocaleString('es-AR')} kcal).`, 'warning', 5000);
                    }
                } else if (prevStatus === 'on_track' && nutriStatus === 'pending') {
                    if (typeof showSensToast === 'function') {
                        showSensToast(`Perdiste el objetivo de racha nutricional de hoy: calorías consumidas (${consumedKcal.toLocaleString('es-AR')} kcal) quedaron debajo del mínimo óptimo.`, 'warning', 4500);
                    }
                }
            } else {
                if (typeof updateObjectiveCardData === 'function') updateObjectiveCardData(sDate);
                if (typeof SensDailyStreakManager !== 'undefined') {
                    SensDailyStreakManager.evaluateDay(sDate, activeAthId);
                }
                if (typeof updateSensStreakCard === 'function') updateSensStreakCard(sDate);
            }

            if (typeof showSensToast === 'function') {
                showSensToast(`Comida registrada con éxito en ${userActiveNutriMealSlot.toUpperCase()}.`, 'champagne');
            }
        });
    }
}

/**
 * Event Listeners de Filtro por Comida y Navegador Semanal en Vista de Nutrición (Item 3)
 */
function initUserNutritionFilterAndDateListeners() {
    const filterRow = document.getElementById('memberNutriFilterRow');
    if (filterRow && !filterRow._hasNutriFilterBound) {
        filterRow._hasNutriFilterBound = true;
        filterRow.addEventListener('click', (e) => {
            const btn = e.target.closest('.sens-nutri-tab-pill');
            if (!btn) return;
            filterRow.querySelectorAll('.sens-nutri-tab-pill').forEach(b => b.classList.remove('active'));
            btn.classList.add('active');
            AppState.activeNutriFilter = btn.getAttribute('data-filter') || 'todas';
            const athId = (typeof getActiveAthleteId === 'function') ? getActiveAthleteId() : 'mock_vip';
            renderMemberNutritionPlan(athId, AppState.nutriSelectedDate || new Date());
        });
    }

    // Botones de Navegación Semanal en Nutrición (Paridad 1:1 con Inicio y Entrenamiento)
    const btnNutriPrev = document.getElementById('btnNutriWeekPrev');
    const btnNutriNext = document.getElementById('btnNutriWeekNext');
    const btnNutriToday = document.getElementById('btnNutriJumpToToday');

    if (btnNutriPrev && !btnNutriPrev._hasNutriNavBound) {
        btnNutriPrev._hasNutriNavBound = true;
        btnNutriPrev.addEventListener('click', () => {
            navigateCalendarWeek('prev');
        });
    }

    if (btnNutriNext && !btnNutriNext._hasNutriNavBound) {
        btnNutriNext._hasNutriNavBound = true;
        btnNutriNext.addEventListener('click', () => {
            navigateCalendarWeek('next');
        });
    }

    if (btnNutriToday && !btnNutriToday._hasNutriNavBound) {
        btnNutriToday._hasNutriNavBound = true;
        btnNutriToday.addEventListener('click', () => {
            const today = new Date();
            AppState.activeWeekStart = getMonday(today);
            AppState.selectedDate = today;
            AppState.nutriSelectedDate = today;
            AppState.currentDay = getDayKeyFromDate(today);

            renderDynamicWeekStrip();
            renderWorkoutDaysNav();
            renderNutriDaysNav();

            const athId = (typeof getActiveAthleteId === 'function') ? getActiveAthleteId() : 'mock_vip';
            renderMemberNutritionPlan(athId, today);
            if (typeof updateObjectiveCardData === 'function') updateObjectiveCardData(today);
            if (typeof updateDynamicTrainingCard === 'function') updateDynamicTrainingCard(today, AppState.currentDay);
            if (typeof updateNutriSummaryCardData === 'function') updateNutriSummaryCardData();
            if (typeof syncAllStreakAndPillTelemetry === 'function') syncAllStreakAndPillTelemetry(today);
            if (typeof renderWeeklyBalanceChart === 'function') renderWeeklyBalanceChart(today);
            showSensToast('Semana actual', 'champagne', 1500);
        });
    }

    if (typeof initCalendarSwipeGestures === 'function') {
        initCalendarSwipeGestures();
    }
}

// =========================================================================
// EXPERIENCIA 2: RECOMENDADOR INTELIGENTE "CLAVAR MIS MACROS"
// =========================================================================
function renderSmartMacroRecommender(allDayFoods, athId, targetKcal, consumedKcal, targetProt, consumedProt) {
    const card = document.getElementById('sensSmartMacroRecommender');
    const meta = document.getElementById('recommenderRemainingMeta');
    const container = document.getElementById('smartRecommenderSuggestions');
    if (!card || !container) return;

    const remKcal = targetKcal - consumedKcal;
    const remProt = Math.max(0, targetProt - consumedProt);

    if (remKcal < 60) {
        card.style.display = 'none';
        return;
    }

    card.style.display = 'block';
    if (meta) {
        meta.textContent = `Faltan ${remKcal.toLocaleString('es-AR')} kcal • ${Math.round(remProt)}g Prot`;
    }

    const library = (typeof SENS_FOOD_LIBRARY !== 'undefined' && Array.isArray(SENS_FOOD_LIBRARY))
        ? SENS_FOOD_LIBRARY
        : (typeof FOOD_CATALOG !== 'undefined' ? FOOD_CATALOG : []);

    // Platos que se acerquen al déficit calórico restante y aporten proteína
    const candidates = library.filter(f => {
        const cal = Number(f.calorias_kcal || f.calories || 0);
        return cal >= Math.max(70, Math.round(remKcal * 0.4)) && cal <= (remKcal + 60);
    });

    candidates.sort((a, b) => {
        const calA = Number(a.calorias_kcal || a.calories || 0);
        const calB = Number(b.calorias_kcal || b.calories || 0);
        const pA = Number(a.proteinas_g || a.protein || 0);
        const pB = Number(b.proteinas_g || b.protein || 0);
        const scoreA = Math.abs(remKcal - calA) - (pA * 2);
        const scoreB = Math.abs(remKcal - calB) - (pB * 2);
        return scoreA - scoreB;
    });

    const topSuggestions = candidates.slice(0, 3);
    if (topSuggestions.length === 0) {
        card.style.display = 'none';
        return;
    }

    container.innerHTML = topSuggestions.map(dish => {
        const img = dish.imagen_url || dish.image || 'Nutricion/images/nut-001-pechuga-de-pollo-a-la-plancha.webp';
        const cal = dish.calorias_kcal || dish.calories || 0;
        const p = Math.round(dish.proteinas_g || dish.protein || 0);
        const name = dish.nombre_alimento_o_plato || dish.name || 'Plato SENS';
        const fid = dish.id || dish.codigo;

        return `
            <div class="sens-recom-dish-chip" data-dish-code="${dish.codigo || fid}" title="Tocar para ver o sumar">
                <div style="display: flex; align-items: center; gap: 8px;">
                    <img src="${img}" style="width: 32px; height: 32px; border-radius: 6px; object-fit: cover;" onerror="this.src='Nutricion/images/nut-001-pechuga-de-pollo-a-la-plancha.webp'">
                    <div style="min-width: 0; flex: 1;">
                        <span style="font-size: 11.5px; font-weight: 700; color: #FFFFFF; display: -webkit-box; -webkit-line-clamp: 1; -webkit-box-orient: vertical; overflow: hidden;">${name}</span>
                        <span style="font-size: 10px; color: #E5CBA7; font-weight: 700;">${cal} kcal • ${p}g P</span>
                    </div>
                </div>
            </div>
        `;
    }).join('');

    container.querySelectorAll('.sens-recom-dish-chip').forEach(chip => {
        chip.addEventListener('click', () => {
            const code = chip.getAttribute('data-dish-code');
            const found = library.find(x => x.codigo === code || x.id === code);
            if (found) {
                openUserFoodDetailModal(found, 'snack');
            }
        });
    });
}

// =========================================================================
// EXPERIENCIA 1: MODAL DE INTERCAMBIO POR EQUIVALENTE (SWAP INTELIGENTE)
// =========================================================================
function openFoodSwapModal(foodItem, mealSlot, onSwapCallback = null) {
    window.openFoodSwapModal = openFoodSwapModal;
    const modal = document.getElementById('userFoodSwapModal');
    const nameEl = document.getElementById('swapCurrentFoodName');
    const listEl = document.getElementById('userFoodSwapList');
    if (!modal || !listEl) return;

    const athId = (typeof getActiveAthleteId === 'function') ? getActiveAthleteId() : 'mock_vip';
    const resolved = (typeof window.getResolvedFood === 'function')
        ? window.getResolvedFood(foodItem, athId)
        : foodItem;

    if (nameEl) nameEl.textContent = resolved?.nombre_alimento_o_plato || resolved?.name || 'Alimento actual';

    const library = (typeof SENS_FOOD_LIBRARY !== 'undefined' && Array.isArray(SENS_FOOD_LIBRARY))
        ? SENS_FOOD_LIBRARY
        : (typeof FOOD_CATALOG !== 'undefined' ? FOOD_CATALOG : []);

    const targetCal = Number(resolved?.calorias_kcal || resolved?.calories || 200) || 200;
    const targetProt = Number(resolved?.proteinas_g || resolved?.protein || 20) || 20;

    let alternatives = library.filter(f => {
        if (f.codigo === resolved?.codigo || f.id === resolved?.id) return false;
        if (mealSlot === 'desayuno' || mealSlot === 'merienda') {
            if (!f.desayuno_merienda) return false;
        } else if (mealSlot === 'almuerzo' || mealSlot === 'cena') {
            if (!f.almuerzo_cena) return false;
        } else if (mealSlot === 'snack') {
            if (!f.snack) return false;
        }
        const cal = Number(f.calorias_kcal || f.calories || 0);
        return cal >= (targetCal * 0.75) && cal <= (targetCal * 1.3);
    });

    alternatives.sort((a, b) => {
        const calA = Number(a.calorias_kcal || a.calories || 0);
        const calB = Number(b.calorias_kcal || b.calories || 0);
        return Math.abs(calA - targetCal) - Math.abs(calB - targetCal);
    });

    alternatives = alternatives.slice(0, 8);

    if (alternatives.length === 0) {
        listEl.innerHTML = `<div style="padding: 16px; color: #A1A1AA; font-size: 12px; text-align: center;">No hay equivalentes directos en el rango calórico para este momento.</div>`;
    } else {
        listEl.innerHTML = alternatives.map(alt => {
            const cal = Number(alt.calorias_kcal || alt.calories || 0);
            const prot = Number(alt.proteinas_g || alt.protein || 0);
            const img = alt.imagen_url || alt.image || 'Nutricion/images/nut-001-pechuga-de-pollo-a-la-plancha.webp';
            const name = alt.nombre_alimento_o_plato || alt.name;
            const altCode = alt.codigo || alt.id;

            return `
                <div class="sens-swap-item-card">
                    <img src="${img}" style="width: 44px; height: 44px; border-radius: 8px; object-fit: cover; background: #18181B;" onerror="this.src='Nutricion/images/nut-001-pechuga-de-pollo-a-la-plancha.webp'">
                    <div style="flex: 1; min-width: 0;">
                        <strong style="font-size: 13px; color: #FFF; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; line-height: 1.25;">${name}</strong>
                        <div style="font-size: 11px; color: #71717A; margin-top: 2px;">
                            ${alt.porcion_total_g_ml || 100}g • <span style="color: #E5CBA7; font-weight: 700;">${cal} kcal</span> • <span style="color: #38BDF8;">${prot}g P</span>
                        </div>
                    </div>
                    <button type="button" class="btn btn-outline btn-sm btn-confirm-swap" data-swap-code="${altCode}" style="border-color: rgba(229,203,167,0.4); color: #E5CBA7; font-size: 11.5px; padding: 6px 12px; border-radius: 8px; font-weight: 700; white-space: nowrap;">
                        Elegir plato
                    </button>
                </div>
            `;
        }).join('');

        listEl.querySelectorAll('.btn-confirm-swap').forEach(btn => {
            btn.addEventListener('click', () => {
                const swapCode = btn.getAttribute('data-swap-code');
                const selectedAlt = alternatives.find(a => (a.codigo === swapCode || a.id === swapCode));
                if (!selectedAlt) return;

                if (typeof onSwapCallback === 'function') {
                    onSwapCallback(selectedAlt);
                    modal.classList.remove('active');
                    document.body.style.overflow = '';
                    setTimeout(() => {
                        if (!document.querySelector('.sens-modal-sheet-wrap.active')) {
                            document.body.classList.remove('sens-modal-open');
                        }
                    }, 50);
                    return;
                }

                const sDate = AppState.nutriSelectedDate || new Date();
                const dateIso = `${sDate.getFullYear()}-${String(sDate.getMonth() + 1).padStart(2, '0')}-${String(sDate.getDate()).padStart(2, '0')}`;
                const customStorageKey = `sens_user_logged_meals_${athId}_${dateIso}`;

                let userCustomMeals = [];
                try {
                    userCustomMeals = JSON.parse(localStorage.getItem(customStorageKey) || '[]');
                } catch (e) {}

                const macros = window.calculateFoodMacros(selectedAlt, selectedAlt.porcion_total_g_ml || 150);
                userCustomMeals.push({
                    id: `swap-${selectedAlt.codigo || selectedAlt.id}-${Date.now()}`,
                    codigo: selectedAlt.codigo,
                    name: selectedAlt.nombre_alimento_o_plato || selectedAlt.name,
                    calories: macros.calories,
                    protein: macros.protein,
                    carbs: macros.carbs,
                    fats: macros.fats,
                    grams: macros.grams,
                    isCustom: true,
                    mealSlot: mealSlot,
                    image: selectedAlt.imagen_url || selectedAlt.image
                });

                localStorage.setItem(customStorageKey, JSON.stringify(userCustomMeals));

                modal.classList.remove('active');
                document.body.style.overflow = '';
                setTimeout(() => {
                    if (!document.querySelector('.sens-modal-sheet-wrap.active')) {
                        document.body.classList.remove('sens-modal-open');
                    }
                }, 50);
                renderMemberNutritionPlan(athId, sDate);

                if (typeof showSensToast === 'function') {
                    showSensToast(`Plato reemplazado por "${selectedAlt.nombre_alimento_o_plato || selectedAlt.name}".`, 'champagne', 3000);
                }
            });
        });
    }

    modal.classList.add('active');
    document.body.classList.add('sens-modal-open');
    document.body.style.overflow = 'hidden';
}

function initUserFoodSwapModal() {
    const modal = document.getElementById('userFoodSwapModal');
    const closeBtn = document.getElementById('btnCloseUserFoodSwapModal');
    if (!modal || modal._hasSwapBound) return;
    modal._hasSwapBound = true;

    const closeModal = () => {
        modal.classList.remove('active');
        document.body.style.overflow = '';
        setTimeout(() => {
            if (!document.querySelector('.sens-modal-sheet-wrap.active')) {
                document.body.classList.remove('sens-modal-open');
            }
        }, 50);
    };

    if (closeBtn) closeBtn.addEventListener('click', closeModal);
    modal.addEventListener('click', (e) => {
        if (e.target === modal) closeModal();
    });
}

