/**
 * Determina el micro-badge con iconos chicos por grupo muscular (hasta 3 iconos por pill)
 */
function getDayFocusBadge(dayData, dayDate = null) {
    const athId = getActiveAthleteId();
    let isCompleted = false;
    if (dayDate) {
        const execution = getAthleteWorkoutExecution(athId, dayDate);
        isCompleted = Boolean(execution && execution.completed);
    } else {
        isCompleted = Boolean(dayData && dayData.completed);
    }
    if (isCompleted) {
        return '<span class="sens-day-badge done" title="Entrenamiento completado">✓</span>';
    }
    const exercises = (dayData && Array.isArray(dayData.exercises)) ? dayData.exercises : [];
    if (exercises.length === 0) {
        const titleLower = ((dayData && dayData.title) || '').toLowerCase();
        if (titleLower.includes('descanso') || titleLower.includes('rest')) {
            return '<span class="sens-day-badge rest" title="Descanso">–</span>';
        }
        return '<span class="sens-day-badge rest">–</span>';
    }

    const sourceLib = (typeof SENS_EXERCISE_LIBRARY !== 'undefined') ? SENS_EXERCISE_LIBRARY : (typeof EXERCISE_CATALOG !== 'undefined' ? EXERCISE_CATALOG : []);
    const iconKeys = [];
    const labelSet = new Set();

    exercises.forEach(ex => {
        const rawMatch = sourceLib.find(c => c.id === ex.id || c.name.toLowerCase() === ex.name.toLowerCase()) || ex;
        const tax = (typeof getExerciseTaxonomy === 'function') 
            ? getExerciseTaxonomy(rawMatch) 
            : { type: 'muscular', muscleGroup: 'piernas', muscleLabel: 'Piernas' };
        
        if (tax.type === 'yoga') {
            iconKeys.push('yoga');
            labelSet.add('Yoga');
        } else if (tax.type === 'cardio') {
            iconKeys.push('cardio');
            labelSet.add('Cardio');
        } else if (tax.type === 'movilidad') {
            iconKeys.push('movilidad');
            labelSet.add('Movilidad');
        } else {
            const mg = (tax.muscleGroup || '').toLowerCase();
            const ml = (tax.muscleLabel || '').toLowerCase();
            if (mg.includes('pecho') || ml.includes('pecho')) {
                iconKeys.push('pecho');
                labelSet.add('Pecho');
            } else if (mg.includes('espalda') || ml.includes('espalda')) {
                iconKeys.push('espalda');
                labelSet.add('Espalda');
            } else if (mg.includes('pierna') || mg.includes('quad') || mg.includes('glute') || ml.includes('pierna') || ml.includes('cuádricep') || ml.includes('glúteo')) {
                iconKeys.push('piernas');
                labelSet.add('Piernas');
            } else if (mg.includes('core') || mg.includes('abdom') || ml.includes('core')) {
                iconKeys.push('core');
                labelSet.add('Core');
            } else if (['biceps', 'triceps', 'hombros', 'brazos'].some(b => mg.includes(b) || ml.includes(b))) {
                iconKeys.push('brazos');
                labelSet.add('Brazos');
            } else {
                iconKeys.push('piernas');
                labelSet.add('Fuerza');
            }
        }
    });

    const uniqueKeys = Array.from(new Set(iconKeys)).slice(0, 3);
    if (uniqueKeys.length === 0) {
        return '<span class="sens-day-badge rest">–</span>';
    }

    const iconsHtml = uniqueKeys.map(k => SENS_MUSCLE_MICRO_ICONS[k] || SENS_MUSCLE_MICRO_ICONS.brazos).join('');
    const tooltipText = Array.from(labelSet).join(' • ');
    return `<div class="sens-pill-icons-row" title="${tooltipText}">${iconsHtml}</div>`;
}

/**
 * Renderiza el calendario de 7 días (id="workoutDaysNav") con paridad 1:1 con la Home
 * Mostrando en micro-pills hasta 3 micro-iconos por grupo muscular
 */
function renderWorkoutDaysNav() {
    const container = document.getElementById('workoutDaysNav');
    if (!container) return;

    if (!AppState.activeWeekStart) {
        AppState.activeWeekStart = getMonday(new Date());
    }

    const rangeLabel = document.getElementById('sensWorkoutWeekRangeLabel');
    if (rangeLabel && typeof getWeekRangeLabel === 'function') {
        rangeLabel.textContent = getWeekRangeLabel(AppState.activeWeekStart);
    }

    const athId = getActiveAthleteId();
    const data = getCoachAthleteWorkoutData(athId);
    const dayNames = ['LUN', 'MAR', 'MIÉ', 'JUE', 'VIE', 'SÁB', 'DOM'];
    let html = '';

    for (let i = 0; i < 7; i++) {
        const dayDate = new Date(AppState.activeWeekStart);
        dayDate.setDate(AppState.activeWeekStart.getDate() + i);

        const isToday = isSameDay(dayDate, new Date());
        const isSelected = isSameDay(dayDate, AppState.selectedDate || new Date());
        const dayKey = 'day' + (i + 1);
        const dKey = formatDateKey(dayDate);
        const dayData = (data && data.calendar_schedule && data.calendar_schedule[dKey])
            ? data.calendar_schedule[dKey]
            : (data && data[dayKey] ? data[dayKey] : {});
        const heroNum = dayDate.getDate();

        // Estado limpio y consistente con la sección de Inicio (Cero píldoras de tipo de ejercicio)
        const modality = dayData.modality;
        const execution = getAthleteWorkoutExecution(athId, dayDate);
        const isCompleted = Boolean(execution && execution.completed);

        const todayStart = new Date();
        todayStart.setHours(0, 0, 0, 0);
        const dayDateStart = new Date(dayDate);
        dayDateStart.setHours(0, 0, 0, 0);
        const isPast = dayDateStart < todayStart;
        const hasExercises = Boolean(dayData.exercises && dayData.exercises.length > 0) && !dayData.isRestDay;

        let badgeHtml = '';
        if (isCompleted) {
            badgeHtml = `<span class="sens-day-badge done" title="Entrenamiento completado">✓</span>`;
        } else if (isPast) {
            if (modality === 'presencial' || modality === 'online' || modality === 'autonomo' || hasExercises) {
                badgeHtml = `<span class="sens-day-badge missed" title="No realizado">✕</span>`;
            } else {
                badgeHtml = `<span class="sens-day-badge rest" title="Descanso">–</span>`;
            }
        } else if (isToday) {
            badgeHtml = `<span class="sens-day-badge today" title="Hoy">Hoy</span>`;
        } else if (hasExercises || modality === 'presencial' || modality === 'online' || modality === 'autonomo') {
            badgeHtml = `<span class="sens-day-badge future-routine" title="Rutina programada">Rutina</span>`;
        } else {
            badgeHtml = `<span class="sens-day-badge future-rest" title="Descanso">Descanso</span>`;
        }

        html += `
            <button type="button" class="sens-week-day-pill ${isSelected ? 'active' : ''} ${isToday ? 'is-today' : ''}" data-day-key="${dayKey}" data-date="${formatDateKey(dayDate)}">
                <span class="sens-day-name">${dayNames[i]}</span>
                <span class="sens-day-hero-num">${heroNum}</span>
                <div class="sens-day-modality-indicator">${badgeHtml}</div>
            </button>
        `;
    }

    container.innerHTML = html;

    container.querySelectorAll('.sens-week-day-pill').forEach((pill, idx) => {
        pill.addEventListener('click', () => {
            container.querySelectorAll('.sens-week-day-pill').forEach(p => p.classList.remove('active'));
            pill.classList.add('active');

            const dayDate = new Date(AppState.activeWeekStart);
            dayDate.setDate(AppState.activeWeekStart.getDate() + idx);
            AppState.selectedDate = dayDate;
            AppState.nutriSelectedDate = dayDate;
            const dayKey = 'day' + (idx + 1);
            AppState.currentDay = dayKey;

            renderWorkoutDay(dayKey, dayDate);
            renderWorkoutDaysNav();
            if (typeof renderDynamicWeekStrip === 'function') renderDynamicWeekStrip();
            if (typeof updateObjectiveCardData === 'function') updateObjectiveCardData(dayDate);
            if (typeof syncAllStreakAndPillTelemetry === 'function') {
                syncAllStreakAndPillTelemetry(dayDate);
            }
        });
    });
}

