/**
 * Deduce taxonomía, tipos y título dinámico de la sesión
 */
function getWorkoutSessionDetails(exercises, fallbackTitle = '', athId = null) {
    if (!Array.isArray(exercises) || exercises.length === 0) {
        return {
            title: fallbackTitle ? fallbackTitle.replace(/^Día\s*\d+:\s*/i, '') : 'Descanso Activo',
            subtitle: 'Recuperación neuromuscular y regeneración tisular',
            types: [],
            totalSets: 0,
            totalKcal: 0,
            estMinutes: 0
        };
    }

    const typesSet = new Set();
    const muscleSetCount = {};
    let totalSets = 0;
    let totalWorkoutKcal = 0;
    const userWeight = parseFloat(AppState.profile?.current_weight || AppState.anamnesis?.weight || 75) || 75;

    exercises.forEach(ex => {
        const resolved = (typeof window.getResolvedExercise === 'function') 
            ? window.getResolvedExercise(ex, athId) 
            : ex;

        const tax = (typeof getExerciseTaxonomy === 'function') 
            ? getExerciseTaxonomy(resolved) 
            : { type: 'muscular', typeLabel: 'Muscular', muscleGroup: 'piernas', muscleLabel: 'Piernas' };

        const type = (tax.type || 'muscular').toLowerCase();
        typesSet.add(type);

        const s = parseInt(ex.sets, 10);
        const setCount = (!isNaN(s) && s > 0) ? s : 3;
        totalSets += setCount;

        if (type === 'muscular') {
            const mLabel = tax.muscleLabel || 'Piernas';
            muscleSetCount[mLabel] = (muscleSetCount[mLabel] || 0) + setCount;
        }

        const kcalData = (typeof window.calculateExerciseKcal === 'function')
            ? window.calculateExerciseKcal(resolved, setCount, ex.reps || 10, userWeight)
            : { kcalPerSet: 7, totalKcal: setCount * 7 };
        totalWorkoutKcal += (kcalData.totalKcal || (setCount * 7));
    });

    // 1. Construir Título Dinámico: Músculos principales o en su defecto tipo
    const sortedMuscles = Object.keys(muscleSetCount).sort((a, b) => muscleSetCount[b] - muscleSetCount[a]);

    const otherTypeLabels = [];
    if (typesSet.has('cardio')) otherTypeLabels.push('Cardio');
    if (typesSet.has('yoga')) otherTypeLabels.push('Yoga');
    if (typesSet.has('movilidad')) otherTypeLabels.push('Movilidad');

    let dynamicTitle = '';
    if (sortedMuscles.length === 1) {
        dynamicTitle = sortedMuscles[0];
    } else if (sortedMuscles.length === 2) {
        dynamicTitle = `${sortedMuscles[0]} y ${sortedMuscles[1]}`;
    } else if (sortedMuscles.length === 3) {
        dynamicTitle = `${sortedMuscles[0]}, ${sortedMuscles[1]} y ${sortedMuscles[2]}`;
    } else if (sortedMuscles.length >= 4) {
        dynamicTitle = 'Cuerpo Completo';
    }

    if (!dynamicTitle) {
        // En su defecto tipo si no hay grupos musculares
        if (otherTypeLabels.length === 1) {
            dynamicTitle = otherTypeLabels[0];
        } else if (otherTypeLabels.length > 1) {
            dynamicTitle = otherTypeLabels.join(' y ');
        } else {
            dynamicTitle = fallbackTitle ? fallbackTitle.replace(/^(Lunes|Martes|Miércoles|Jueves|Viernes|Sábado|Domingo|Día\s*\d+)[:\s-]*/i, '').trim() : 'Entrenamiento Funcional';
        }
    } else if (otherTypeLabels.length > 0 && sortedMuscles.length <= 2) {
        dynamicTitle = `${dynamicTitle} & ${otherTypeLabels.join(' & ')}`;
    }

    // 2. Subtítulo con métricas reales: X ejercicios | Y series (sin la palabra Volumen)
    const subtitle = `${exercises.length} ejercicios | ${totalSets} series`;

    const estMinutes = Math.max(25, Math.round(exercises.length * 8.5 + 5));

    return {
        title: dynamicTitle,
        subtitle,
        types: Array.from(typesSet),
        totalSets,
        totalKcal: Math.round(totalWorkoutKcal),
        estMinutes
    };
}

/**
 * Actualiza la Card de Entrenamiento del Dashboard con video y taxonomía automática
 */

/**
 * Helper de Gobernanza para Skeletons de Video (Zero CLS / Quiet Luxury)
 * Muestra el shimmer durante buffering/loadstart y desvanece suavemente en canplay/playing.
 */
function attachVideoSkeleton(videoEl, skeletonEl) {
    if (!videoEl || !skeletonEl) return;
    if (videoEl._hasSkeletonAttached) return;
    videoEl._hasSkeletonAttached = true;

    const hide = () => skeletonEl.classList.add('is-hidden');
    const show = () => skeletonEl.classList.remove('is-hidden');

    if (videoEl.readyState >= 3) {
        hide();
    } else {
        show();
    }

    videoEl.addEventListener('loadstart', show);
    videoEl.addEventListener('waiting', show);
    videoEl.addEventListener('loadeddata', hide);
    videoEl.addEventListener('canplay', hide);
    videoEl.addEventListener('playing', hide);
    videoEl.addEventListener('error', hide);
}
window.attachVideoSkeleton = attachVideoSkeleton;

function updateDynamicTrainingCard(selectedDate = new Date(), dayKey = null) {
    if (!dayKey) {
        dayKey = getDayKeyFromDate(selectedDate);
    }

    const activePane = document.getElementById('dashWorkoutActivePane');
    const restPane = document.getElementById('dashWorkoutRestPane');
    const videoPlayer = document.getElementById('dashWorkoutVideoPlayer');
    const videoSource = document.getElementById('dashWorkoutVideoSource');
    const modalityPill = document.getElementById('dashWorkoutModalityPill');
    const typeIconsWrap = document.getElementById('dashWorkoutTypeIconsWrap');
    const durationPill = document.getElementById('dashWorkoutDurationPill');
    const dayDateLabel = document.getElementById('dashWorkoutDayDateLabel');
    const focusTitle = document.getElementById('dashWorkoutFocusTitle');
    const subFocus = document.getElementById('dashWorkoutSubFocus');

    const athId = getActiveAthleteId();
    const hasRoutine = athleteHasAssignedRoutine(athId);
    const data = getCoachAthleteWorkoutData(athId);
    const dateIso = getFormattedDateKey(selectedDate);
    const dayData = (data && data.calendar_schedule && data.calendar_schedule[dateIso])
        ? data.calendar_schedule[dateIso]
        : ((data && data[dayKey]) ? data[dayKey] : null);
    const isRest = dayData?.isRestDay || dayData?.modality === 'descanso';
    const exercises = (!isRest && dayData && Array.isArray(dayData.exercises)) ? dayData.exercises : [];
    const isToday = isSameDay(selectedDate, new Date());

    // Label de fecha/dominio superior (Eyebrow Champagne)
    if (dayDateLabel) {
        dayDateLabel.textContent = isToday ? 'Entrenamiento de Hoy' : `Entrenamiento del ${formatDateDDMM(selectedDate)}`;
    }

    // Caso A: Descanso o sin ejercicios asignados
    if (!hasRoutine || exercises.length === 0 || isRest) {
        if (activePane) activePane.style.display = 'none';
        if (restPane) restPane.style.display = 'block';
        if (typeof updateHomeCardsStreakPills === 'function') {
            updateHomeCardsStreakPills(selectedDate, athId);
        }
        return;
    }

    // Caso B: Con entrenamiento programado
    if (activePane) activePane.style.display = 'block';
    if (restPane) restPane.style.display = 'none';

    // 1. Obtener detalles de sesión y título dinámico
    const details = getWorkoutSessionDetails(exercises, dayData.title, athId);

    if (focusTitle && focusTitle.textContent !== details.title) {
        focusTitle.textContent = details.title;
    }
    if (subFocus && subFocus.textContent !== details.subtitle) {
        subFocus.textContent = details.subtitle;
    }

    // 2. Fila de los 4 tipos de entrenamiento (Muscular, Cardio, Movilidad, Yoga) al fondo con icono y label
    if (typeIconsWrap) {
        const ALL_TYPES = ['muscular', 'cardio', 'movilidad', 'yoga'];
        typeIconsWrap.innerHTML = ALL_TYPES.map(typeKey => {
            const info = SENS_TYPE_ICONS[typeKey];
            if (!info) return '';
            const isActive = details.types.includes(typeKey);
            const activeClass = isActive ? 'active highlight' : 'inactive';
            const tooltip = isActive ? `${info.label}: Estimulado hoy` : `${info.label}: No incluido`;
            return `<div class="sens-type-chip ${activeClass}" title="${tooltip}">
                <span class="type-chip-icon">${info.svg}</span>
                <span class="type-chip-label">${info.label}</span>
            </div>`;
        }).join('');
    }

    // 3. Modality Pill y Badge de Calorías Totales + Tiempo Promedio
    const modality = dayData.modality;
    if (modalityPill) {
        if (modality === 'presencial') {
            modalityPill.textContent = 'Presencial';
            modalityPill.className = 'sens-modality-pill';
            modalityPill.style.display = 'inline-flex';
        } else if (modality === 'online') {
            modalityPill.textContent = 'Online';
            modalityPill.className = 'sens-modality-pill online';
            modalityPill.style.display = 'inline-flex';
        } else if (modality === 'autonomo') {
            modalityPill.textContent = 'Autónomo';
            modalityPill.className = 'sens-modality-pill auto';
            modalityPill.style.display = 'inline-flex';
        } else {
            modalityPill.textContent = '–';
            modalityPill.style.display = 'none';
        }
    }

    if (durationPill) {
        durationPill.textContent = `~${details.totalKcal} kcal | ~${details.estMinutes} min`;
    }

    // 4. Carrusel Heroico en Inicio: Videos Exclusivos de Nico (100% MP4s Editados de VIDEOS-NICO)
    dashWorkoutCarouselSlides = getHomeHeroNicoSlides(exercises, athId);
    dashWorkoutCarouselIndex = 0;
    dashWorkoutCarouselDetails = details;
    dashWorkoutCarouselDate = selectedDate;
    dashWorkoutCarouselAthId = athId;

    renderDashWorkoutCarouselExercise(0);
    initDashWorkoutCarouselInteractions();
    if (typeof updateHomeCardsStreakPills === 'function') {
        updateHomeCardsStreakPills(selectedDate, athId);
    }
}

