function getHomeHeroNicoSlides(exercises, athId) {
    if (!Array.isArray(exercises) || exercises.length === 0) {
        return [{
            muscleKey: 'piernas',
            title: 'Entrenamiento del Día',
            subtitle: 'Preparación y técnica biomecánica',
            videoPath: 'EJERCICIOS/exercises-final/videos/VIDEOS-NICO/aad15275-4bb0-4459-a180-6c9f5dbe6d95_peso-muerto-rumano-con-mancuernas.mp4'
        }];
    }

    const detectedMuscles = new Map();
    exercises.forEach(ex => {
        const resolved = (typeof window.getResolvedExercise === 'function')
            ? window.getResolvedExercise(ex, athId)
            : ex;
        const tax = (typeof getExerciseTaxonomy === 'function')
            ? getExerciseTaxonomy(resolved)
            : null;

        let m = (tax?.muscleGroup || resolved?.nivel_2_grupo_muscular || resolved?.category || 'piernas').toLowerCase().trim();
        let sub = (tax?.subMuscle || resolved?.nivel_3_submusculo_piernas || '').toLowerCase().trim();

        if (m.includes('pecho') || m.includes('chest') || m.includes('push')) m = 'pecho';
        else if (m.includes('espalda') || m.includes('back') || m.includes('pull')) m = 'espalda';
        else if (m.includes('hombro') || m.includes('shoulder')) m = 'hombros';
        else if (m.includes('bicep') || m.includes('bícep')) m = 'biceps';
        else if (m.includes('tricep') || m.includes('trícep')) m = 'triceps';
        else if (m.includes('abdom') || m.includes('core')) m = 'abdominales';
        else if (m.includes('antebrazo') || m.includes('forearm')) m = 'antebrazos';
        else if (m.includes('lumbar')) m = 'zona_lumbar';
        else if (m.includes('pierna') || m.includes('leg') || m.includes('glute') || m.includes('quad')) m = 'piernas';
        else m = 'piernas';

        if (!detectedMuscles.has(m)) {
            detectedMuscles.set(m, { count: 0, subMuscles: new Set() });
        }
        const data = detectedMuscles.get(m);
        data.count++;
        if (sub) data.subMuscles.add(sub);
    });

    const slides = [];
    detectedMuscles.forEach((data, muscleKey) => {
        const candidates = SENS_NICO_HERO_VIDEOS[muscleKey] || SENS_NICO_HERO_VIDEOS.piernas;

        if (muscleKey === 'piernas' && data.subMuscles.size > 1) {
            const hasQuads = data.subMuscles.has('cuadriceps');
            const hasPosterior = data.subMuscles.has('isquios') || data.subMuscles.has('gluteos');

            if (hasQuads) {
                const vid = candidates.find(c => c.file.includes('sentadilla') || c.file.includes('prensa')) || candidates[0];
                slides.push({
                    muscleKey: 'cuadriceps',
                    title: 'Cuádriceps & Tren Inferior',
                    subtitle: `${data.count} ejercicios en sesión • ${vid.subtitle}`,
                    videoPath: `EJERCICIOS/exercises-final/videos/VIDEOS-NICO/${vid.file}`
                });
            }
            if (hasPosterior) {
                const vid = candidates.find(c => c.file.includes('peso-muerto') || c.file.includes('hip-thrust')) || candidates[1];
                slides.push({
                    muscleKey: 'gluteos_isquios',
                    title: 'Glúteos & Cadena Posterior',
                    subtitle: `${data.count} ejercicios en sesión • ${vid.subtitle}`,
                    videoPath: `EJERCICIOS/exercises-final/videos/VIDEOS-NICO/${vid.file}`
                });
            }
            return;
        }

        const selectedVid = candidates[0];
        slides.push({
            muscleKey,
            title: selectedVid.title,
            subtitle: `${data.count} ejercicio${data.count > 1 ? 's' : ''} en sesión • ${selectedVid.subtitle}`,
            videoPath: `EJERCICIOS/exercises-final/videos/VIDEOS-NICO/${selectedVid.file}`
        });
    });

    return slides.length > 0 ? slides : [{
        muscleKey: 'piernas',
        title: 'Entrenamiento del Día',
        subtitle: `${exercises.length} ejercicios prescriptos`,
        videoPath: 'EJERCICIOS/exercises-final/videos/VIDEOS-NICO/aad15275-4bb0-4459-a180-6c9f5dbe6d95_peso-muerto-rumano-con-mancuernas.mp4'
    }];
}

/**
 * Renderiza el grupo muscular / video de Nico activo en el carrusel del Dashboard
 */
function renderDashWorkoutCarouselExercise(index) {
    if (!dashWorkoutCarouselSlides || dashWorkoutCarouselSlides.length === 0) return;
    dashWorkoutCarouselIndex = (index + dashWorkoutCarouselSlides.length) % dashWorkoutCarouselSlides.length;
    const slide = dashWorkoutCarouselSlides[dashWorkoutCarouselIndex];
    const sDate = dashWorkoutCarouselDate || new Date();
    const isToday = isSameDay(sDate, new Date());

    const videoPlayer = document.getElementById('dashWorkoutVideoPlayer');
    const videoSource = document.getElementById('dashWorkoutVideoSource');
    const videoSkeleton = document.getElementById('dashWorkoutVideoSkeleton');
    const dayDateLabel = document.getElementById('dashWorkoutDayDateLabel');
    const focusTitle = document.getElementById('dashWorkoutFocusTitle');
    const subFocus = document.getElementById('dashWorkoutSubFocus');
    const dotsContainer = document.getElementById('dashWorkoutDotsIndicator');
    const navArrows = document.getElementById('dashWorkoutNavArrows');

    // 1. Visibilidad de Flechas & Paginador de Puntos (Solo si hay múltiples grupos en el día)
    if (navArrows) {
        navArrows.style.display = dashWorkoutCarouselSlides.length > 1 ? 'flex' : 'none';
    }
    if (dotsContainer) {
        if (dashWorkoutCarouselSlides.length > 1) {
            dotsContainer.innerHTML = dashWorkoutCarouselSlides.map((s, i) =>
                `<span class="sens-video-dot ${i === dashWorkoutCarouselIndex ? 'active' : ''}" data-idx="${i}" title="${s.title}"></span>`
            ).join('');
        } else {
            dotsContainer.innerHTML = '';
        }
    }

    // 2. Video de Nico (Siempre MP4 editado de alta calidad desde VIDEOS-NICO)
    const targetVideo = slide.videoPath;
    if (videoPlayer && videoSource) {
        const currentSrc = videoSource.getAttribute('src');
        if (currentSrc !== targetVideo) {
            if (videoSkeleton) videoSkeleton.classList.remove('is-hidden');
            videoSource.setAttribute('src', targetVideo);
            videoPlayer.load();
            videoPlayer.play().catch(() => {});
        }
        if (typeof attachVideoSkeleton === 'function') {
            attachVideoSkeleton(videoPlayer, videoSkeleton);
        }
    }

    // 3. Sincronizar Textos y Foco Muscular en el Hero de Inicio
    if (dayDateLabel) {
        if (dashWorkoutCarouselSlides.length > 1) {
            dayDateLabel.textContent = isToday
                ? `Entrenamiento de Hoy • Grupo ${dashWorkoutCarouselIndex + 1}/${dashWorkoutCarouselSlides.length}`
                : `Entrenamiento • Grupo ${dashWorkoutCarouselIndex + 1}/${dashWorkoutCarouselSlides.length}`;
        } else {
            dayDateLabel.textContent = isToday ? 'Entrenamiento de Hoy' : `Entrenamiento del ${formatDateDDMM(sDate)}`;
        }
    }
    if (focusTitle) focusTitle.textContent = slide.title;
    if (subFocus) subFocus.textContent = slide.subtitle;
}

/**
 * Inicializa los eventos táctiles y de botones para el carrusel de video de entrenamiento
 */
function initDashWorkoutCarouselInteractions() {
    const card = document.getElementById('dashTrainingVideoCard');
    const prevBtn = document.getElementById('dashPrevExBtn');
    const nextBtn = document.getElementById('dashNextExBtn');
    const dotsContainer = document.getElementById('dashWorkoutDotsIndicator');
    if (!card) return;

    if (prevBtn && !prevBtn._hasCarouselBound) {
        prevBtn._hasCarouselBound = true;
        prevBtn.addEventListener('click', (e) => {
            e.stopPropagation();
            e.preventDefault();
            renderDashWorkoutCarouselExercise(dashWorkoutCarouselIndex - 1);
        });
    }

    if (nextBtn && !nextBtn._hasCarouselBound) {
        nextBtn._hasCarouselBound = true;
        nextBtn.addEventListener('click', (e) => {
            e.stopPropagation();
            e.preventDefault();
            renderDashWorkoutCarouselExercise(dashWorkoutCarouselIndex + 1);
        });
    }

    if (dotsContainer && !dotsContainer._hasCarouselBound) {
        dotsContainer._hasCarouselBound = true;
        dotsContainer.addEventListener('click', (e) => {
            const dot = e.target.closest('.sens-video-dot');
            if (dot) {
                e.stopPropagation();
                e.preventDefault();
                const idx = parseInt(dot.getAttribute('data-idx'), 10);
                if (!isNaN(idx)) renderDashWorkoutCarouselExercise(idx);
            }
        });
    }

    // Soporte de Swipe Táctil Ergonomía Mobile-First (Thumb Zone)
    if (!card._hasSwipeBound) {
        card._hasSwipeBound = true;
        let touchStartX = 0;
        let touchStartY = 0;
        let touchStartTime = 0;

        card.addEventListener('touchstart', (e) => {
            if (!e.touches || e.touches.length === 0) return;
            touchStartX = e.touches[0].clientX;
            touchStartY = e.touches[0].clientY;
            touchStartTime = Date.now();
        }, { passive: true });

        card.addEventListener('touchend', (e) => {
            if (!e.changedTouches || e.changedTouches.length === 0) return;
            const deltaX = e.changedTouches[0].clientX - touchStartX;
            const deltaY = e.changedTouches[0].clientY - touchStartY;
            const deltaTime = Date.now() - touchStartTime;

            // Swipe horizontal genuino
            if (Math.abs(deltaX) > 40 && Math.abs(deltaX) > Math.abs(deltaY) * 1.3 && deltaTime < 650) {
                window._dashWorkoutWasSwipe = true;
                setTimeout(() => { window._dashWorkoutWasSwipe = false; }, 350);

                if (deltaX < 0) {
                    renderDashWorkoutCarouselExercise(dashWorkoutCarouselIndex + 1);
                } else {
                    renderDashWorkoutCarouselExercise(dashWorkoutCarouselIndex - 1);
                }
            }
        }, { passive: true });
    }
}

// Exponer alias global para compatibilidad
window.updateDashboardWorkoutDirective = updateDynamicTrainingCard;
window.getWorkoutSessionDetails = getWorkoutSessionDetails;


/**
 * Actualiza la Card Nutricional con calorías por comida y objetivo biológico de Nico/Atleta
 */
function updateNutriSummaryCardData() {
    const targetBadge = document.getElementById('dashNutriTargetBadge');
    const goalPill = document.getElementById('dashNutriGoalPill');
    const subText = document.getElementById('dashNutriSubText');
    const nutriDayLabel = document.getElementById('dashNutriDayDateLabel');
    const caloriesHero = document.getElementById('dashNutriCaloriesHero');
    const calDesayuno = document.getElementById('calMealDesayuno');
    const calAlmuerzo = document.getElementById('calMealAlmuerzo');
    const calMerienda = document.getElementById('calMealMerienda');
    const calCena = document.getElementById('calMealCena');
    const calSnack = document.getElementById('calMealSnack');

    const profile = AppState.profile || {};
    const anamnesis = AppState.anamnesis || {};
    const athId = getActiveAthleteId();
    const isDemo = (athId === 'usr-vip-001' || athId === 'mock_vip');
    const selectedDate = AppState.selectedDate || new Date();
    const isToday = isSameDay(selectedDate, new Date());

    // 1. Obtener plan nutricional del Coach OS (prioridad máxima)
    let userPlan = null;
    try {
        const raw = localStorage.getItem(`sens_prescribed_nutrition_${athId}`) ||
                    localStorage.getItem(`sens_coach_assigned_nutrition_${athId}`);
        if (raw) userPlan = JSON.parse(raw);
    } catch (e) {}
    if (!userPlan && profile.prescribed_nutrition) {
        userPlan = profile.prescribed_nutrition;
    }

    // Eyebrow dinámico de Nutrición
    if (nutriDayLabel) {
        nutriDayLabel.textContent = isToday ? 'Nutrición de Hoy' : `Nutrición del ${formatDateDDMM(selectedDate)}`;
    }

    // 2. Objetivo Biológico del Atleta (SENS Brandbook / Nico Coach)
    const userGoal = userPlan?.goal || profile.goal || anamnesis.goal || 'fat_loss';
    if (goalPill) {
        const goalLabels = {
            fat_loss: 'Déficit Calórico',
            muscle_gain: 'Superávit Hipertrofia',
            recomp: 'Recomposición Magra',
            posture_health: 'Salud Postural'
        };
        goalPill.textContent = goalLabels[userGoal] || 'Nutrición SENS';
    }

    // 3. Resolución Robusta de Calorías Objetivo (Coach -> Perfil -> Anamnesis -> TDEE Mifflin-St Jeor)
    let targetKcal = 0;
    if (userPlan && userPlan.target_calories) {
        targetKcal = parseInt(userPlan.target_calories, 10);
    } else if (profile.daily_calories) {
        targetKcal = parseInt(profile.daily_calories, 10);
    } else if (anamnesis.daily_calories) {
        targetKcal = parseInt(anamnesis.daily_calories, 10);
    }

    // Si aún no está configurado, calcular científicamente con Mifflin-St Jeor
    if (!targetKcal || targetKcal <= 0) {
        const weightVal = parseFloat(profile.current_weight || anamnesis.weight || 75.0);
        const heightVal = parseFloat(profile.height || anamnesis.height || 175.0);
        const ageVal = parseInt(profile.age || anamnesis.age || 30, 10);
        const genderVal = profile.gender || anamnesis.gender || 'male';

        let bmr = (10 * weightVal) + (6.25 * heightVal) - (5 * ageVal);
        bmr += (genderVal === 'female' ? -161 : 5);
        const tdee = Math.round(bmr * 1.55);

        if (userGoal === 'fat_loss') targetKcal = Math.round(tdee - 450);
        else if (userGoal === 'muscle_gain') targetKcal = Math.round(tdee + 350);
        else targetKcal = Math.round(tdee);
    }

    // 4. Proteínas y Carbohidratos Recomendados
    const weightRaw = profile.current_weight || anamnesis.weight;
    const currentWeight = weightRaw ? parseFloat(weightRaw) : (isDemo ? 75.8 : 75.0);
    const recProtein = userPlan?.macros?.protein || (profile.target_protein ? Math.round(profile.target_protein) : Math.round(Math.max(130, currentWeight * 2.0)));
    const recCarbs = userPlan?.macros?.carbs || (profile.target_carbs ? Math.round(profile.target_carbs) : Math.round((targetKcal * 0.40) / 4));

    if (targetBadge) {
        targetBadge.textContent = `${recProtein}g Prot • ${recCarbs}g Carbs`;
    }

    // 5. Título Hero y Subtítulo
    if (caloriesHero) {
        caloriesHero.textContent = `${targetKcal.toLocaleString('es-AR')} kcal Totales`;
    }

    if (subText) {
        const goalSubtexts = {
            fat_loss: 'Déficit calórico estructurado para preservar masa muscular',
            muscle_gain: 'Superávit calórico calibrado para máxima síntesis proteica',
            recomp: 'Aporte óptimo para recomposición magra y rendimiento',
            posture_health: 'Plan antiinflamatorio para longevidad y vitalidad'
        };
        subText.textContent = userPlan?.directive_note || goalSubtexts[userGoal] || 'Plan calibrado por Nico para síntesis proteica & energía';
    }

    // 6. Determinar día de la semana y calcular calorías reales por comida
    const dayOfWeek = selectedDate.getDay(); // 0: Dom, 1: Lun, 2: Mar, ...
    const dayKey = dayOfWeek === 0 ? 'day7' : `day${dayOfWeek}`;
    const dayMeals = userPlan?.days?.[dayKey]?.meals || userPlan?.days?.['day1']?.meals || {};

    const getMealKcal = (mealKey, defaultPct) => {
        const foods = dayMeals[mealKey];
        if (Array.isArray(foods) && foods.length > 0) {
            const sum = foods.reduce((acc, f) => acc + (f.calories || 0), 0);
            if (sum > 0) return Math.round(sum);
        }
        return Math.round(targetKcal * defaultPct);
    };

    if (calDesayuno) calDesayuno.textContent = `${getMealKcal('desayuno', 0.20)} kcal`;
    if (calAlmuerzo) calAlmuerzo.textContent = `${getMealKcal('almuerzo', 0.35)} kcal`;
    if (calMerienda) calMerienda.textContent = `${getMealKcal('merienda', 0.15)} kcal`;
    if (calCena) calCena.textContent = `${getMealKcal('cena', 0.20)} kcal`;
    if (calSnack) calSnack.textContent = `${getMealKcal('snack', 0.10)} kcal`;

    // 7. Lanzar Carrusel Dinámico 4:5 con Rotación de Comidas y Alimentos Oficiales
    if (typeof initDashNutriCarousel === 'function') {
        initDashNutriCarousel();
    }

    if (typeof updateHomeCardsStreakPills === 'function') {
        updateHomeCardsStreakPills(AppState.selectedDate || new Date(), athId);
    }
}

let dashNutriCarouselTimer = null;
let dashNutriCurrentMealIndex = 0;
let dashNutriMealsData = [];

/**
 * Carrusel Rotativo Automático 4:5 de Nutrición (Quiet Luxury / Senior UX Standards)
 * Alterna suavemente cada 2.5s entre las 5 ingestas del día (Desayuno, Almuerzo, Merienda, Cena, Snack).
 * Muestra la imagen HD real del primer alimento prescrito (o fallback de SENS_FOOD_LIBRARY),
 * resalta la pill correspondiente con sus calorías y sincroniza el copy editorial.
 */
function initDashNutriCarousel() {
    const card = document.getElementById('dashNutriSummaryCard');
    const imgA = document.getElementById('dashNutriFoodImageA');
    const imgB = document.getElementById('dashNutriFoodImageB');
    const chipsRow = document.getElementById('dashNutri5calsRow');
    if (!card || !imgA || !imgB) return;

    // Obtener plan de nutrición prescrito del alumno activo
    const athId = (typeof getActiveAthleteId === 'function') ? getActiveAthleteId() : 'mock_vip';
    let userPlan = null;
    try {
        const raw = localStorage.getItem(`sens_prescribed_nutrition_${athId}`) ||
                    localStorage.getItem(`sens_coach_assigned_nutrition_${athId}`);
        if (raw) userPlan = JSON.parse(raw);
    } catch (e) {}

    // Si no está en localStorage, intentar de AppState.profile
    if (!userPlan && AppState?.profile?.prescribed_nutrition) {
        userPlan = AppState.profile.prescribed_nutrition;
    }

    // Determinar día de la semana para nutrición (day1 = Lunes ... day7 = Domingo)
    const selectedDate = AppState.selectedDate || new Date();
    const dayOfWeek = selectedDate.getDay(); // 0: Dom, 1: Lun, 2: Mar, ...
    const dayKey = dayOfWeek === 0 ? 'day7' : `day${dayOfWeek}`;
    const dayMeals = userPlan?.days?.[dayKey]?.meals || userPlan?.days?.['day1']?.meals || {};

    const mealKeys = ['desayuno', 'almuerzo', 'merienda', 'cena', 'snack'];
    const mealLabels = {
        desayuno: 'Desayuno',
        almuerzo: 'Almuerzo',
        merienda: 'Merienda',
        cena: 'Cena',
        snack: 'Snack'
    };

    // Alimentos representativos base de la Master DB de 500 alimentos si la comida aún no tiene prescripción
    const fallbackFoodByMeal = {
        desayuno: {
            name: 'Huevo Entero de Gallina (Poché o Duro)',
            image: 'Nutricion/images/nut-002-huevo-entero-de-gallina.webp',
            portion: '2 unidades (100g)',
            protein: 26,
            carbs: 2,
            fats: 19
        },
        almuerzo: {
            name: 'Pechuga de Pollo a la Plancha',
            image: 'Nutricion/images/nut-001-pechuga-de-pollo-a-la-plancha.webp',
            portion: '180g con Arroz Integral',
            protein: 46,
            carbs: 45,
            fats: 6
        },
        merienda: {
            name: 'Yogur Griego Natural sin Azúcar',
            image: 'Nutricion/images/nut-017-yogur-griego-natural-sin-azucar.webp',
            portion: '170g con Frutos Secos',
            protein: 20,
            carbs: 18,
            fats: 8
        },
        cena: {
            name: 'Salmón Rosado a la Plancha',
            image: 'Nutricion/images/nut-010-salmon-rosado-trucha-salmonada-a-la-plancha.webp',
            portion: '180g con Vegetales Asados',
            protein: 38,
            carbs: 12,
            fats: 16
        },
        snack: {
            name: 'Almendras o Nueces Naturales',
            image: 'Nutricion/images/nut-042-almendras-o-nueces-naturales.webp',
            portion: '30g (1 puñado)',
            protein: 7,
            carbs: 6,
            fats: 18
        }
    };

    // Estructurar array de 5 ingestas
    dashNutriMealsData = mealKeys.map(key => {
        const mealFoods = dayMeals[key] || [];
        const firstFood = mealFoods.length > 0 ? mealFoods[0] : null;
        let foodName = '';
        let foodImage = '';
        let foodPortion = '';
        let foodProt = 0;
        let foodCarbs = 0;
        let foodFats = 0;

        if (firstFood) {
            const resolved = (typeof window.getResolvedFood === 'function')
                ? window.getResolvedFood(firstFood, athId)
                : firstFood;
            foodName = firstFood.name || resolved?.name || resolved?.name_es || 'Alimento SENS';
            foodImage = resolved?.image || resolved?.image_url || resolved?.imagen_path || firstFood.image || '';
            foodPortion = firstFood.grams ? `${firstFood.grams}g` : (resolved?.portion || '1 porción');
            foodProt = firstFood.protein || resolved?.protPer100 || 25;
            foodCarbs = firstFood.carbs || resolved?.carbsPer100 || 20;
            foodFats = firstFood.fats || resolved?.fatsPer100 || 10;
        }

        const fallback = fallbackFoodByMeal[key];
        if (!foodImage) {
            foodName = fallback.name;
            foodImage = fallback.image;
            foodPortion = fallback.portion;
            foodProt = fallback.protein;
            foodCarbs = fallback.carbs;
            foodFats = fallback.fats;
        }

        const calEl = document.getElementById(`calMeal${key.charAt(0).toUpperCase() + key.slice(1)}`);
        const mealKcal = calEl ? parseInt(calEl.textContent, 10) || 0 : 0;

        return {
            key,
            label: mealLabels[key],
            foodName,
            foodImage,
            foodPortion,
            foodProt: Math.round(foodProt),
            foodCarbs: Math.round(foodCarbs),
            foodFats: Math.round(foodFats),
            mealKcal
        };
    });

    const dotsWrap = document.getElementById('dashNutriDotsIndicator');
    if (dotsWrap) {
        dotsWrap.innerHTML = dashNutriMealsData.map((_, i) => `<span class="sens-video-dot ${i === dashNutriCurrentMealIndex ? 'active' : ''}" data-nutri-idx="${i}"></span>`).join('');
        dotsWrap.querySelectorAll('.sens-video-dot').forEach(dot => {
            dot.addEventListener('click', (e) => {
                e.stopPropagation();
                const idx = parseInt(dot.getAttribute('data-nutri-idx'), 10);
                if (!isNaN(idx)) {
                    showMeal(idx);
                    stopTimer();
                    setTimeout(startTimer, 4500);
                }
            });
        });
    }

    const prevBtn = document.getElementById('dashPrevNutriBtn');
    const nextBtn = document.getElementById('dashNextNutriBtn');
    if (prevBtn && !prevBtn._hasNutriNavBound) {
        prevBtn._hasNutriNavBound = true;
        prevBtn.addEventListener('click', (e) => {
            e.stopPropagation();
            showMeal(dashNutriCurrentMealIndex - 1);
            stopTimer();
            setTimeout(startTimer, 4500);
        });
    }
    if (nextBtn && !nextBtn._hasNutriNavBound) {
        nextBtn._hasNutriNavBound = true;
        nextBtn.addEventListener('click', (e) => {
            e.stopPropagation();
            showMeal(dashNutriCurrentMealIndex + 1);
            stopTimer();
            setTimeout(startTimer, 4500);
        });
    }

    function showMeal(index, instant = false) {
        if (!dashNutriMealsData || dashNutriMealsData.length === 0) return;
        dashNutriCurrentMealIndex = (index + dashNutriMealsData.length) % dashNutriMealsData.length;
        const item = dashNutriMealsData[dashNutriCurrentMealIndex];
        if (!item) return;

        // 1. Cross-fade suave entre capas A y B
        const showingA = imgA.classList.contains('active');
        const activeImg = showingA ? imgA : imgB;
        const nextImg = showingA ? imgB : imgA;

        nextImg.src = item.foodImage;
        nextImg.onerror = () => {
            nextImg.src = fallbackFoodByMeal[item.key]?.image || 'Nutricion/images/nut-001-pechuga-de-pollo-a-la-plancha.webp';
        };

        if (instant) {
            nextImg.classList.add('active');
            activeImg.classList.remove('active');
        } else {
            requestAnimationFrame(() => {
                nextImg.classList.add('active');
                activeImg.classList.remove('active');
            });
        }

        // 2. Resaltar pill en la fila de 5 comidas
        document.querySelectorAll('#dashNutri5calsRow .sens-5cals-chip').forEach(chip => {
            const isMatch = chip.getAttribute('data-meal-key') === item.key;
            chip.classList.toggle('highlight', isMatch);
        });

        // 3. Actualizar dots indicadores (Item 1)
        if (dotsWrap) {
            dotsWrap.querySelectorAll('.sens-video-dot').forEach((dot, i) => {
                dot.classList.toggle('active', i === dashNutriCurrentMealIndex);
            });
        }

        // 4. Sincronizar textos y métricas editoriales
        const eyebrow = document.getElementById('dashNutriDayDateLabel');
        const caloriesHero = document.getElementById('dashNutriCaloriesHero');
        const subText = document.getElementById('dashNutriSubText');
        const targetBadge = document.getElementById('dashNutriTargetBadge');

        const sDate = AppState.selectedDate || new Date();
        const isToday = isSameDay(sDate, new Date());

        if (eyebrow) {
            eyebrow.textContent = isToday ? `Nutrición de Hoy • ${item.label}` : `Nutrición • ${item.label}`;
        }
        if (caloriesHero) {
            caloriesHero.textContent = `${item.label} • ${item.mealKcal > 0 ? item.mealKcal.toLocaleString('es-AR') + ' kcal' : 'Nutrición SENS'}`;
        }
        if (subText) {
            subText.textContent = `${item.foodName} (${item.foodPortion}) • ${item.foodProt}g Prot`;
        }
        if (targetBadge && item.foodProt > 0) {
            targetBadge.textContent = `${item.foodProt}g Prot • ${item.foodCarbs}g Carbs`;
        }
    }

    function startTimer() {
        stopTimer();
        if (document.hidden) return;
        const dashViewEl = document.getElementById('dashView');
        if (dashViewEl && !dashViewEl.classList.contains('active')) return;
        dashNutriCarouselTimer = setInterval(() => {
            if (document.hidden) return;
            const dv = document.getElementById('dashView');
            if (dv && !dv.classList.contains('active')) {
                stopTimer();
                return;
            }
            showMeal(dashNutriCurrentMealIndex + 1);
        }, 4200);
    }

    function stopTimer() {
        if (dashNutriCarouselTimer) {
            clearInterval(dashNutriCarouselTimer);
            dashNutriCarouselTimer = null;
        }
    }
    window.stopDashNutriCarousel = stopTimer;
    window.startDashNutriCarousel = startTimer;

    // Interacción al clickear cada pill de comida
    if (chipsRow && !chipsRow._hasNutriCarouselBound) {
        chipsRow._hasNutriCarouselBound = true;
        chipsRow.addEventListener('click', (e) => {
            const chip = e.target.closest('.sens-5cals-chip');
            if (!chip) return;
            e.stopPropagation();
            const mealKey = chip.getAttribute('data-meal-key');
            const targetIdx = dashNutriMealsData.findIndex(m => m.key === mealKey);
            if (targetIdx !== -1) {
                showMeal(targetIdx);
                stopTimer();
                setTimeout(startTimer, 5000);
            }
        });
    }

    // Soporte de Swipe Táctil Mobile-First & Thumb Zone (Item 1)
    if (!card._hasNutriSwipeBound) {
        card._hasNutriSwipeBound = true;
        let touchStartX = 0;
        let touchStartY = 0;
        let touchStartTime = 0;

        card.addEventListener('touchstart', (e) => {
            if (!e.touches || e.touches.length === 0) return;
            touchStartX = e.touches[0].clientX;
            touchStartY = e.touches[0].clientY;
            touchStartTime = Date.now();
            stopTimer();
        }, { passive: true });

        card.addEventListener('touchend', (e) => {
            if (!e.changedTouches || e.changedTouches.length === 0) return;
            const deltaX = e.changedTouches[0].clientX - touchStartX;
            const deltaY = e.changedTouches[0].clientY - touchStartY;
            const deltaTime = Date.now() - touchStartTime;

            // Swipe horizontal genuino
            if (Math.abs(deltaX) > 40 && Math.abs(deltaX) > Math.abs(deltaY) * 1.3 && deltaTime < 650) {
                window._dashNutriWasSwipe = true;
                setTimeout(() => { window._dashNutriWasSwipe = false; }, 350);

                if (deltaX < 0) {
                    showMeal(dashNutriCurrentMealIndex + 1);
                } else {
                    showMeal(dashNutriCurrentMealIndex - 1);
                }
            }
            setTimeout(startTimer, 3500);
        }, { passive: true });
    }

    // Pausar en hover
    if (!card._hasNutriHoverBound) {
        card._hasNutriHoverBound = true;
        card.addEventListener('mouseenter', stopTimer);
        card.addEventListener('mouseleave', startTimer);
    }

    // Iniciar con la primera comida (Desayuno) y activar rotador
    showMeal(0, true);
    startTimer();
}

window.initDashNutriCarousel = initDashNutriCarousel;

// =============================================================================
// ACTIVIDAD DIARIA, METABOLISMO & RACHA SENS (QUIET LUXURY GAMIFICATION)
// =============================================================================
const SENS_ACTIVITY_STORAGE_PREFIX = 'sens_daily_activity_v2';
const SENS_STREAK_STORAGE_PREFIX = 'sens_streak_completed_v1';

function getFormattedDateKey(d) {
    if (!d) d = new Date();
    if (typeof d === 'string') {
        if (d.includes('T')) return d.split('T')[0];
        return d;
    }
    const year = d.getFullYear();
    const month = String(d.getMonth() + 1).padStart(2, '0');
    const day = String(d.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
}
window.getFormattedDateKey = getFormattedDateKey;

function getAthleteActivityLog(athId, dateKey) {
    try {
        const raw = localStorage.getItem(`${SENS_ACTIVITY_STORAGE_PREFIX}_${athId}`);
        if (raw) {
            const parsed = JSON.parse(raw);
            if (parsed && parsed[dateKey]) {
                return parsed[dateKey];
            }
        }
    } catch (e) {}
    // De entrada marca 0: El usuario debe completar y guardar para activar el balance
    return {
        steps: 0,
        cardioMinutes: 0,
        cardioType: 'caminata',
        cardioRate: 6.5,
        isLogged: false
    };
}

function saveAthleteActivityLog(athId, dateKey, data) {
    try {
        let store = {};
        const raw = localStorage.getItem(`${SENS_ACTIVITY_STORAGE_PREFIX}_${athId}`);
        if (raw) store = JSON.parse(raw) || {};
        store[dateKey] = {
            steps: Number(data.steps) || 0,
            cardioMinutes: Number(data.cardioMinutes) || 0,
            cardioType: data.cardioType || 'caminata',
            cardioRate: Number(data.cardioRate) || 6.5,
            isLogged: true,
            savedAt: new Date().toISOString()
        };
        localStorage.setItem(`${SENS_ACTIVITY_STORAGE_PREFIX}_${athId}`, JSON.stringify(store));
    } catch (e) {}
}
window.saveAthleteActivityLog = saveAthleteActivityLog;
window.getAthleteActivityLog = getAthleteActivityLog;

/**
 * =============================================================================
 * SENS DAILY STREAK ENGINE — TELEMETRÍA OBJETIVA & GAMIFICACIÓN QUIET LUXURY
 * =============================================================================
 * Reglas Estrictas:
 * 1. La racha es diaria y diferenciada por fecha (YYYY-MM-DD).
 * 2. Solo está activa la de hoy o días anteriores.
 * 3. Entrenamiento: Solo se activa si completó el 100% de los ejercicios de la sesión (o descanso activo).
 * 4. Nutrición: Se activa si las calorías consumidas están entre -20% y +10% del objetivo.
 *    Si supera el +10%, el usuario pierde la racha diaria.
 * 5. Pasos y Cardio: Se activa al registrar en Balance Energético al menos 10.000 pasos,
 *    90 min de caminata o 30 min de otro cardio.
 * 6. En días anteriores sin cumplir, se muestra cruz (✕).
 * 7. La racha NO se puede completar tocando la racha; solo se gana ejecutando objetivos.
 */

const SensDailyStreakManager = {
    STORAGE_PREFIX: 'sens_streak_daily_records_v3',

    getStorageKey(athId) {
        const id = athId || (typeof getActiveAthleteId === 'function' ? getActiveAthleteId() : 'mock_vip');
        return `${this.STORAGE_PREFIX}_${id}`;
    },

    getAllRecords(athId) {
        try {
            const raw = localStorage.getItem(this.getStorageKey(athId));
            return raw ? JSON.parse(raw) : {};
        } catch (e) {
            return {};
        }
    },

    saveAllRecords(athId, records) {
        try {
            localStorage.setItem(this.getStorageKey(athId), JSON.stringify(records));
        } catch (e) {}
    },

    evaluateDay(targetDate = new Date(), athId = null) {
        const id = athId || (typeof getActiveAthleteId === 'function' ? getActiveAthleteId() : 'mock_vip');
        const sDate = (targetDate instanceof Date) ? targetDate : new Date(targetDate);
        const dateIso = `${sDate.getFullYear()}-${String(sDate.getMonth() + 1).padStart(2, '0')}-${String(sDate.getDate()).padStart(2, '0')}`;
        const dayKey = (typeof getDayKeyFromDate === 'function') ? getDayKeyFromDate(sDate) : 'day1';

        const today = new Date();
        today.setHours(0, 0, 0, 0);
        const targetMidnight = new Date(sDate);
        targetMidnight.setHours(0, 0, 0, 0);
        const isPastDay = targetMidnight < today;
        const isFutureDay = targetMidnight > today;

        if (isFutureDay) {
            return {
                current: {
                    workout: { done: false, metric: 'Sesión Programada', isRestDay: false, completedExercises: 0, totalExercises: 0 },
                    nutrition: { done: false, status: 'pending', consumed: 0, target: 1950, metric: '0 / 1.950 kcal' },
                    cardio: { done: false, steps: 0, cardioMinutes: 0, cardioType: 'caminata', metric: '0 pasos' },
                    completedCount: 0,
                    isQualified: false,
                    isFuture: true,
                    locked: true,
                    updatedAt: Date.now()
                },
                previous: null
            };
        }

        const records = this.getAllRecords(id);
        const existingRecord = records[dateIso];

        // REGLA DE INMUTABILIDAD HISTÓRICA (Item 3):
        // Una vez finalizado el día (días pasados), la racha queda sellada e inmutable (locked: true).
        // Se pueden editar pesos o comidas retroactivas, pero el estado de la racha de ese día permanece congelado.
        if (isPastDay && existingRecord && existingRecord.locked) {
            const execution = getAthleteWorkoutExecution(id, sDate);
            const hasRealExecution = Boolean(execution && (execution.completed || execution.attended === true));
            if (!hasRealExecution && existingRecord.workout && existingRecord.workout.done && !existingRecord.workout.isRestDay) {
                // Registro corrupto por plantilla antigua: forzar re-evaluación limpia
            } else {
                return {
                    current: existingRecord,
                    previous: existingRecord
                };
            }
        }

        // 1. EVALUAR PILAR ENTRENAMIENTO (Scoping estricto por fecha)
        let workoutDone = false;
        let workoutMetric = 'Sesión Programada';
        let isRestDay = false;
        let totalExercises = 0;
        let completedExercises = 0;

        const execution = getAthleteWorkoutExecution(id, sDate);
        const workoutData = (typeof getCoachAthleteWorkoutData === 'function') ? getCoachAthleteWorkoutData(id) : null;
        let dayWorkout = null;
        if (workoutData && workoutData[dayKey]) {
            dayWorkout = workoutData[dayKey];
        } else if (workoutData && workoutData.calendar_schedule && workoutData.calendar_schedule[dateIso]) {
            dayWorkout = workoutData.calendar_schedule[dateIso];
        } else if (typeof WORKOUT_DAYS_DATA !== 'undefined' && WORKOUT_DAYS_DATA[dayKey]) {
            dayWorkout = WORKOUT_DAYS_DATA[dayKey];
        }

        if (dayWorkout) {
            isRestDay = (dayWorkout.modality === 'descanso');
            if (Array.isArray(dayWorkout.exercises) && dayWorkout.exercises.length > 0) {
                totalExercises = dayWorkout.exercises.length;
                if (execution && execution.completedExercises) {
                    completedExercises = dayWorkout.exercises.filter(e => execution.completedExercises[e.id]).length;
                } else if (execution && execution.completed) {
                    completedExercises = totalExercises;
                }
            }
        }

        if (execution && execution.completed) {
            workoutDone = true;
            workoutMetric = 'Sesión Completada';
            if (completedExercises === 0 && totalExercises > 0) completedExercises = totalExercises;
        } else if (totalExercises > 0 && completedExercises === totalExercises) {
            workoutDone = true;
            workoutMetric = '100% Completado';
        } else if (isRestDay) {
            // Un día de descanso en el pasado solo califica si el usuario tuvo actividad o nutrición ese día
            const hasAnyActivity = Boolean((execution && execution.attended !== null) || (execution && execution.completed));
            if (!isPastDay || hasAnyActivity) {
                workoutDone = true;
                workoutMetric = 'Descanso Activo';
            } else {
                workoutDone = false;
                workoutMetric = 'Descanso (Sin registro)';
            }
        } else if (totalExercises > 0) {
            workoutMetric = `${completedExercises} de ${totalExercises} Ejercicios`;
        }

        if (!workoutDone && typeof isDateInCompletedWorkouts === 'function' && isDateInCompletedWorkouts(dateIso)) {
            workoutDone = true;
            workoutMetric = 'Sesión Completada';
            if (totalExercises === 0) {
                totalExercises = 5;
                completedExercises = 5;
            }
        }

        // 2. EVALUAR PILAR NUTRICIÓN
        // Rango de racha: -20% a +10% del objetivo recomendado. Superar +10% = pérdida de racha.
        let nutriDone = false;
        let nutriStatus = 'pending'; // 'pending' | 'on_track' | 'exceeded'
        let targetCals = 1950;
        let consumedCals = 0;

        if (typeof getAthletePrescribedCalories === 'function') {
            targetCals = getAthletePrescribedCalories(id, sDate);
        } else if (AppState.profile?.prescribed_nutrition?.target_calories) {
            targetCals = parseInt(AppState.profile.prescribed_nutrition.target_calories, 10);
        } else if (AppState.profile?.daily_calories) {
            targetCals = parseInt(AppState.profile.daily_calories, 10);
        }

        if (typeof getAthleteConsumedCalories === 'function') {
            consumedCals = getAthleteConsumedCalories(id, sDate);
        } else {
            const rawCals = localStorage.getItem(`sens_cals_${dateIso}`);
            if (rawCals !== null) {
                consumedCals = parseInt(rawCals, 10) || 0;
            } else if (isSameDay(sDate, new Date()) && AppState.dailyNutrition?.calories) {
                consumedCals = parseInt(AppState.dailyNutrition.calories, 10) || 0;
            }
        }

        const minTarget = Math.round(targetCals * 0.80);
        const maxTarget = Math.round(targetCals * 1.10);

        if (consumedCals >= minTarget && consumedCals <= maxTarget) {
            nutriDone = true;
            nutriStatus = 'on_track';
        } else if (consumedCals > maxTarget) {
            nutriDone = false;
            nutriStatus = 'exceeded';
        } else {
            nutriDone = false;
            nutriStatus = 'pending';
        }

        const nutriMetric = `${consumedCals.toLocaleString('es-AR')} / ${targetCals.toLocaleString('es-AR')} kcal`;

        // 3. EVALUAR PILAR PASOS & CARDIO
        // Mínimo 10.000 pasos ó 90 min de caminata ó 30 min de otro cardio
        let cardioDone = false;
        let steps = 0;
        let cardioMinutes = 0;
        let cardioType = 'caminata';

        const actLog = (typeof getAthleteActivityLog === 'function') ? getAthleteActivityLog(id, dateIso) : null;
        if (actLog) {
            steps = Number(actLog.steps) || 0;
            cardioMinutes = Number(actLog.cardioMinutes) || 0;
            cardioType = actLog.cardioType || 'caminata';
        }

        if (steps >= 10000 || (cardioType === 'caminata' && cardioMinutes >= 90) || (cardioType !== 'caminata' && cardioMinutes >= 30)) {
            cardioDone = true;
        }
        const cardioMetric = `${steps.toLocaleString('es-AR')} pasos • ${cardioMinutes}m ${cardioType}`;

        const completedCount = (workoutDone ? 1 : 0) + (nutriDone ? 1 : 0) + (cardioDone ? 1 : 0);
        const isQualified = (completedCount >= 1);

        // Motivos detallados si la racha no se logró (Item 2)
        const missedReasons = [];
        if (!workoutDone) {
            if (workoutMetric.includes('de')) {
                missedReasons.push({
                    pillar: 'Entrenamiento',
                    detail: `Faltaron ejercicios: Solo completaste ${workoutMetric}.`
                });
            } else {
                missedReasons.push({
                    pillar: 'Entrenamiento',
                    detail: `No se completó la sesión prescripta de fuerza del día.`
                });
            }
        }
        if (!nutriDone) {
            if (nutriStatus === 'exceeded') {
                missedReasons.push({
                    pillar: 'Nutrición',
                    detail: `Exceso calórico: ${consumedCals.toLocaleString('es-AR')} kcal consumidas (+10% del objetivo de ${targetCals.toLocaleString('es-AR')} kcal).`
                });
            } else if (consumedCals === 0) {
                missedReasons.push({
                    pillar: 'Nutrición',
                    detail: `Sin registro de comidas para este día.`
                });
            } else {
                missedReasons.push({
                    pillar: 'Nutrición',
                    detail: `Calorías insuficientes: ${consumedCals.toLocaleString('es-AR')} kcal (debajo del rango mínimo de ${minTarget.toLocaleString('es-AR')} kcal).`
                });
            }
        }
        if (!cardioDone) {
            missedReasons.push({
                pillar: 'Pasos & Cardio',
                detail: `Actividad insuficiente: ${steps.toLocaleString('es-AR')} pasos (mínimo: 10.000 pasos ó 90m caminata / 30m cardio).`
            });
        }

        const previous = records[dateIso] || null;

        records[dateIso] = {
            workout: { done: workoutDone, metric: workoutMetric, isRestDay, completedExercises, totalExercises },
            nutrition: { done: nutriDone, status: nutriStatus, consumed: consumedCals, target: targetCals, metric: nutriMetric },
            cardio: { done: cardioDone, steps, cardioMinutes, cardioType, metric: cardioMetric },
            completedCount,
            isQualified,
            missedReasons,
            locked: isPastDay,
            updatedAt: Date.now()
        };
        this.saveAllRecords(id, records);

        return {
            current: records[dateIso],
            previous
        };
    },

    calculateStreak(athId = null) {
        const id = athId || (typeof getActiveAthleteId === 'function' ? getActiveAthleteId() : 'mock_vip');
        const records = this.getAllRecords(id);
        const today = new Date();
        today.setHours(0, 0, 0, 0);

        const todayIso = `${today.getFullYear()}-${String(today.getMonth() + 1).padStart(2, '0')}-${String(today.getDate()).padStart(2, '0')}`;
        const todayRec = records[todayIso];

        let streak = 0;
        let checkDate = new Date(today);

        if (todayRec && todayRec.isQualified) {
            streak = 1;
            checkDate.setDate(checkDate.getDate() - 1);
        } else {
            checkDate.setDate(checkDate.getDate() - 1);
        }

        for (let i = 0; i < 90; i++) {
            const iso = `${checkDate.getFullYear()}-${String(checkDate.getMonth() + 1).padStart(2, '0')}-${String(checkDate.getDate()).padStart(2, '0')}`;
            const rec = records[iso];
            if (rec && rec.isQualified) {
                streak++;
                checkDate.setDate(checkDate.getDate() - 1);
            } else {
                break;
            }
        }

        return streak;
    }
};

window.SensDailyStreakManager = SensDailyStreakManager;

/**
 * Muestra el detalle contextual de por qué no se completó la racha en un día (Item 2)
 */
window.showStreakMissedDetail = function(dateIso = null) {
    const athId = (typeof getActiveAthleteId === 'function') ? getActiveAthleteId() : 'mock_vip';
    const sDate = dateIso ? new Date(dateIso + 'T12:00:00') : (AppState.selectedDate || new Date());
    const iso = dateIso || `${sDate.getFullYear()}-${String(sDate.getMonth() + 1).padStart(2, '0')}-${String(sDate.getDate()).padStart(2, '0')}`;

    const evalResult = SensDailyStreakManager.evaluateDay(sDate, athId);
    const rec = evalResult.current;
    const box = document.getElementById('sensStreakMissedDetailBox');
    const titleEl = document.getElementById('sensStreakMissedDateTitle');
    const listEl = document.getElementById('sensStreakMissedReasonsList');
    const tipEl = document.getElementById('sensStreakMissedCoachingTip');

    if (!box || !listEl) return;

    const dayName = sDate.toLocaleDateString('es-AR', { weekday: 'long', day: 'numeric', month: 'long' });
    const capitalizedDay = dayName.charAt(0).toUpperCase() + dayName.slice(1);

    if (rec.isQualified) {
        if (titleEl) titleEl.textContent = `${capitalizedDay} • Racha Activa (${rec.completedCount} / 3)`;
        titleEl.style.color = '#10B981';
        listEl.innerHTML = `
            <div style="font-size: 12px; color: #10B981; font-weight: 700; padding: 4px 0;">
                ✓ ¡Racha asegurada! Cumpliste con tus hábitos biológicos programados.
            </div>
        `;
        if (tipEl) tipEl.textContent = '"La disciplina consistente es el único atajo comprobado a la recomposición y longevidad celular."';
    } else {
        if (titleEl) titleEl.textContent = `${capitalizedDay} • Racha no alcanzada`;
        titleEl.style.color = '#F87171';

        const reasons = (rec.missedReasons && rec.missedReasons.length > 0) ? rec.missedReasons : [
            { pillar: 'Objetivos', detail: 'No se completaron todos los requisitos del día.' }
        ];

        listEl.innerHTML = reasons.map(r => `
            <div class="sens-missed-reason-item">
                <span class="sens-missed-cross-badge">✕</span>
                <div>
                    <strong style="color: #F87171;">${r.pillar}:</strong>
                    <span>${r.detail}</span>
                </div>
            </div>
        `).join('') + (rec.locked ? `<div style="font-size: 10px; color: #A1A1AA; margin-top: 6px;">Día finalizado e inmutable. Podés editar cargas y comidas pasadas, pero la racha permanece sellada.</div>` : '');

        if (tipEl) tipEl.textContent = '"Un día no define tu metabolismo. Enfocate en clavar tu rutina y rango de calorías de hoy para reactivar el fuego."';
    }

    box.style.display = 'block';
    box.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
};

window.closeStreakMissedDetail = function() {
    const box = document.getElementById('sensStreakMissedDetailBox');
    if (box) box.style.display = 'none';
};

function renderStreakWeeklyDots(targetDate) {
    const wrap = document.getElementById('sensStreakDotsWrap');
    if (!wrap) return;

    if (!AppState.activeWeekStart) {
        AppState.activeWeekStart = getMonday(new Date());
    }

    const dayLabels = ['L', 'M', 'M', 'J', 'V', 'S', 'D'];
    const today = new Date();
    today.setHours(0, 0, 0, 0);

    const athId = getActiveAthleteId();
    const records = SensDailyStreakManager.getAllRecords(athId);

    let html = '';
    for (let i = 0; i < 7; i++) {
        const d = new Date(AppState.activeWeekStart);
        d.setDate(AppState.activeWeekStart.getDate() + i);
        d.setHours(0, 0, 0, 0);
        const dIso = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;

        const isToday = isSameDay(d, today);
        const isPast = d < today;
        const isFuture = d > today;

        let rec = records[dIso];
        if (!rec && !isFuture) {
            rec = SensDailyStreakManager.evaluateDay(d, athId).current;
        }

        const isDone = Boolean(rec && rec.isQualified);

        let dotHtml = '';
        if (isFuture) {
            dotHtml = `<div class="sens-streak-dot-ring future" title="${dayLabels[i]} ${d.getDate()}: Planificado"></div>`;
        } else if (isPast) {
            if (isDone) {
                dotHtml = `<div class="sens-streak-dot-ring done" onclick="window.showStreakMissedDetail('${dIso}')" title="${dayLabels[i]} ${d.getDate()}: Objetivos cumplidos (Tocar para ver)">✓</div>`;
            } else {
                dotHtml = `<div class="sens-streak-dot-ring missed" onclick="window.showStreakMissedDetail('${dIso}')" title="${dayLabels[i]} ${d.getDate()}: Racha no alcanzada (Tocar para ver por qué)">✕</div>`;
            }
        } else {
            // Hoy
            if (isDone) {
                dotHtml = `<div class="sens-streak-dot-ring done today" onclick="window.showStreakMissedDetail('${dIso}')" title="Hoy: Racha activa">✓</div>`;
            } else {
                dotHtml = `<div class="sens-streak-dot-ring today" onclick="window.showStreakMissedDetail('${dIso}')" title="Hoy: En progreso (Tocar para ver)"></div>`;
            }
        }

        html += `
            <div class="sens-streak-day-dot-unit" onclick="window.showStreakMissedDetail('${dIso}')">
                <span class="sens-streak-dot-name" style="${isToday ? 'color: #E5CBA7; font-weight: 800;' : ''}">${dayLabels[i]}</span>
                ${dotHtml}
            </div>
        `;
    }

    wrap.innerHTML = html;
}

/**
 * Sincroniza en tiempo real toda la telemetría de racha, pilares y pills contextuales
 * de las 3 cards principales (Entrenamiento, Nutrición, Balance / Pasos)
 */
function syncAllStreakAndPillTelemetry(targetDate = null) {
    const d = targetDate || AppState.selectedDate || new Date();
    const athId = (typeof getActiveAthleteId === 'function') ? getActiveAthleteId() : 'mock_vip';

    // 1. Re-evaluar estado de racha del día
    let evalResult = null;
    if (typeof SensDailyStreakManager !== 'undefined') {
        evalResult = SensDailyStreakManager.evaluateDay(d, athId);
    }

    // 2. Actualizar la card heroica de racha y los 3 pilares
    if (typeof updateSensStreakCard === 'function') {
        updateSensStreakCard(d);
    }

    // 3. Actualizar los pills contextuales en las cards de Inicio (Training, Nutrición, Balance)
    if (typeof updateHomeCardsStreakPills === 'function') {
        updateHomeCardsStreakPills(d, athId);
    }

    // 4. Actualizar Balance Energético si está activo
    if (typeof updateObjectiveCardData === 'function') {
        updateObjectiveCardData(d);
    }

    // 5. Actualizar card dinámica de entrenamiento
    if (typeof updateDynamicTrainingCard === 'function') {
        updateDynamicTrainingCard(d);
    }

    // 6. Actualizar Módulo de Rachas & Recompensas Desbloqueables (Presupuesto Social de Fin de Semana)
    if (typeof window.renderSensUnlockablesModule === 'function') {
        window.renderSensUnlockablesModule();
    }

    return evalResult;
}
window.syncAllStreakAndPillTelemetry = syncAllStreakAndPillTelemetry;

function updateSensStreakCard(targetDate = null) {
    if (!targetDate) targetDate = AppState.selectedDate || new Date();
    const athId = getActiveAthleteId();
    
    const evalResult = SensDailyStreakManager.evaluateDay(targetDate, athId);
    const dayRec = evalResult.current;

    // Actualizar UI de los 3 Pilares
    // 1. Entrenamiento
    const chkWorkout = document.getElementById('pillarChkWorkout');
    const pillWorkout = document.getElementById('pillarPillWorkout');
    const metricWorkout = document.getElementById('pillarMetricWorkout');
    const wDone = dayRec.workout.done;
    if (chkWorkout) chkWorkout.className = `sens-pillar-chk ${wDone ? 'done' : ''}`;
    if (pillWorkout) {
        pillWorkout.className = `sens-pillar-pill ${wDone ? 'done' : ''}`;
        pillWorkout.textContent = wDone ? (dayRec.workout.isRestDay ? 'Descanso' : 'Completado') : 'Pendiente';
    }
    if (metricWorkout) {
        metricWorkout.textContent = dayRec.workout.metric;
    }

    // 2. Nutrición
    const chkNutri = document.getElementById('pillarChkNutrition');
    const pillNutri = document.getElementById('pillarPillNutrition');
    const metricNutri = document.getElementById('pillarMetricNutrition');
    const nDone = dayRec.nutrition.done;
    const nExceeded = (dayRec.nutrition.status === 'exceeded');
    if (chkNutri) chkNutri.className = `sens-pillar-chk ${nDone ? 'done' : ''}`;
    if (pillNutri) {
        pillNutri.className = `sens-pillar-pill ${nDone ? 'done' : (nExceeded ? 'exceeded' : '')}`;
        pillNutri.textContent = nDone ? 'En rango' : (nExceeded ? 'Perdida (+10%)' : 'Pendiente');
    }
    if (metricNutri) {
        metricNutri.textContent = dayRec.nutrition.metric;
    }

    // 3. Pasos & Cardio
    const chkAct = document.getElementById('pillarChkActivity');
    const pillAct = document.getElementById('pillarPillActivity');
    const metricAct = document.getElementById('pillarMetricActivity');
    const cDone = dayRec.cardio.done;
    if (chkAct) chkAct.className = `sens-pillar-chk ${cDone ? 'done' : ''}`;
    if (pillAct) {
        pillAct.className = `sens-pillar-pill ${cDone ? 'done' : ''}`;
        pillAct.textContent = cDone ? 'Cumplido' : 'Pendiente';
    }
    if (metricAct) {
        metricAct.textContent = dayRec.cardio.metric;
    }

    // Ratio
    const ratioEl = document.getElementById('sensPillarsRatio');
    if (ratioEl) ratioEl.textContent = `${dayRec.completedCount} de 3 completados`;

    // Racha Hero, Nivel & Status Pill
    const streakNum = document.getElementById('sensStreakHeroNum');
    const streakSub = document.getElementById('sensStreakSubText');
    const streakStatusPill = document.getElementById('sensStreakStatusPill');
    const streakLevelTag = document.getElementById('sensStreakLevelTag');
    const flameIcon = document.getElementById('sensStreakFlameIcon');

    const streakDays = SensDailyStreakManager.calculateStreak(athId);
    const levelInfo = (typeof SensGamification !== 'undefined' && SensGamification.getStreakLevel)
        ? SensGamification.getStreakLevel(streakDays)
        : { level: 1, title: 'Semilla del Hábito' };

    if (streakNum) streakNum.textContent = streakDays;
    if (streakLevelTag) streakLevelTag.textContent = `Nivel ${levelInfo.level} • ${levelInfo.title}`;
    if (flameIcon) flameIcon.classList.toggle('active-glow', streakDays > 0);

    const today = new Date();
    today.setHours(0, 0, 0, 0);
    const sDate = (targetDate instanceof Date) ? targetDate : new Date(targetDate);
    sDate.setHours(0, 0, 0, 0);
    const isPast = sDate < today;

    if (streakStatusPill) {
        if (dayRec.completedCount === 3) {
            streakStatusPill.className = 'sens-streak-status-pill perfect';
            streakStatusPill.textContent = 'Día Perfecto 100%';
        } else if (dayRec.completedCount >= 1) {
            streakStatusPill.className = 'sens-streak-status-pill';
            streakStatusPill.textContent = 'Racha Activa';
        } else if (isPast) {
            streakStatusPill.className = 'sens-streak-status-pill lost';
            streakStatusPill.textContent = 'Racha no alcanzada';
        } else {
            streakStatusPill.className = 'sens-streak-status-pill';
            streakStatusPill.textContent = 'En progreso';
        }
    }

    if (streakSub) {
        if (dayRec.completedCount === 3) {
            streakSub.textContent = '¡Día 100% completado! Racha perfecta asegurada.';
            streakSub.style.color = '#10B981';
        } else if (dayRec.completedCount >= 1) {
            streakSub.textContent = `${dayRec.completedCount} de 3 objetivos cumplidos • ¡Seguí sumando hábitos hoy!`;
            streakSub.style.color = '#E5CBA7';
        } else if (isPast) {
            streakSub.textContent = 'Día finalizado sin cumplir objetivos. Tocá ✕ para ver el detalle.';
            streakSub.style.color = '#F87171';
        } else {
            streakSub.textContent = 'Completá tus objetivos de hoy para mantener la racha activa.';
            streakSub.style.color = '#A1A1AA';
        }
    }

    // Botón para cerrar detalle
    const closeMissedBtn = document.getElementById('btnCloseStreakMissedDetail');
    if (closeMissedBtn && !closeMissedBtn._hasCloseMissedBound) {
        closeMissedBtn._hasCloseMissedBound = true;
        closeMissedBtn.addEventListener('click', window.closeStreakMissedDetail);
    }

    renderStreakWeeklyDots(targetDate);
    updateHomeCardsStreakPills(targetDate, athId);
}

