// Evaluador y Renderizador del Módulo de Rachas & Recompensas Desbloqueables (Dashboard + Nutrición)
window.renderSensUnlockablesModule = function() {
    const dashGrid = document.getElementById('dashUnlockablesCardsGrid');
    const nutriGrid = document.getElementById('nutriUnlockablesCardsGrid');
    if (!dashGrid && !nutriGrid) return;

    const athId = (typeof getActiveAthleteId === 'function') ? getActiveAthleteId() : 'local_user';
    const profile = AppState.profile || {};

    // Contar sesiones de entrenamiento completadas en la semana en curso e históricas
    let weeklyCompleted = parseInt(profile.weekly_workouts_completed || 0, 10);
    let totalCompleted = 0;

    try {
        const storedDates = JSON.parse(localStorage.getItem('sens_completed_workout_dates') || '[]');
        if (Array.isArray(storedDates)) {
            totalCompleted = Math.max(totalCompleted, storedDates.length);
            const mon = getMonday(new Date());
            const sun = new Date(mon);
            sun.setDate(mon.getDate() + 6);
            sun.setHours(23, 59, 59, 999);
            const weekMatches = storedDates.filter(iso => {
                const d = new Date(iso + 'T12:00:00');
                return d >= mon && d <= sun;
            });
            weeklyCompleted = Math.max(weeklyCompleted, weekMatches.length);
        }
    } catch (_) {}

    if (typeof SensDailyStreakManager !== 'undefined') {
        try {
            const recs = SensDailyStreakManager.getAllRecords(athId) || {};
            const mon = getMonday(new Date());
            let recWeekCount = 0;
            let recTotalCount = 0;
            Object.keys(recs).forEach(iso => {
                const r = recs[iso];
                if (r && r.workout && r.workout.done && !r.workout.isRestDay) {
                    recTotalCount++;
                    const d = new Date(iso + 'T12:00:00');
                    if (d >= mon) recWeekCount++;
                }
            });
            weeklyCompleted = Math.max(weeklyCompleted, recWeekCount);
            totalCompleted = Math.max(totalCompleted, recTotalCount);
        } catch (_) {}
    }

    const unlockedOfficeProtocol = totalCompleted >= 1;
    const unlockedWeekendRefeed = Boolean(profile.weekend_refeed_unlocked) || weeklyCompleted >= 3;
    const unlockedCriterio3Days = Boolean(profile.onboarding_completed && totalCompleted >= 3);

    // Si acaba de alcanzar las 3 sesiones en su primera semana, otorgar +3 días extra localmente (idempotente)
    if (unlockedCriterio3Days && AppState.profile && !localStorage.getItem(`sens_criterio_3d_awarded_${athId}`)) {
        try {
            localStorage.setItem(`sens_criterio_3d_awarded_${athId}`, 'true');
            const currentEnd = AppState.profile.trial_ends_at ? new Date(AppState.profile.trial_ends_at) : new Date(Date.now() + 7 * 86400000);
            const extendedEnd = new Date(Math.max(currentEnd.getTime(), Date.now()) + 3 * 86400000);
            AppState.profile.trial_ends_at = extendedEnd.toISOString();
            localStorage.setItem('sens_active_profile', JSON.stringify(AppState.profile));
        } catch (_) {}
    }

    const progressText = `${Math.min(3, weeklyCompleted)} / 3 sesiones esta sem.`;
    const dashBadge = document.getElementById('dashWeeklySessionsProgressBadge');
    const nutriBadge = document.getElementById('nutriWeeklySessionsProgressBadge');
    if (dashBadge) dashBadge.textContent = progressText;
    if (nutriBadge) nutriBadge.textContent = progressText;

    const lockSvg = `<svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="#71717A" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="11" width="18" height="11" rx="2" ry="2"/><path d="M7 11V7a5 5 0 0 1 10 0v4"/></svg>`;
    const unlockSvg = `<svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="#080809" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"/></svg>`;

    const refCode = profile.referral_code || 'SENS-VIP';
    const referralUrl = `https://makesens.online/?ref=${encodeURIComponent(refCode)}`;

    const cards = [
        {
            key: 'weekend_social_refeed',
            shortLabel: 'Refeed +500 kcal',
            eyebrow: '3 Sesiones / Semana',
            title: 'Permiso Social Fin de Semana (+500 kcal)',
            desc: unlockedWeekendRefeed
                ? 'Activo: Tenés +500 kcal libres para tu cena social del fin de semana manteniendo proteína.'
                : `Te ${Math.max(0, 3 - weeklyCompleted) === 1 ? 'falta 1 sesión' : `faltan ${Math.max(0, 3 - weeklyCompleted)} sesiones`} esta semana para liberar tu margen social de +500 kcal.`,
            unlocked: unlockedWeekendRefeed,
            statusLabel: unlockedWeekendRefeed ? 'DESBLOQUEADO ✓' : `${Math.min(3, weeklyCompleted)}/3 sesiones`,
            ctaText: 'Ver Guía de Cena Social SENS'
        },
        {
            key: 'initial_criterio_3days',
            shortLabel: '+3 Días Gratis',
            eyebrow: 'Premio a la Constancia',
            title: '+3 Días Gratis de App Full',
            desc: unlockedCriterio3Days
                ? '¡Felicitaciones! Sumaste +3 días extra a tu prueba gratuita por cumplir 3 sesiones en la semana.'
                : 'Completá 3 entrenamientos durante tu primera semana de prueba y sumás automáticamente +3 días gratis.',
            unlocked: unlockedCriterio3Days,
            statusLabel: unlockedCriterio3Days ? '+3 DÍAS ACREDITADOS' : `${Math.min(3, totalCompleted)}/3 completados`,
            ctaText: 'Ver Mi Plan y Días Restantes'
        },
        {
            key: 'viral_guest_pass_7days',
            shortLabel: 'Regalar 14d (+7d Vos)',
            eyebrow: 'Growth • Invitar Amigo',
            title: '+7 Días Gratis para Ambos',
            desc: 'Regalale un Pase de 14 Días a un amigo. Cuando complete su 1er entrenamiento, ambos suman +7 días gratis reales en la App.',
            unlocked: true,
            statusLabel: '+7 DÍAS POR AMIGO',
            ctaText: 'Compartir Pase por WhatsApp →'
        }
    ];

    window._sensRewardsCache = cards;

    // Renderizado Compacto en Micro-Chips (Zero Bloat - Foco en Flujo de Inicio)
    const chipsContainer = document.getElementById('dashUnlockablesChipsStrip') || document.getElementById('dashUnlockablesCardsGrid');
    if (chipsContainer) {
        chipsContainer.innerHTML = cards.map(c => `
            <button type="button" class="sens-unlock-micro-chip ${c.unlocked ? 'unlocked' : ''}" onclick="window.openSensRewardDeepDiveSheet('${c.key}')" title="Tocar para ver detalle y beneficios">
                <span class="sens-unlock-chip-icon">
                    ${c.unlocked ? `<svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"/></svg>` : `<svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><rect x="3" y="11" width="18" height="11" rx="2" ry="2"/><path d="M7 11V7a5 5 0 0 1 10 0v4"/></svg>`}
                </span>
                <span>${escapeHTML(c.shortLabel)}</span>
            </button>
        `).join('');
    }

    if (nutriGrid) {
        nutriGrid.innerHTML = chipsContainer ? chipsContainer.innerHTML : '';
    }
};

window.openSensRewardDeepDiveSheet = function(rewardKey) {
    const sheet = document.getElementById('rewardDeepDiveBottomSheet');
    if (!sheet) return;
    const cards = window._sensRewardsCache || [];
    const reward = cards.find(c => c.key === rewardKey) || cards[0];
    if (!reward) return;

    const titleEl = document.getElementById('rewardSheetTitle');
    const eyebrowEl = document.getElementById('rewardSheetEyebrow');
    const descEl = document.getElementById('rewardSheetDesc');
    const statusTag = document.getElementById('rewardSheetStatusTag');
    const actionWrap = document.getElementById('rewardSheetActionContainer');

    if (titleEl) titleEl.textContent = reward.title;
    if (eyebrowEl) eyebrowEl.textContent = reward.eyebrow;
    if (descEl) descEl.textContent = reward.desc;
    if (statusTag) {
        statusTag.textContent = reward.statusLabel;
        statusTag.style.background = reward.unlocked ? 'rgba(16, 185, 129, 0.15)' : 'rgba(255, 255, 255, 0.08)';
        statusTag.style.color = reward.unlocked ? '#34D399' : '#A1A1AA';
    }

    if (actionWrap) {
        const refCode = AppState.profile?.referral_code || 'SENS-VIP';
        const referralUrl = `https://makesens.online/?ref=${encodeURIComponent(refCode)}`;
        if (reward.key === 'viral_guest_pass_7days') {
            actionWrap.innerHTML = `
                <button type="button" class="btn btn-primary btn-full" onclick="window.shareSensReferralCode && window.shareSensReferralCode()" style="padding: 12px; font-weight: 800; font-size: 13px;">
                    Compartir Pase por WhatsApp (+7d para vos) →
                </button>
            `;
        } else if (reward.key === 'weekend_social_refeed') {
            actionWrap.innerHTML = `
                <button type="button" class="btn btn-outline btn-full" onclick="window.closeSensRewardDeepDiveSheet(); if(typeof switchPortalView==='function') switchPortalView('nutritionView');" style="padding: 11px; font-weight: 700; font-size: 12px; border-color: rgba(229,203,167,0.4); color: #E5CBA7;">
                    Ver en Nutrición & Hábitos →
                </button>
            `;
        } else {
            actionWrap.innerHTML = `
                <button type="button" class="btn btn-outline btn-full" onclick="window.closeSensRewardDeepDiveSheet(); window.openSensPlansUpgradeModal && window.openSensPlansUpgradeModal();" style="padding: 11px; font-weight: 700; font-size: 12px; border-color: rgba(229,203,167,0.4); color: #E5CBA7;">
                    Ver Estado de Membresía y Días →
                </button>
            `;
        }
    }

    sheet.classList.add('active');
};

window.closeSensRewardDeepDiveSheet = function() {
    const sheet = document.getElementById('rewardDeepDiveBottomSheet');
    if (sheet) sheet.classList.remove('active');
};

window.shareSensReferralCode = function() {
    const refCode = AppState.profile?.referral_code || 'SENS-VIP';
    const referralUrl = `https://makesens.online/?ref=${encodeURIComponent(refCode)}`;
    try { navigator.clipboard.writeText(referralUrl); } catch (_) {}
    const waMsg = encodeURIComponent(`Hola! Te regalo un Pase de Invitado para entrenar en MAKES SENS. con el método de Nico (fuerza, postura y cálculo nutricional). Registrate con mi link único y cuando completes tu 1er entrenamiento ambos sumamos +7 días gratis: ${referralUrl}`);
    window.open(`https://wa.me/?text=${waMsg}`, '_blank');
};

// =============================================================================
// GOBERNADOR DE ENERGÍA, TÉRMICA Y FLUIDEZ 120Hz (SensBatteryPerfGovernor)
// Arquitectura Senior Director IT: Cero drenaje de batería en idle/background
// =============================================================================
const SensBatteryPerfGovernor = {
    videoObserver: null,
    idleTimer: null,
    IDLE_TIMEOUT_MS: 40000, // 40s sin interacción táctil pausa decodificadores de video decorativos

    init() {
        this.initViewportVideoObserver();
        this.initVisibilityLifecycle();
        this.initIdleBatteryGuard();
    },

    initViewportVideoObserver() {
        if (!('IntersectionObserver' in window)) return;
        this.videoObserver = new IntersectionObserver((entries) => {
            entries.forEach(entry => {
                const video = entry.target;
                if (!video || video.id === 'dashNutriVideoPlayer') return;

                // No reproducir si la pestaña está oculta o si el contenedor padre está oculto
                if (document.hidden || video.offsetParent === null) {
                    if (!video.paused) {
                        try { video.pause(); } catch (_) {}
                    }
                    return;
                }

                if (entry.isIntersecting && entry.intersectionRatio >= 0.35) {
                    if (video.getAttribute('preload') === 'none') {
                        video.setAttribute('preload', 'metadata');
                    }
                    const p = video.play();
                    if (p && typeof p.catch === 'function') p.catch(() => {});
                } else {
                    if (!video.paused) {
                        try { video.pause(); } catch (_) {}
                    }
                }
            });
        }, {
            root: null,
            rootMargin: '40px 0px',
            threshold: [0, 0.35]
        });

        this.observeVideosInContainer(document);
    },

    observeVideosInContainer(container) {
        if (!this.videoObserver || !container) return;
        const videos = container.querySelectorAll('video');
        videos.forEach(v => {
            if (v.id === 'dashNutriVideoPlayer' || v.id === 'mktHiddenSourceVideo') return;
            this.videoObserver.observe(v);
        });
    },

    pauseAllActiveVideos() {
        document.querySelectorAll('video').forEach(v => {
            try { if (!v.paused) v.pause(); } catch (_) {}
        });
    },

    resumeVisibleVideos() {
        if (document.hidden) return;
        document.body.classList.remove('sens-power-save');
        document.querySelectorAll('video').forEach(v => {
            if (v.id === 'dashNutriVideoPlayer' || v.id === 'mktHiddenSourceVideo') return;
            if (v.offsetParent === null) return;
            const rect = v.getBoundingClientRect();
            const vh = window.innerHeight || document.documentElement.clientHeight;
            const vw = window.innerWidth || document.documentElement.clientWidth;
            const isVisible = rect.bottom > 40 && rect.top < (vh - 40) && rect.right > 0 && rect.left < vw;
            if (isVisible) {
                try {
                    const p = v.play();
                    if (p && typeof p.catch === 'function') p.catch(() => {});
                } catch (_) {}
            }
        });
    },

    initVisibilityLifecycle() {
        const onWakeUp = () => {
            if (document.hidden) return;
            this.resetIdleTimer();
            this.resumeVisibleVideos();
            // Sincronizar de inmediato los cronómetros de entrenamiento/descanso con el reloj de hardware (Epoch Date.now())
            if (typeof window.syncMasterTimerWithWallClock === 'function') {
                window.syncMasterTimerWithWallClock();
            }
            if (typeof window.syncWorkoutStopwatchWithWallClock === 'function') {
                window.syncWorkoutStopwatchWithWallClock();
            }
            if (AppState.floatingRestEndAtMs && AppState.activeTimerInterval) {
                const rem = Math.ceil((AppState.floatingRestEndAtMs - Date.now()) / 1000);
                AppState.remainingSeconds = Math.max(0, rem);
                if (AppState.remainingSeconds <= 0) {
                    stopRestTimer();
                    playBeep(880, 0.4);
                    showSensToast('Descanso completado. Preparate para el próximo set.', 'champagne', 3400);
                } else {
                    updateTimerDisplay();
                }
            }
            const dashView = document.getElementById('dashView');
            if (dashView && dashView.classList.contains('active') && typeof window.startDashNutriCarousel === 'function') {
                window.startDashNutriCarousel();
            }
        };

        document.addEventListener('visibilitychange', () => {
            if (document.hidden) {
                document.body.classList.add('sens-power-save');
                this.pauseAllActiveVideos();
                if (typeof window.stopDashNutriCarousel === 'function') window.stopDashNutriCarousel();
                if (typeof window.stopCoachMarketingStudio === 'function') window.stopCoachMarketingStudio();
                if (typeof persistMasterTimerState === 'function') persistMasterTimerState();
            } else {
                onWakeUp();
            }
        });

        window.addEventListener('focus', onWakeUp, { passive: true });
        window.addEventListener('pageshow', onWakeUp, { passive: true });
    },

    resetIdleTimer() {
        if (document.body.classList.contains('sens-power-save') && !document.hidden) {
            document.body.classList.remove('sens-power-save');
            this.resumeVisibleVideos();
        }
        if (this.idleTimer) clearTimeout(this.idleTimer);
        this.idleTimer = setTimeout(() => {
            // Si el usuario deja el celular encendido sobre la mesa sin tocarlo por 40s,
            // congelamos animaciones infinitas y decodificadores de video decorativos
            const modalOpen = document.getElementById('sensExerciseModalBackdrop')?.classList.contains('active');
            if (!modalOpen) {
                document.body.classList.add('sens-power-save');
                this.pauseAllActiveVideos();
                if (typeof window.stopDashNutriCarousel === 'function') window.stopDashNutriCarousel();
            }
        }, this.IDLE_TIMEOUT_MS);
    },

    initIdleBatteryGuard() {
        ['touchstart', 'scroll', 'click', 'keydown'].forEach(evt => {
            window.addEventListener(evt, () => this.resetIdleTimer(), { passive: true });
        });
        this.resetIdleTimer();
    }
};
window.SensBatteryPerfGovernor = SensBatteryPerfGovernor;

if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => {
        try { migrateLegacyWorkoutsInLocalStorage(); } catch (e) {}
        try { initClarityTrainerModule(); } catch (e) {}
        try { CoachWorkoutsMaster.init(); } catch (e) {}
        try { CoachNutritionMaster.init(); } catch (e) {}
        try { CoachEvolutionEngine.init(); } catch (e) {}
        try { SensPwaManager.init(); } catch (e) {}
        try { SensBatteryPerfGovernor.init(); } catch (e) {}
        try { if (typeof window.renderSensUnlockablesModule === 'function') window.renderSensUnlockablesModule(); } catch (e) {}
    });
} else {
    try { migrateLegacyWorkoutsInLocalStorage(); } catch (e) {}
    try { initClarityTrainerModule(); } catch (e) {}
    try { CoachWorkoutsMaster.init(); } catch (e) {}
    try { CoachNutritionMaster.init(); } catch (e) {}
    try { CoachEvolutionEngine.init(); } catch (e) {}
    try { SensPwaManager.init(); } catch (e) {}
    try { SensBatteryPerfGovernor.init(); } catch (e) {}
    try { if (typeof window.renderSensUnlockablesModule === 'function') window.renderSensUnlockablesModule(); } catch (e) {}
}

